import { SubjectLessonMatrix } from './types';

export const ESTATISTICA_LESSON_MATRIX: SubjectLessonMatrix = {
  0: [
    { sub: 'População, Amostra e Censo', ref: 'Estatística Descritiva', t: 'População (ou universo estatístico) é o conjunto completo de todos os elementos que compartilham pelo menos uma característica em comum de interesse da pesquisa, enquanto amostra é qualquer subconjunto finito e representativo extraído dessa população.', f: 'Um levantamento estatístico que coleta dados apenas de 10% dos contribuintes chama-se recenseamento ou censo demográfico.', exp: 'Censo = pesquisa de toda a população; Amostragem = pesquisa de uma parte (amostra) da população.' },
    { sub: 'Classificação das Variáveis: Qualitativas (Nominais e Ordinais) vs. Quantitativas (Discretas e Contínuas)', ref: 'Estatística Descritiva', t: 'As variáveis qualitativas dividem-se em nominais (sem hierarquia intrínseca, como estado civil ou UF) e ordinais (com ordem natural, como grau de instrução); já as quantitativas dividem-se em discretas (provenientes de contagem em conjunto enumerável) e contínuas (provenientes de mensuração em intervalo real).', f: 'O número de filhos de um servidor é uma variável qualitativa nominal, enquanto a cor dos olhos é quantitativa contínua.', exp: 'Número de filhos/autuações = Quantitativa Discreta; Peso/Altura/Renda exata = Quantitativa Contínua.' },
    { sub: 'Frequências Simples (Absoluta e Relativa) e Acumuladas', ref: 'Tabelas de Frequência', t: 'Em uma distribuição de frequências, a soma de todas as frequências absolutas simples ($f_i$) é igual ao tamanho total da amostra ($n$), e a soma de todas as frequências relativas simples ($fr_i = f_i / n$) é sempre igual a $1$ (ou $100\\%$).', f: 'A soma das frequências acumuladas absolutas de todas as classes de uma tabela é sempre igual a 1.', exp: 'A última classe da frequência acumulada ($F_k$) iguala $n$ (ou $100\\%$ na relativa acumulada), mas a soma das acumuladas supera $n$.' },
    { sub: 'Amplitude de Classe e Regra de Sturges', ref: 'Agrupamento em Classes', t: 'Na construção de uma distribuição por intervalos de classe de mesma largura, a amplitude de classe ($h$) é dada pela diferença entre o limite superior e o limite inferior da classe, e o ponto médio ($x_i$) é a semissoma desses limites.', f: 'O ponto médio de um intervalo de classe $10 \\vdash 20$ é obtido multiplicando-se 10 por 20.', exp: 'Ponto médio de $10 \\vdash 20$ é $(10 + 20) / 2 = 15$, e a amplitude de classe é $20 - 10 = 10$.' },
    { sub: 'Representações Gráficas: Histograma, Polígono de Frequências e Ogiva de Galton', ref: 'Gráficos Estatísticos', t: 'O histograma é formado por retângulos contíguos cuja área é proporcional à frequência da classe; o polígono de frequências une os pontos médios dos topos das classes; e a Ogiva de Galton representa graficamente as frequências acumuladas.', f: 'O gráfico de setores (pizza) é a representação oficial obrigatória para determinar graficamente a mediana de variáveis contínuas.', exp: 'A interseção das duas ogivas (acumulada "abaixo de" e "acima de") fornece graficamente a Mediana.' }
  ],
  1: [
    { sub: 'Propriedades da Média Aritmética Simples e Ponderada', ref: 'Medidas de Posição', t: 'A soma algébrica dos desvios de cada observação em relação à própria média aritmética é sempre igual a zero: $\\sum (x_i - \\bar{x}) = 0$; além disso, a soma dos quadrados dos desvios $\\sum (x_i - c)^2$ é mínima quando $c = \\bar{x}$.', f: 'A soma dos desvios simples em relação à média aritmética é sempre igual à variância amostral.', exp: '1ª propriedade fundamental da média: $\\sum (x_i - \\bar{x}) = 0$. 2ª propriedade: $\\sum (x_i - \\bar{x})^2$ é mínimo.' },
    { sub: 'Efeito de Transformação Linear sobre a Média', ref: 'Medidas de Posição', t: 'Se cada valor de um conjunto de dados for multiplicado por uma constante $a$ e acrescido de uma constante $b$ ($Y = aX + b$), a nova média aritmética sofrerá exatamente a mesma transformação linear: $\\bar{Y} = a\\bar{X} + b$.', f: 'Somar uma constante positiva $b$ a todos os salários de uma repartição não altera a média salarial.', exp: 'Medidas de posição (média, mediana, moda, quantis) são afetadas tanto por multiplicação ($a$) quanto por soma/subtração ($b$).' },
    { sub: 'Média Geométrica ($G$)', ref: 'Medidas de Posição', t: 'A média geométrica de $n$ valores positivos é a raiz $n$-ésima do produto desses valores ($G = \\sqrt[n]{x_1 \\cdot x_2 \\cdots x_n}$), sendo a medida adequada para calcular taxas médias de variação ou fatores acumulativos ao longo do tempo.', f: 'A média geométrica de números positivos distintos é sempre estritamente maior que a sua média aritmética.', exp: 'O logaritmo da média geométrica é a média aritmética dos logaritmos dos valores.' },
    { sub: 'Média Harmônica ($H$)', ref: 'Medidas de Posição', t: 'A média harmônica de $n$ valores positivos é o inverso da média aritmética dos inversos dos valores ($H = n / \\sum (1/x_i)$), sendo aplicada em grandezas inversamente proporcionais, como velocidade média em percursos de mesma distância.', f: 'Se um veículo percorre a ida a $60\\text{ km/h}$ e a volta (mesma distância) a $40\\text{ km/h}$, a velocidade média total é de $50\\text{ km/h}$.', exp: 'Para distâncias iguais, usa-se a média harmônica: $H = 2 \\cdot 60 \\cdot 40 / (60 + 40) = 48\\text{ km/h}$ (menor que a média aritmética 50).' },
    { sub: 'Desigualdade das Médias (Cauchy)', ref: 'Medidas de Posição', t: 'Para qualquer conjunto de valores reais positivos não todos iguais entre si, vale sempre a desigualdade estrita: Média Aritmética ($\bar{X}$) > Média Geométrica ($G$) > Média Harmônica ($H$), ocorrendo a igualdade apenas se todos os elementos forem idênticos.', f: 'Para valores positivos distintos, a média harmônica supera sempre a média geométrica e a média aritmética.', exp: 'Relação clássica de prova: $\\bar{X} \\ge G \\ge H$ (com igualdade se e somente se $x_1 = x_2 = \\dots = x_n$).' }
  ],
  2: [
    { sub: 'Conceito de Moda e Classificação Modal', ref: 'Medidas de Posição', t: 'A moda ($Mo$) é o valor que ocorre com a maior frequência em um conjunto de dados; uma distribuição pode ser amodal (nenhum valor se repete mais que outros), unimodal (uma única moda), bimodal (duas modas) ou multimodal.', f: 'Todo conjunto numérico discreto possui obrigatoriamente uma única moda positiva.', exp: 'Ao contrário da média e da mediana (que sempre existem e são únicas), a moda pode não existir (amodal) ou não ser única.' },
    { sub: 'Moda Bruta (Ponto Médio) vs. Moda de Czuber em Dados Agrupados', ref: 'Dados Agrupados em Classes', t: 'Em dados agrupados por intervalos de classe, a classe modal é aquela de maior frequência simples (ou maior densidade de frequência se as amplitudes forem distintas); a Moda Bruta é o ponto médio da classe modal, enquanto a fórmula de Czuber interpola usando os excessos de frequência $\\Delta_1$ e $\\Delta_2$: $Mo = l_{mo} + h \\cdot [\\Delta_1 / (\\Delta_1 + \\Delta_2)]$.', f: 'Pela fórmula de Czuber, a moda depende exclusivamente da frequência acumulada da primeira classe da tabela.', exp: 'Em Czuber: $\\Delta_1 = f_{mo} - f_{ant}$ e $\\Delta_2 = f_{mo} - f_{post}$. Já na fórmula de King: $Mo = l_{mo} + h \\cdot [f_{post} / (f_{ant} + f_{post})]$.' },
    { sub: 'Relação Empírica de Pearson entre Média, Mediana e Moda', ref: 'Assimetria e Posição', t: 'Para distribuições unimodais moderadamente assimétricas, vale a relação empírica aproximada de Karl Pearson: $\\text{Média} - \\text{Moda} \\approx 3 \\cdot (\\text{Média} - \\text{Mediana})$, ou equivalentemente $Mo \\approx 3Md - 2\\bar{X}$.', f: 'Pela relação empírica de Pearson, a média aritmética é sempre igual ao triplo da moda.', exp: 'Isolando a Mediana na fórmula de Pearson: $Md = (2\\bar{X} + Mo) / 3$ (a mediana fica a $1/3$ do caminho da média para a moda).' },
    { sub: 'Posição Relativa de Média, Mediana e Moda na Assimetria', ref: 'Curvas de Frequência', t: 'Em uma distribuição unimodal perfeitamente simétrica, coincidem $\\bar{X} = Md = Mo$; na assimétrica positiva (à direita), tem-se $Mo < Md < \\bar{X}$; e na assimétrica negativa (à esquerda), tem-se $\\bar{X} < Md < Mo$.', f: 'Em uma distribuição fortemente assimétrica à direita (positiva), a moda é sempre maior que a média aritmética.', exp: 'A cauda longa "puxa" a média aritmética: cauda à direita (positiva) -> $\\bar{X} > Md > Mo$; cauda à esquerda (negativa) -> $\\bar{X} < Md < Mo$.' },
    { sub: 'Sensibilidade a Valores Extremos (Outliers)', ref: 'Robustez Estatística', t: 'A média aritmética é altamente sensível a valores discrepantes (outliers), ao passo que a mediana e a moda são medidas de posição robustas, que não se alteram quando o maior valor extremo da série sofre um acréscimo aberrante.', f: 'A moda e a mediana são muito mais influenciadas por valores extremos do que a média aritmética.', exp: 'Por depender apenas da posição central (ou da maior frequência), a mediana (e a moda) resiste a outliers.' }
  ],
  3: [
    { sub: 'Conceito de Mediana em Séries Simples (Rol)', ref: 'Separatrizes', t: 'A mediana ($Md$) é a separatriz que divide o conjunto de dados ordenados (em rol crescente ou decrescente) em duas partes com 50% das observações cada: se $n$ é ímpar, ocupa a posição $(n+1)/2$; se $n$ é par, é a média aritmética dos termos nas posições $n/2$ e $(n/2)+1$.', f: 'Para calcular a mediana de uma série bruta, basta somar o primeiro e o último número sem necessidade de ordenar os dados em rol.', exp: 'Passo obrigatório antes de calcular a mediana ou qualquer quantil em dados brutos: ordenar em ROL!' },
    { sub: 'Interpolação Linear da Mediana em Classes', ref: 'Dados Agrupados', t: 'Em dados agrupados por intervalos de classe, identifica-se a classe mediana pela posição $n/2$ na frequência acumulada e aplica-se a interpolação: $Md = l_{md} + h \\cdot [(n/2 - F_{ant}) / f_{md}]$.', f: 'A mediana em dados agrupados é sempre igual ao limite inferior da primeira classe da tabela.', exp: 'Na fórmula da separatriz em classes, $F_{ant}$ é a frequência acumulada até a classe imediatamente anterior e $f_{md}$ é a frequência simples da classe da separatriz.' },
    { sub: 'Quartis ($Q_1, Q_2, Q_3$), Decis e Percentis', ref: 'Separatrizes', t: 'Os três quartis dividem o rol em 4 partes iguais de 25% ($Q_1 = P_{25}$, $Q_2 = Md = D_5 = P_{50}$, $Q_3 = P_{75}$); os nove decis dividem em 10 partes de 10%; e os noventa e nove percentis (ou centis) dividem em 100 partes de 1%.', f: 'O terceiro quartil ($Q_3$) deixa 25% das observações abaixo dele e 75% acima dele.', exp: '$Q_1$ deixa 25% abaixo e 75% acima; $Q_2$ deixa 50% abaixo; $Q_3$ deixa 75% abaixo e 25% acima.' },
    { sub: 'Amplitude Interquartílica (AIQ) e Diagrama em Caixa (Boxplot)', ref: 'Boxplot e Separatrizes', t: 'No gráfico Boxplot, a caixa central é delimitada pelo primeiro quartil ($Q_1$) e pelo terceiro quartil ($Q_3$), com um traço interno na Mediana ($Q_2$), sendo a altura/largura da caixa denominada Amplitude Interquartílica ($AIQ = Q_3 - Q_1$), que abrange os 50% centrais dos dados.', f: 'A Amplitude Interquartílica corresponde à diferença entre o valor máximo absoluto e o valor mínimo absoluto da amostra.', exp: 'Amplitude Total = Máx - Mín; Amplitude Interquartílica ($AIQ$ ou $DIQ$) = $Q_3 - Q_1$; Amplitude Semi-Interquartílica = $(Q_3 - Q_1)/2$.' },
    { sub: 'Coeficiente de Assimetria Quartílico de Bowley e Curtose Percentílica', ref: 'Assimetria e Curtose por Quantis', t: 'Pelo critério quartílico de Bowley, a distribuição é simétrica se a mediana é equidistante de $Q_1$ e $Q_3$ ($Q_3 - Q_2 = Q_2 - Q_1$); já o coeficiente de curtose percentílico compara a distância semi-interquartílica com a distância entre os percentis $P_{90}$ e $P_{10}$: $K = (Q_3 - Q_1) / [2(P_{90} - P_{10})]$, cujo referencial mesocúrtico (normal) é $0{,}263$.', f: 'Uma curva leptocúrtica (mais afilada que a normal) apresenta coeficiente percentílico de curtose superior a $0{,}50$.', exp: 'Na convenção clássica da FGV ($K = (Q_3 - Q_1)/[2(P_{90} - P_{10})]$): Mesocúrtica $K = 0{,}263$; Leptocúrtica $K < 0{,}263$; Platicúrtica $K > 0{,}263$.' }
  ],
  4: [
    { sub: 'Variância Populacional ($\sigma^2$) vs. Variância Amostral ($s^2$)', ref: 'Medidas de Dispersão', t: 'A variância mede a média dos quadrados dos desvios em torno da média: na população divide-se por $N$ ($\\sigma^2 = \\sum (x_i - \\mu)^2 / N$), enquanto na amostra não viesada divide-se por $n - 1$ graus de liberdade ($s^2 = \\sum (x_i - \\bar{x})^2 / (n - 1)$).', f: 'A variância de um conjunto de números reais negativos assume sempre um valor estritamente negativo.', exp: 'Como soma quadrados de desvios reais, a variância e o desvio-padrão são sempre não negativos ($\\ge 0$), só valendo zero se todos os elementos forem iguais.' },
    { sub: 'Fórmula Operacional (Atalho) da Variância', ref: 'Medidas de Dispersão', t: 'Pela fórmula de cálculo rápido (identidade de König-Huygens), a variância populacional é a média dos quadrados menos o quadrado da média: $\\sigma^2 = [\\sum x_i^2 / N] - \\bar{x}^2$, e na amostra: $s^2 = [\\sum x_i^2 - n\\bar{x}^2] / (n - 1)$.', f: 'A média dos quadrados de uma variável aleatória é sempre menor que o quadrado da sua média aritmética.', exp: 'Como $\\text{Var}(X) = E(X^2) - [E(X)]^2 \\ge 0$, tem-se sempre $E(X^2) \\ge [E(X)]^2$.' },
    { sub: 'Efeito de Transformação Linear sobre Variância e Desvio-Padrão', ref: 'Propriedades da Dispersão', t: 'Somar ou subtrair uma constante $b$ a todos os dados não altera a dispersão; já multiplicar todos os dados por uma constante $a$ ($Y = aX + b$) multiplica o desvio-padrão por $|a|$ ($DP(Y) = |a| \\cdot DP(X)$) e multiplica a variância por $a^2$ ($\\text{Var}(Y) = a^2 \\cdot \\text{Var}(X)$).', f: 'Se somarmos R$ 500,00 ao salário de todos os funcionários, o desvio-padrão salarial aumentará em R$ 500,00.', exp: 'Translação ($+b$) desloca os dados em bloco sem espalhá-los -> Variância e DP ficam inalterados! Escala ($\\times a$) -> $DP \\times |a|$ e $\\text{Var} \\times a^2$.' },
    { sub: 'Coeficiente de Variação de Pearson ($CV$)', ref: 'Dispersão Relativa', t: 'O Coeficiente de Variação ($CV = s / \\bar{x}$) é uma medida de dispersão relativa adimensional (expressa em porcentagem), ideal para comparar a variabilidade de conjuntos com unidades de medida diferentes (ex: peso em kg vs. estatura em cm) ou médias muito distintas.', f: 'O Coeficiente de Variação é expresso na unidade de medida da variável original elevada ao quadrado.', exp: 'Como divide o desvio-padrão (mesma unidade dos dados) pela média (mesma unidade), as unidades se cancelam e o $CV$ é adimensional!' },
    { sub: 'Desvio Médio Absoluto ($DMA$) e Escore Padronizado ($Z$)', ref: 'Dispersão e Padronização', t: 'O Desvio Médio Absoluto é a média aritmética dos módulos dos desvios ($DMA = \\sum |x_i - \\bar{x}| / n$); já o escore padronizado $Z = (x - \\bar{x}) / s$ indica a quantos desvios-padrão uma observação está acima ou abaixo da média, tendo sempre média $0$ e desvio-padrão $1$.', f: 'O escore padronizado $Z$ possui média igual a 100 e variância igual a 10.', exp: 'Qualquer variável padronizada $Z = (X - \\mu)/\\sigma$ tem $E(Z) = 0$ e $\\text{Var}(Z) = 1$.' }
  ],
  5: [
    { sub: 'Princípio Fundamental da Contagem (PFC / Regra do Produto)', ref: 'Análise Combinatória', t: 'Se uma decisão $E_1$ pode ser tomada de $m$ maneiras distintas e, tomada essa decisão, uma segunda decisão independente $E_2$ pode ser tomada de $n$ maneiras, então o número total de maneiras de tomar as decisões em sequência é $m \\times n$.', f: 'Pelo princípio multiplicativo, se há 3 camisas e 4 calças, existem apenas $3 + 4 = 7$ formas de escolher um conjunto de camisa e calça.', exp: 'Conectivo "E" (etapas sucessivas) -> multiplica ($3 \\times 4 = 12$); Conectivo "OU" (alternativas mutuamente exclusivas) -> soma.' },
    { sub: 'Permutação Simples, Circular e com Elementos Repetidos', ref: 'Análise Combinatória', t: 'O número de permutações simples de $n$ elementos distintos é $P_n = n!$; em uma roda (permutação circular), é $PC_n = (n - 1)!$; e quando há repetições de elementos ($\\alpha, \\beta, \\dots$), divide-se pelos fatoriais das repetições: $P_n^{\\alpha, \\beta} = n! / (\\alpha! \\cdot \\beta!)$.', f: 'O número de anagramas da palavra ARARA é igual a $5! = 120$.', exp: 'Em ARARA ($n=5$, com 3 A e 2 R), o total de anagramas é $5! / (3! \\cdot 2!) = 120 / 12 = 10$.' },
    { sub: 'Arranjo Simples vs. Combinação Simples (Importância da Ordem)', ref: 'Análise Combinatória', t: 'Tanto no Arranjo quanto na Combinação escolhem-se $p$ elementos dentre $n$ disponíveis; no Arranjo ($A_{n,p} = n! / (n-p)!$), a ordem dos escolhidos importa (ex: pódio 1º, 2º e 3º lugar ou senhas), enquanto na Combinação ($C_{n,p} = n! / [p!(n-p)!]$), a ordem não importa (ex: formar uma comissão de auditores).', f: 'Para escolher uma comissão de 3 auditores sem cargos definidos dentre 10 disponíveis, deve-se usar a fórmula de Arranjo Simples.', exp: 'Mudou a ordem dos escolhidos e mudou o agrupamento? Arranjo! Mudou a ordem e continua sendo a mesma comissão? Combinação!' },
    { sub: 'Propriedade dos Números Binomiais Complementares', ref: 'Triângulo de Pascal e Combinações', t: 'Dois números binomiais complementares possuem o mesmo valor: $C_{n,p} = C_{n, n-p}$ (escolher $p$ elementos para entrar no grupo equivale a escolher os $n-p$ elementos que ficarão de fora), e a soma de todas as combinações de uma linha de Pascal é $\\sum_{p=0}^n C_{n,p} = 2^n$.', f: 'A soma de todos os subconjuntos possíveis de um conjunto com $n = 5$ elementos é igual a $5^2 = 25$.', exp: 'O total de subconjuntos de um conjunto com $n$ elementos é $2^n$ (para $n=5$, $2^5 = 32$ subconjuntos).' },
    { sub: 'Combinação com Repetição (Soluções Inteiras Não Negativas)', ref: 'Análise Combinatória Avançada', t: 'O número de maneiras de escolher $p$ objetos dentre $n$ tipos disponíveis permitindo repetição (ou o número de soluções inteiras não negativas de $x_1 + x_2 + \\dots + x_n = p$) é dado por $CR_{n,p} = C_{n+p-1, p}$.', f: 'A equação $x + y + z = 4$ admite apenas 3 soluções em números inteiros não negativos.', exp: 'Pela fórmula de combinação completa (traços e bolas): $CR_{3,4} = C_{3+4-1, 4} = C_{6,4} = C_{6,2} = 15$ soluções.' }
  ],
  6: [
    { sub: 'Axiomas de Kolmogorov e Regra da Adição da União', ref: 'Teoria das Probabilidades', t: 'Para quaisquer eventos $A$ e $B$ de um espaço amostral $\\Omega$, tem-se $0 \\le P(A) \\le 1$, $P(\\Omega) = 1$, e a probabilidade da união é dada por $P(A \\cup B) = P(A) + P(B) - P(A \\cap B)$.', f: 'Para quaisquer dois eventos que possuem interseção não vazia, a probabilidade da união é sempre a soma direta $P(A) + P(B)$.', exp: 'Só se soma diretamente $P(A \\cup B) = P(A) + P(B)$ quando $A$ e $B$ são mutuamente exclusivos ($A \\cap B = \\emptyset$).' },
    { sub: 'Eventos Mutuamente Exclusivos vs. Eventos Independentes', ref: 'Teoria das Probabilidades', t: 'Dois eventos $A$ e $B$ são mutuamente exclusivos (disjuntos) quando não podem ocorrer juntos ($P(A \\cap B) = 0$); já dois eventos são estocasticamente independentes quando a ocorrência de um não altera a probabilidade do outro, isto é, $P(A \\cap B) = P(A) \\cdot P(B)$.', f: 'Se dois eventos com probabilidades positivas ($P(A) > 0$ e $P(B) > 0$) são mutuamente exclusivos, então eles são necessariamente independentes.', exp: 'Pegadinha clássica FGV: se $P(A)>0$ e $P(B)>0$, eventos mutuamente exclusivos ($P(A\\cap B)=0$) NUNCA são independentes (pois $P(A)P(B) > 0$)!' },
    { sub: 'Probabilidade Condicional', ref: 'Teoria das Probabilidades', t: 'A probabilidade condicional de ocorrer o evento $A$, dado que o evento $B$ ($P(B) > 0$) já ocorreu, é definida pela razão entre a probabilidade da interseção e a probabilidade do evento condicionante: $P(A | B) = P(A \\cap B) / P(B)$.', f: 'A probabilidade condicional $P(A | B)$ é sempre idêntica à probabilidade condicional inversa $P(B | A)$.', exp: 'O denominador da probabilidade condicional é sempre a probabilidade do evento "dado que" ($P(B)$).' },
    { sub: 'Teorema da Probabilidade Total', ref: 'Probabilidade Condicional', t: 'Se os eventos $B_1, B_2, \\dots, B_k$ formam uma partição do espaço amostral $\\Omega$ (mutuamente exclusivos e cuja união é $\\Omega$), então a probabilidade de um evento qualquer $A$ é a soma ponderada: $P(A) = \\sum P(B_i) \\cdot P(A | B_i)$.', f: 'No teorema da probabilidade total, os eventos da partição devem ter interseção igual a 100%.', exp: 'Cada ramo da árvore de probabilidades contribui com $P(B_i) \\cdot P(A | B_i)$, e a soma de todos os ramos dá $P(A)$.' },
    { sub: 'Teorema de Bayes (Probabilidade a Posteriori)', ref: 'Teorema de Bayes', t: 'O Teorema de Bayes permite atualizar a probabilidade de uma causa $B_j$ dado que o efeito $A$ foi observado: $P(B_j | A) = [P(B_j) \\cdot P(A | B_j)] / [\\sum P(B_i) \\cdot P(A | B_i)]$.', f: 'O Teorema de Bayes aplica-se apenas a variáveis determinísticas sem incerteza.', exp: 'Numerador de Bayes = ramo específico da causa $B_j$ com $A$; Denominador = probabilidade total de $A$ (soma de todos os ramos que levam a $A$).' }
  ],
  7: [
    { sub: 'Função de Probabilidade Discreta e Função de Distribuição Acumulada ($F(x)$)', ref: 'Variáveis Aleatórias Discretas', t: 'Para uma variável aleatória discreta $X$, as probabilidades pontuais satisfazem $p(x_i) \\ge 0$ e $\\sum p(x_i) = 1$; a função de distribuição acumulada $F(x) = P(X \\le x)$ é uma função em escada (passo), não decrescente, contínua à direita, com $\\lim_{x\\to -\\infty} F(x) = 0$ e $\\lim_{x\\to +\\infty} F(x) = 1$.', f: 'Em uma variável aleatória discreta, a função de distribuição acumulada pode diminuir de valor à medida que $x$ cresce.', exp: 'A probabilidade pontual em um salto pode ser recuperada pela diferença: $P(X = x_i) = F(x_i) - F(x_{i-1})$.' },
    { sub: 'Esperança Matemática (Valor Esperado $E(X)$) e Linearidade', ref: 'Esperança Matemática', t: 'O valor esperado de uma variável discreta é $E(X) = \\sum x_i \\cdot p(x_i)$, e o operador esperança é sempre linear: $E(aX + bY + c) = aE(X) + bE(Y) + c$, independentemente de $X$ e $Y$ serem ou não independentes.', f: 'A propriedade $E(X + Y) = E(X) + E(Y)$ só é válida quando as variáveis $X$ e $Y$ são estatisticamente independentes.', exp: 'A esperança da soma é SEMPRE a soma das esperanças! Já a esperança do produto $E(XY) = E(X)E(Y)$ exige independência (covariância nula).' },
    { sub: 'Variância de Variável Aleatória Discreta', ref: 'Variância de V.A.', t: 'A variância de uma variável aleatória $X$ é dada por $\\text{Var}(X) = E[(X - \\mu)^2] = E(X^2) - [E(X)]^2$, onde $E(X^2) = \\sum x_i^2 \\cdot p(x_i)$.', f: 'Para qualquer variável aleatória $X$, tem-se que $\\text{Var}(aX + b) = a \\cdot \\text{Var}(X) + b$.', exp: 'Propriedade fundamental: $\\text{Var}(aX + b) = a^2 \\cdot \\text{Var}(X)$ (a constante somada $b$ desaparece e o fator $a$ sai ao quadrado).' },
    { sub: 'Variância da Soma e da Diferença de Variáveis Independentes', ref: 'Propriedades da Variância', t: 'Se $X$ e $Y$ são variáveis aleatórias independentes (covariância igual a zero), tanto a variância da soma quanto a variância da diferença são iguais à SOMA das variâncias: $\\text{Var}(X + Y) = \\text{Var}(X) + \\text{Var}(Y)$ e $\\text{Var}(X - Y) = \\text{Var}(X) + \\text{Var}(Y)$.', f: 'Se $X$ e $Y$ são independentes com mesma variância $\\sigma^2$, então a variância da diferença $\\text{Var}(X - Y)$ é igual a zero.', exp: 'Cuidado extremo na FGV: como $(-1)^2 = +1$, na diferença de variáveis independentes as variâncias se SOMAM: $\\text{Var}(X - Y) = \\text{Var}(X) + \\text{Var}(Y)$!' },
    { sub: 'Desigualdade de Chebyshev', ref: 'Teorema de Chebyshev', t: 'Para qualquer variável aleatória com média $\\mu$ e desvio-padrão finito $\\sigma$ (qualquer que seja sua distribuição de probabilidade), a probabilidade de um valor distar da média menos de $k$ desvios-padrão ($k > 1$) é no mínimo $1 - 1/k^2$: $P(|X - \\mu| < k\\sigma) \\ge 1 - 1/k^2$.', f: 'A desigualdade de Chebyshev só pode ser aplicada quando a variável segue comprovadamente a distribuição Normal.', exp: 'Chebyshev vale para QUALQUER distribuição! Para $k=2$, no mínimo $1 - 1/4 = 75\\%$ dos dados estão entre $\\mu - 2\\sigma$ e $\\mu + 2\\sigma$.' }
  ],
  8: [
    { sub: 'Ensaio de Bernoulli e Distribuição Binomial $B(n, p)$', ref: 'Distribuições Discretas', t: 'Na distribuição Binomial $X \\sim B(n, p)$, que conta o número de sucessos em $n$ ensaios de Bernoulli independentes com probabilidade constante $p$, tem-se $P(X = k) = C_{n,k} \\cdot p^k \\cdot (1-p)^{n-k}$, média $E(X) = np$ e variância $\\text{Var}(X) = np(1-p)$.', f: 'Em uma distribuição Binomial $B(n, p)$, a variância é sempre estritamente maior que a média $np$.', exp: 'Como $0 < 1-p < 1$, na distribuição Binomial a variância $npq$ é sempre MENOR que a média $np$!' },
    { sub: 'Distribuição de Poisson $P(\\lambda)$', ref: 'Distribuições Discretas', t: 'A distribuição de Poisson modela o número de ocorrências de eventos em um intervalo contínuo de tempo ou espaço à taxa média $\\lambda$, com $P(X = k) = (e^{-\\lambda} \\cdot \\lambda^k) / k!$, possuindo a propriedade característica de que sua média e sua variância são numericamente iguais: $E(X) = \\text{Var}(X) = \\lambda$.', f: 'Na distribuição de Poisson de parâmetro $\\lambda = 4$, a média é 4 e a variância é igual a 16.', exp: 'Na Poisson: Média = Variância = $\\lambda$ (e o desvio-padrão é $\\sqrt{\\lambda}$). Além disso, a soma de Poissons independentes é Poisson ($\\lambda_1 + \\lambda_2$).' },
    { sub: 'Distribuição Hipergeométrica (Amostragem Sem Reposição)', ref: 'Distribuições Discretas', t: 'Enquanto a Binomial pressupõe extrações com reposição (probabilidade constante), a distribuição Hipergeométrica modela o número de sucessos em $n$ extrações SEM reposição de uma população finita $N$ contendo $K$ elementos do tipo desejado: $P(X = k) = (C_{K,k} \\cdot C_{N-K, n-k}) / C_{N,n}$.', f: 'A distribuição Hipergeométrica exige que cada peça sorteada seja devolvida à urna antes do sorteio seguinte.', exp: 'Com reposição -> Binomial; Sem reposição em população finita -> Hipergeométrica.' },
    { sub: 'Distribuição Geométrica e Binomial Negativa (Pascal)', ref: 'Distribuições Discretas', t: 'A distribuição Geométrica modela o número de tentativas independentes até a ocorrência do primeiro sucesso ($P(X = k) = (1-p)^{k-1} \\cdot p$, com média $1/p$ na parametrização de tentativas) e possui a propriedade de perda de memória entre as discretas.', f: 'A distribuição Geométrica possui número fixo de ensaios e conta quantos fracassos ocorrem em uma população sem reposição.', exp: 'A Geométrica é a única distribuição discreta com a propriedade de falta de memória (memoryless).' },
    { sub: 'Aproximação da Binomial pela Poisson (Lei dos Eventos Raros)', ref: 'Aproximações Discretas', t: 'Quando o número de ensaios $n$ é grande e a probabilidade de sucesso $p$ é muito pequena ($p \\to 0$), a distribuição Binomial $B(n, p)$ pode ser aproximada pela distribuição de Poisson com parâmetro $\\lambda = n \\cdot p$.', f: 'A aproximação de Poisson para a Binomial só é válida quando $p = 0{,}50$ e $n = 2$.', exp: 'Para $n$ grande e $p$ pequeno (eventos raros), usa-se Poisson com $\\lambda = np$.' }
  ],
  9: [
    { sub: 'Função Densidade de Probabilidade ($f(x)$) e Probabilidade no Ponto', ref: 'Variáveis Contínuas', t: 'Para uma variável aleatória contínua $X$ com função densidade $f(x) \\ge 0$ e $\\int_{-\\infty}^{+\\infty} f(x)dx = 1$, a probabilidade de $X$ pertencer a $[a, b]$ é a área sob a curva ($\\int_a^b f(x)dx$), e a probabilidade de $X$ assumir qualquer valor isolado exato é sempre zero: $P(X = c) = 0$.', f: 'Em uma variável aleatória contínua, $P(a < X < b)$ é sempre estritamente menor que $P(a \\le X \\le b)$.', exp: 'Como $P(X = a) = P(X = b) = 0$ nas variáveis contínuas, incluir ou excluir as extremidades ($<$ ou $\\le$) não altera a probabilidade!' },
    { sub: 'Distribuição Uniforme Contínua $U[a, b]$', ref: 'Distribuições Contínuas', t: 'Na distribuição Uniforme Contínua no intervalo $[a, b]$, a densidade é constante $f(x) = 1 / (b - a)$, a esperança (e mediana) é o ponto médio $E(X) = (a + b) / 2$, e a variância é $\\text{Var}(X) = (b - a)^2 / 12$.', f: 'Na distribuição Uniforme Contínua em $[0, 6]$, a variância é igual a $(6 - 0) / 2 = 3$.', exp: 'Fórmula muito cobrada pela FGV: na Uniforme $U[a, b]$, $\\text{Var}(X) = (b - a)^2 / 12$. Para $[0, 6]$, $\\text{Var} = 36/12 = 3$ e $E(X) = 3$.' },
    { sub: 'Distribuição Exponencial e Falta de Memória', ref: 'Distribuições Contínuas', t: 'Se o número de ocorrências por unidade de tempo segue Poisson com taxa $\\lambda$, o tempo de espera entre ocorrências segue a distribuição Exponencial ($f(x) = \\lambda e^{-\\lambda x}$ para $x \\ge 0$, $F(x) = 1 - e^{-\\lambda x}$), com média $E(X) = 1/\\lambda$, variância $1/\\lambda^2$ e propriedade de falta de memória ($P(X > s+t | X > s) = P(X > t)$).', f: 'Na distribuição Exponencial de parâmetro $\\lambda = 2$, a média é 2 e a variância é 4.', exp: 'Na Exponencial($\\lambda$): Média = $1/\\lambda$ e Desvio-Padrão = $1/\\lambda$ (logo Variância = $1/\\lambda^2$).' },
    { sub: 'Distribuição Normal (Gaussiana) e Padronização $Z$', ref: 'Distribuição Normal', t: 'A distribuição Normal $X \\sim N(\\mu, \\sigma^2)$ é perfeitamente simétrica em forma de sino (média = mediana = moda = $\\mu$), e qualquer Normal é convertida na Normal Padrão $Z \\sim N(0, 1)$ pela transformação $Z = (X - \\mu) / \\sigma$; na regra empírica, cerca de $68{,}26\\%$ da área está em $\\mu \\pm 1\\sigma$, $95{,}44\\%$ em $\\mu \\pm 2\\sigma$ e $99{,}73\\%$ em $\\mu \\pm 3\\sigma$.', f: 'A combinação linear de duas variáveis normais independentes deixa de ter distribuição Normal.', exp: 'Qualquer combinação linear de variáveis Normais independentes ($aX + bY$) continua tendo distribuição Normal, com média $a\\mu_X + b\\mu_Y$ e variância $a^2\\sigma_X^2 + b^2\\sigma_Y^2$!' },
    { sub: 'Distribuições Amostrais: Qui-Quadrado ($\\chi^2$), $t$ de Student e $F$ de Snedecor', ref: 'Distribuições Derivadas da Normal', t: 'A soma dos quadrados de $k$ normais padrão independentes segue Qui-Quadrado com $k$ graus de liberdade ($\\chi^2_k$, com média $k$ e variância $2k$); a razão $Z / \\sqrt{\\chi^2_k / k}$ segue $t$ de Student com $k$ g.l. (simétrica com caudas mais pesadas que a Normal); e a razão de duas Qui-Quadrado independentes divididas por seus g.l. segue $F$ de Snedecor.', f: 'A distribuição Qui-Quadrado assume valores negativos e tem média igual a zero.', exp: 'Resumo FGV: $\\chi^2_k$ tem média $k$ e variância $2k$ (só assume valores $\\ge 0$); $t_k \\to N(0,1)$ quando $k \\to \\infty$.' }
  ],
  10: [
    { sub: 'Distribuições Marginais e Condicionais de Variáveis Bidimensionais', ref: 'Variáveis Conjuntas', t: 'Dada a distribuição conjunta $P(X = x_i, Y = y_j)$ em uma tabela de dupla entrada, as distribuições marginais de $X$ e de $Y$ são obtidas somando-se as probabilidades ao longo das linhas e das colunas, respectivamente, e a condicional é $P(X = x_i | Y = y_j) = P(X=x_i, Y=y_j) / P(Y=y_j)$.', f: 'Para obter a distribuição marginal de $X$, deve-se multiplicar todas as probabilidades da diagonal principal da tabela.', exp: 'Marginais = totais das linhas e totais das colunas; se para todo par $(x_i, y_j)$ a célula conjunta for igual ao produto das marginais, $X$ e $Y$ são independentes.' },
    { sub: 'Covariância ($\\text{Cov}(X, Y)$) e Fórmula Operacional', ref: 'Covariância', t: 'A covariância mede a direção da associação linear entre duas variáveis e é calculada por $\\text{Cov}(X, Y) = E[(X - \\mu_X)(Y - \\mu_Y)] = E(XY) - E(X)E(Y)$.', f: 'Se a covariância entre duas variáveis aleatórias é igual a zero, então elas são obrigatoriamente independentes em qualquer caso.', exp: 'Atenção máxima na FGV: Independência $\\implies \\text{Cov}(X,Y) = 0$; porém $\\text{Cov}(X,Y) = 0$ NÃO implica independência (exceto na Normal Bivariada), pois pode haver relação não linear (ex: $Y = X^2$ com $X$ simétrica em torno de zero)!' },
    { sub: 'Variância da Soma e da Diferença no Caso Geral (Com Covariância)', ref: 'Variância Conjunta', t: 'Para quaisquer duas variáveis aleatórias $X$ e $Y$, tem-se $\\text{Var}(X + Y) = \\text{Var}(X) + \\text{Var}(Y) + 2\\text{Cov}(X, Y)$ e $\\text{Var}(X - Y) = \\text{Var}(X) + \\text{Var}(Y) - 2\\text{Cov}(X, Y)$; de forma geral, $\\text{Var}(aX \\pm bY) = a^2\\text{Var}(X) + b^2\\text{Var}(Y) \\pm 2ab\\text{Cov}(X, Y)$.', f: 'Na variância da diferença $\\text{Var}(X - Y)$, subtrai-se $\\text{Var}(Y)$ de $\\text{Var}(X)$.', exp: '$\\text{Var}(X)$ e $\\text{Var}(Y)$ entram SEMPRE somando ($+a^2\\text{Var}(X) + b^2\\text{Var}(Y)$); o sinal $\\pm$ afeta apenas o termo duplo da covariância ($\\pm 2ab\\text{Cov}$)!' },
    { sub: 'Propriedades de Bilinearidade da Covariância', ref: 'Propriedades da Covariância', t: 'A covariância satisfaz $\\text{Cov}(X, X) = \\text{Var}(X)$, é insensível a constantes somadas e é bilinear nas constantes multiplicativas: $\\text{Cov}(aX + b, cY + d) = a \\cdot c \\cdot \\text{Cov}(X, Y)$.', f: 'Somar uma constante positiva $b$ a $X$ e uma constante $d$ a $Y$ aumenta a covariância em $b \\cdot d$.', exp: 'Constantes aditivas ($+b, +d$) desaparecem na covariância; constantes multiplicativas ($a, c$) saem multiplicando ($a \\cdot c$).' },
    { sub: 'Coeficiente de Correlação Linear ($\\rho_{XY}$)', ref: 'Correlação Linear', t: 'O coeficiente de correlação linear de Pearson é a covariância padronizada pelos desvios-padrão: $\\rho(X, Y) = \\text{Cov}(X, Y) / [\\sigma_X \\cdot \\sigma_Y]$, sendo adimensional e limitado ao intervalo fechado $-1 \\le \\rho \\le +1$.', f: 'Quando multiplicamos a variável $X$ por $2$, o coeficiente de correlação entre $X$ e $Y$ dobra de valor.', exp: 'A correlação é invariante à escala em magnitude: para $Y\' = cX + d$, a correlação mantém o valor absoluto (só inverte o sinal se $a \\cdot c < 0$).' }
  ],
  11: [
    { sub: 'Amostragem Probabilística vs. Não Probabilística', ref: 'Teoria da Amostragem', t: 'Na amostragem probabilística (aleatória simples, estratificada, sistemática e por conglomerados), todos os elementos da população possuem probabilidade conhecida e não nula de serem selecionados, o que permite medir o erro amostral e fazer inferência estatística válida; já na não probabilística (conveniência, julgamento, cotas, bola de neve), a seleção é subjetiva.', f: 'A amostragem por conveniência e a amostragem por cotas são métodos probabilísticos que permitem calcular intervalos de confiança exatos.', exp: 'Probabilísticas = AAS, Estratificada, Sistemática, Conglomerados; Não Probabilísticas = Conveniência, Julgamento, Cotas, Bola de Neve.' },
    { sub: 'Amostragem Estratificada vs. Amostragem por Conglomerados (Clusters)', ref: 'Planos Amostrais', t: 'Na amostragem estratificada, a população é dividida em estratos internamente homogêneos e heterogêneos entre si, sorteando-se elementos de TODOS os estratos; já na amostragem por conglomerados, a população é dividida em grupos internamente heterogêneos (miniaturas da população, ex: quarteirões) e sorteiam-se apenas alguns conglomerados.', f: 'Na amostragem estratificada, sorteia-se apenas um único estrato para representar toda a população.', exp: 'Estratos = homogêneos por dentro, diferentes entre si (amostra-se de TODOS os estratos). Conglomerados = heterogêneos por dentro, parecidos entre si (sorteiam-se alguns conglomerados).' },
    { sub: 'Alocação Proporcional e Alocação Ótima de Neyman na Estratificada', ref: 'Amostragem Estratificada', t: 'Na amostragem estratificada proporcional, o tamanho amostral de cada estrato é proporcional apenas ao tamanho $N_h$ do estrato; já na alocação de Neyman (com custos iguais), a amostra de cada estrato é proporcional ao produto do tamanho pelo desvio-padrão interno do estrato ($n_h \\propto N_h \\cdot S_h$).', f: 'Pela alocação ótima de Neyman, um estrato totalmente homogêneo com desvio-padrão zero ($S_h = 0$) deve receber a maior amostra de todas.', exp: 'Em Neyman, estratos com maior variabilidade interna ($S_h$ maior) recebem amostra maior!' },
    { sub: 'Distribuição Amostral da Média ($\\bar{X}$) e Erro-Padrão', ref: 'Distribuições Amostrais', t: 'Na amostragem aleatória simples com reposição (ou população infinita) de média $\\mu$ e variância $\\sigma^2$, a média amostral $\\bar{X}$ tem valor esperado $E(\\bar{X}) = \\mu$, variância $\\text{Var}(\\bar{X}) = \\sigma^2 / n$ e erro-padrão $EP(\\bar{X}) = \\sigma / \\sqrt{n}$ (com fator de correção de população finita $\\sqrt{(N-n)/(N-1)}$ se for sem reposição).', f: 'Para reduzir o erro-padrão da média amostral à metade, basta duplicar o tamanho da amostra $n$.', exp: 'Como o erro-padrão tem $\\sqrt{n}$ no denominador ($\\sigma / \\sqrt{n}$), para reduzir o erro-padrão (ou a margem de erro) à metade, é preciso QUADRUPLICAR o tamanho da amostra ($4n$)!' },
    { sub: 'Teorema Central do Limite (TCL)', ref: 'Teoria Assintótica', t: 'Pelo Teorema Central do Limite, à medida que o tamanho da amostra $n$ cresce ($n \\to \\infty$), a distribuição amostral da média $\\bar{X}$ (de variáveis i.i.d. com média $\\mu$ e variância finita $\\sigma^2$) converge em distribuição para uma Normal $N(\\mu, \\sigma^2 / n)$, qualquer que seja a distribuição original da população.', f: 'Pelo Teorema Central do Limite, quando a amostra cresce, os dados individuais da população passam a ser todos iguais à mediana.', exp: 'O TCL garante que a MÉDIA AMOSTRAL $\\bar{X}$ (e a soma amostral) tem distribuição aproximadamente Normal para $n$ grande, mesmo que a população original seja assimétrica ou discreta!' }
  ],
  12: [
    { sub: 'Propriedades dos Estimadores Pontuais: Não Viesado, Eficiência e Consistência', ref: 'Estimação Pontual', t: 'Um estimador $\\hat{\\theta}$ é não viesado (não tendencioso) quando $E(\\hat{\\theta}) = \\theta$; dentre dois estimadores não viesados, é mais eficiente o que possui menor variância; e um estimador é consistente quando converge em probabilidade para $\\theta$ à medida que $n \\to \\infty$ (viés e variância tendem a zero).', f: 'O Erro Quadrático Médio de um estimador viesado é dado exclusivamente pelo quadrado do seu viés, ignorando a variância.', exp: 'Fórmula clássica da FGV: Erro Quadrático Médio $\\text{EQM}(\\hat{\\theta}) = \\text{Var}(\\hat{\\theta}) + [\\text{Viés}(\\hat{\\theta})]^2$.' },
    { sub: 'Métodos de Estimação: Máxima Verossimilhança (EMV) e Momentos (MM)', ref: 'Estimação Pontual', t: 'O Estimador de Máxima Verossimilhança (EMV) escolhe o valor do parâmetro $\\theta$ que maximiza a função de verossimilhança $L(\\theta)$ (probabilidade ou densidade conjunta da amostra observada) e goza da propriedade da invariância (se $\\hat{\\theta}$ é o EMV de $\\theta$, então $g(\\hat{\\theta})$ é o EMV de $g(\\theta)$).', f: 'O método dos momentos consiste em igualar a mediana populacional ao máximo valor da amostra.', exp: 'Método dos Momentos iguala os momentos amostrais ($\\sum X_i^k / n$) aos momentos populacionais ($E(X^k)$); Máxima Verossimilhança maximiza $L(\\theta)$ (ou $\\ln L(\\theta)$).' },
    { sub: 'Intervalo de Confiança para a Média Populacional ($Z$ vs. $t$ de Student)', ref: 'Estimação Intervalar', t: 'O intervalo de confiança para a média $\\mu$ de uma população normal é $\\bar{x} \\pm z_{\\alpha/2} \\cdot (\\sigma / \\sqrt{n})$ quando a variância populacional $\\sigma^2$ é conhecida; quando $\\sigma^2$ é desconhecida e estimada pela variância amostral $s^2$, utiliza-se a distribuição $t$ de Student com $n - 1$ graus de liberdade: $\\bar{x} \\pm t_{n-1; \\alpha/2} \\cdot (s / \\sqrt{n})$.', f: 'Quando a variância populacional é desconhecida em uma amostra pequena de tamanho $n = 9$, usa-se a distribuição $t$ com $9$ graus de liberdade.', exp: 'Para uma única média com $\\sigma$ desconhecido, os graus de liberdade da distribuição $t$ são sempre $gl = n - 1$.' },
    { sub: 'Intervalo de Confiança para a Proporção Populacional ($p$)', ref: 'Estimação Intervalar', t: 'Para amostras grandes, o intervalo de confiança para a proporção populacional $p$ é $\\hat{p} \\pm z_{\\alpha/2} \\cdot \\sqrt{\\hat{p}(1 - \\hat{p}) / n}$; na ausência de estimativa prévia de $p$ (critério conservador para dimensionamento de amostra), adota-se $p = 0{,}50$, que maximiza o produto $p(1-p) = 0{,}25$.', f: 'O produto $p(1 - p)$ atinge seu valor máximo quando $p = 0{,}90$.', exp: 'O erro-padrão máximo da proporção ocorre em $p = 0{,}50$, onde $\\sqrt{p(1-p)/n} = 0{,}5 / \\sqrt{n}$ (resultando no tamanho de amostra conservador $n = z^2 / (4e^2)$).' },
    { sub: 'Relação entre Nível de Confiança, Tamanho da Amostra e Amplitude do IC', ref: 'Estimação Intervalar', t: 'Mantido fixo o tamanho da amostra, aumentar o nível de confiança ($1 - \\alpha$, ex: de 95% para 99%) aumenta o valor crítico e torna o intervalo mais largo (maior amplitude, menor precisão); já aumentar o tamanho da amostra $n$ reduz a margem de erro e estreita o intervalo.', f: 'Aumentar o nível de confiança de 90% para 99% mantendo a mesma amostra reduz pela metade a largura do intervalo de confiança.', exp: 'Maior confiança ($1-\\alpha$) -> maior $z$ -> maior margem de erro (intervalo mais amplo). Maior amostra ($n$) -> menor margem de erro (intervalo mais estreito).' }
  ],
  13: [
    { sub: 'Erros Tipo I ($\\alpha$), Tipo II ($\\beta$) e Poder do Teste ($1 - \\beta$)', ref: 'Testes de Hipóteses', t: 'Em um teste de hipóteses, o Erro Tipo I ($\\alpha$, nível de significância) consiste em rejeitar a hipótese nula $H_0$ quando $H_0$ é verdadeira; o Erro Tipo II ($\\beta$) consiste em não rejeitar $H_0$ quando $H_0$ é falsa; e o Poder do Teste ($1 - \\beta$) é a probabilidade de rejeitar corretamente uma $H_0$ falsa.', f: 'O Erro Tipo I consiste em aceitar uma hipótese nula falsa, e a soma $\\alpha + \\beta$ é sempre igual a 1.', exp: '$\\alpha = P(\\text{Rejeitar } H_0 | H_0 \\text{ verdadeira})$; $\\beta = P(\\text{Não rejeitar } H_0 | H_0 \\text{ falsa})$. Para amostra fixa, reduzir $\\alpha$ aumenta $\\beta$; só aumentando $n$ reduzem-se ambos!' },
    { sub: 'Regra de Decisão pelo Valor-$p$ (p-valor / Nível Descritivo)', ref: 'Testes de Hipóteses', t: 'O p-valor é a probabilidade de se obter uma estatística de teste tão ou mais extrema que a observada na amostra, sob a suposição de que $H_0$ seja verdadeira; rejeita-se $H_0$ se e somente se o p-valor for menor ou igual ao nível de significância $\\alpha$ ($\\text{p-valor} \\le \\alpha$).', f: 'Se o p-valor calculado em um teste for igual a $0{,}01$, a hipótese nula não deve ser rejeitada ao nível de significância de $\\alpha = 5\\%$.', exp: 'Regra universal: se $\\text{p-valor} \\le \\alpha \\implies$ Rejeita $H_0$! Logo, se p-valor = 1%, rejeita-se $H_0$ a 5% e a 1%, mas não a 0,5%.' },
    { sub: 'Testes para Duas Médias Independentes vs. Pareadas', ref: 'Testes Paramétricos', t: 'Para comparar duas médias de amostras independentes normais com variâncias populacionais desconhecidas mas supostas iguais (homocedasticidade), usa-se o teste $t$ com variância combinada (pooled) e $n_1 + n_2 - 2$ graus de liberdade; já para amostras dependentes (antes e depois no mesmo indivíduo), aplica-se o teste $t$ pareado sobre as diferenças $d_i$ com $n - 1$ graus de liberdade.', f: 'Na comparação de duas amostras independentes de tamanhos $n_1 = 10$ e $n_2 = 12$ pelo teste $t$ homocedástico, o número de graus de liberdade é $22$.', exp: 'Duas amostras independentes: $gl = n_1 + n_2 - 2$ (no exemplo, $10 + 12 - 2 = 20$). Amostra pareada de $n$ pares: $gl = n - 1$.' },
    { sub: 'Teste Qui-Quadrado de Aderência, Homogeneidade e Independência', ref: 'Testes Qui-Quadrado', t: 'A estatística Qui-Quadrado de Pearson $\\chi^2 = \\sum [(O_i - E_i)^2 / E_i]$ compara as frequências observadas ($O_i$) com as frequências esperadas ($E_i$): no teste de aderência a $k$ categorias sem parâmetros estimados, tem $k - 1$ graus de liberdade; em uma tabela de contingência com $L$ linhas e $C$ colunas, tem $(L - 1)(C - 1)$ graus de liberdade.', f: 'Em uma tabela de contingência $3 \\times 4$, o teste Qui-Quadrado de independência possui $3 \\times 4 = 12$ graus de liberdade.', exp: 'Em tabela $L \\times C$: $gl = (L - 1)(C - 1)$. Para $3 \\times 4$, $gl = (3-1)(4-1) = 2 \\times 3 = 6$.' },
    { sub: 'Testes Não Paramétricos (Sinais, Wilcoxon, Mann-Whitney, Kruskal-Wallis e Kolmogorov-Smirnov)', ref: 'Estatística Não Paramétrica', t: 'Os testes não paramétricos independem da suposição de normalidade e baseiam-se frequentemente em postos (ranks) ou sinais: Mann-Whitney (Wilcoxon rank-sum) compara duas amostras independentes, Wilcoxon signed-rank compara amostras pareadas, Kruskal-Wallis compara 3 ou mais grupos independentes, e Kolmogorov-Smirnov testa aderência de distribuição contínua.', f: 'O teste de Mann-Whitney exige que os dados tenham distribuição Normal com variâncias conhecidas.', exp: 'Correspondência FGV: Teste $t$ independente $\\leftrightarrow$ Mann-Whitney; Teste $t$ pareado $\\leftrightarrow$ Wilcoxon/Sinais; ANOVA $\\leftrightarrow$ Kruskal-Wallis.' }
  ],
  14: [
    { sub: 'Objetivo e Hipótese Nula da ANOVA a Um Fator (One-Way)', ref: 'Análise de Variância', t: 'A Análise de Variância (ANOVA) de um fator testa a igualdade simultânea das médias de $k \\ge 3$ populações ($H_0: \\mu_1 = \\mu_2 = \\dots = \\mu_k$ contra $H_1:$ pelo menos uma média difere das demais) por meio da comparação de variâncias.', f: 'Quando a ANOVA rejeita a hipótese nula $H_0$ para 4 grupos, fica provado que todas as 4 médias populacionais são diferentes entre si.', exp: 'Rejeitar $H_0$ na ANOVA indica apenas que PELO MENOS UMA média difere das demais (para saber quais diferem, usam-se testes post-hoc como Tukey, Bonferroni ou Scheffé).' },
    { sub: 'Decomposição da Soma de Quadrados ($SQT = SQE + SQR$)', ref: 'Quadro da ANOVA', t: 'Na ANOVA a um fator, a Soma de Quadrados Total ($SQT$) é decomposta na Soma de Quadrados Entre Grupos / Tratamentos ($SQE$ ou $SQTr$, variação explicada pelo fator) mais a Soma de Quadrados Dentro dos Grupos / Resíduos ($SQR$ ou $SQD$, variação aleatória não explicada): $SQT = SQE + SQR$.', f: 'Na tabela da ANOVA, a Soma de Quadrados dos Resíduos é sempre maior que a Soma de Quadrados Total.', exp: 'Identidade fundamental da ANOVA: $SQ_{\\text{Total}} = SQ_{\\text{Entre (Tratamentos)}} + SQ_{\\text{Dentro (Resíduos/Erro)}}$.' },
    { sub: 'Graus de Liberdade na ANOVA a Um Fator', ref: 'Quadro da ANOVA', t: 'Para $k$ grupos (tratamentos) e um total geral de $N$ observações, os graus de liberdade na ANOVA a um fator são: Entre Grupos (Tratamentos) = $k - 1$; Dentro dos Grupos (Resíduos/Erro) = $N - k$; e Total = $N - 1$.', f: 'Em uma ANOVA com $k = 4$ tratamentos e $N = 20$ observações totais, os graus de liberdade do resíduo são iguais a 19.', exp: 'Para $k = 4$ e $N = 20$: $gl_{\\text{Trat}} = 4 - 1 = 3$; $gl_{\\text{Res}} = 20 - 4 = 16$; $gl_{\\text{Total}} = 20 - 1 = 19$ ($3 + 16 = 19$).' },
    { sub: 'Quadrados Médios ($QM$) e Estatística $F$ da ANOVA', ref: 'Quadro da ANOVA', t: 'Cada Quadrado Médio é obtido dividindo-se a respectiva Soma de Quadrados pelos seus graus de liberdade ($QME = SQE / (k-1)$ e $QMR = SQR / (N-k)$), e a estatística de teste é a razão $F = QME / QMR$, que segue a distribuição $F(k-1, N-k)$ sob $H_0$.', f: 'A estatística $F$ da ANOVA é calculada dividindo-se a Soma de Quadrados Total pela média geral da amostra.', exp: '$F = QM_{\\text{Entre}} / QM_{\\text{Resíduo}}$. Sob $H_0$, $QMR$ estima $\\sigma^2$ sempre sem viés, e se $H_0$ é falsa, $QME$ tende a ser muito maior que $QMR$ (teste unilateral à direita).' },
    { sub: 'Pressupostos Clássicos da ANOVA e Delineamento em Blocos (DBA)', ref: 'Pressupostos da ANOVA', t: 'A validade do teste $F$ na ANOVA pressupõe: (1) normalidade dos resíduos em cada grupo; (2) homocedasticidade (igualdade das variâncias populacionais dos grupos, testada por Bartlett ou Levene); e (3) independência das observações; no Delineamento em Blocos Casualizados (ANOVA a dois fatores sem repetição), a $SQT$ decompõe-se em $SQ_{\\text{Trat}} + SQ_{\\text{Blocos}} + SQ_{\\text{Resíduo}}$.', f: 'A ANOVA exige que as variâncias de cada grupo sejam extremamente diferentes entre si (heterocedasticidade severa).', exp: 'No Delineamento em Blocos com $k$ tratamentos e $b$ blocos ($N = kb$): $gl_{\\text{Trat}} = k-1$, $gl_{\\text{Blocos}} = b-1$, e $gl_{\\text{Res}} = (k-1)(b-1)$.' }
  ],
  15: [
    { sub: 'Estimadores de Mínimos Quadrados Ordinários (MQO / OLS) na Regressão Simples', ref: 'Regressão Linear Simples', t: 'No modelo $Y_i = \\beta_0 + \\beta_1 X_i + \\varepsilon_i$, o método dos Mínimos Quadrados Ordinários minimiza a soma dos quadrados dos resíduos $\\sum e_i^2$, fornecendo $\\hat{\\beta}_1 = \\text{Cov}(X, Y) / \\text{Var}(X) = S_{XY} / S_{XX} = r \\cdot (s_Y / s_X)$ e $\\hat{\\beta}_0 = \\bar{Y} - \\hat{\\beta}_1 \\bar{X}$.', f: 'No método de Mínimos Quadrados Ordinários, o coeficiente angular $\\hat{\\beta}_1$ é obtido dividindo-se a variância de $X$ pela covariância entre $X$ e $Y$.', exp: 'Fórmula campeã de cobrança na FGV: $\\hat{\\beta}_1 = \\text{Cov}(X,Y) / \\text{Var}(X) = r \\cdot (s_Y / s_X)$, e a reta de regressão passa sempre pelo ponto médio $(\\bar{X}, \\bar{Y})$!' },
    { sub: 'Propriedades Algébricas dos Resíduos de MQO (Com Intercepto)', ref: 'Regressão Linear Simples', t: 'Em toda regressão linear estimada por MQO com intercepto ($\\beta_0$), a soma dos resíduos é identicamente zero ($\\sum e_i = 0$), a média dos valores estimados é igual à média dos valores observados ($\\bar{\\hat{Y}} = \\bar{Y}$), e os resíduos são ortogonais à variável explicativa ($\\sum X_i e_i = 0$) e aos valores ajustados ($\\sum \\hat{Y}_i e_i = 0$).', f: 'Na regressão por MQO com intercepto, a soma dos quadrados dos resíduos é sempre igual a zero.', exp: 'A soma simples dos resíduos é sempre zero ($\\sum e_i = 0$); a soma dos quadrados dos resíduos ($SQR = \\sum e_i^2$) só é zero se o ajuste for perfeito ($R^2 = 1$).' },
    { sub: 'Coeficiente de Determinação ($R^2$) e Relação com a Correlação ($r$)', ref: 'Qualidade do Ajuste', t: 'O Coeficiente de Determinação mede a proporção da variação total de $Y$ que é explicada linearmente por $X$: $R^2 = SQE / SQT = 1 - (SQR / SQT)$, variando entre $0$ e $1$; na regressão linear simples com intercepto, $R^2$ é exatamente igual ao quadrado do coeficiente de correlação de Pearson ($R^2 = r^2$).', f: 'Se o coeficiente de correlação linear é $r = -0{,}80$, então o coeficiente de determinação é $R^2 = -0{,}64$.', exp: 'Para $r = -0{,}80$, temos $R^2 = (-0{,}80)^2 = +0{,}64$ (64% da variância de $Y$ é explicada por $X$). Note que $r$ tem sempre o mesmo sinal de $\\hat{\\beta}_1$.' },
    { sub: 'Teorema de Gauss-Markov (Estimadores BLUE / MELNV)', ref: 'Pressupostos de Gauss-Markov', t: 'Sob as hipóteses clássicas de Gauss-Markov (linearidade nos parâmetros, média condicional zero do erro $E(\\varepsilon_i | X) = 0$, homocedasticidade $\\text{Var}(\\varepsilon_i) = \\sigma^2$ e ausência de autocorrelação $\\text{Cov}(\\varepsilon_i, \\varepsilon_j) = 0$), os estimadores de MQO são os Melhores Estimadores Lineares Não Viesados (BLUE / MELNV), ou seja, possuem variância mínima dentre todos os estimadores lineares não viesados.', f: 'O Teorema de Gauss-Markov exige a normalidade dos erros para demonstrar que o estimador de MQO é não viesado.', exp: 'A normalidade dos erros NÃO é exigida pelo Teorema de Gauss-Markov (BLUE); a normalidade é usada apenas para os testes exatos $t$ e $F$ em amostras pequenas!' },
    { sub: 'Estimativa da Variância do Erro ($s^2_e$) e Teste $t$ para $\\beta_1$', ref: 'Inferência na Regressão Simples', t: 'Na regressão linear simples (2 parâmetros estimados: $\\beta_0$ e $\\beta_1$), o estimador não viesado da variância do erro $\\sigma^2$ é o Quadrado Médio do Resíduo $QMR = s^2_e = SQR / (n - 2)$, e na ausência de relação linear ($H_0: \\beta_1 = 0$), a estatística $t = \\hat{\\beta}_1 / EP(\\hat{\\beta}_1)$ segue $t_{n-2}$ (com $F = t^2$).', f: 'Na regressão linear simples, o Quadrado Médio do Resíduo divide a Soma de Quadrados dos Resíduos por $n - 1$.', exp: 'Como estimamos 2 parâmetros ($\\beta_0$ e $\\beta_1$), perdem-se 2 graus de liberdade: $gl_{\\text{Res}} = n - 2$.' }
  ],
  16: [
    { sub: 'Modelo de Regressão Linear Múltipla e Interpretação Ceteris Paribus', ref: 'Regressão Múltipla', t: 'No modelo de regressão múltipla $Y = \\beta_0 + \\beta_1 X_1 + \\beta_2 X_2 + \\dots + \\beta_k X_k + \\varepsilon$ (com $k$ variáveis explicativas e $p = k + 1$ parâmetros), cada coeficiente parcial $\\beta_j$ mede a variação esperada em $Y$ para um aumento de uma unidade em $X_j$, mantendo todas as demais variáveis explicativas constantes (ceteris paribus).', f: 'Na regressão múltipla com $k = 3$ variáveis explicativas e intercepto, os graus de liberdade do resíduo são $n - 1$.', exp: 'Na regressão múltipla com $k$ regressores e intercepto ($p = k + 1$ parâmetros): $gl_{\\text{Regressão}} = k$, $gl_{\\text{Resíduo}} = n - k - 1$ e $gl_{\\text{Total}} = n - 1$.' },
    { sub: 'Coeficiente de Determinação Ajustado ($\\bar{R}^2$ ou $R^2_a$)', ref: 'Qualidade do Ajuste Múltiplo', t: 'Como o $R^2$ comum nunca diminui ao se adicionar uma nova variável explicativa ao modelo (mesmo irrelevante), utiliza-se o $R^2$ Ajustado, que penaliza a inclusão de variáveis sem poder explicativo pelos graus de liberdade: $\\bar{R}^2 = 1 - [(1 - R^2)(n - 1) / (n - k - 1)] = 1 - (QMR / QMT)$.', f: 'O $R^2$ Ajustado aumenta sempre que qualquer variável aleatória irrelevante é acrescentada à regressão múltipla.', exp: 'Fórmula essencial da FGV: $\\bar{R}^2 = 1 - [\\frac{n-1}{n-k-1}](1 - R^2) = 1 - \\frac{SQR/(n-k-1)}{SQT/(n-1)}$. O $\\bar{R}^2$ pode diminuir e até ser negativo!' },
    { sub: 'Multicolinearidade e Fator de Inflação da Variância (VIF / FIV)', ref: 'Diagnóstico da Regressão', t: 'A multicolinearidade consiste na alta correlação linear entre as variáveis explicativas ($X_j$): na multicolinearidade imperfeita, os estimadores de MQO continuam não viesados, mas suas variâncias e erros-padrão ficam inflados (reduzindo as estatísticas $t$), o que é medido pelo Fator de Inflação da Variância $VIF_j = 1 / (1 - R^2_j)$.', f: 'A presença de multicolinearidade moderada entre $X_1$ e $X_2$ torna os estimadores de MQO viesados e inconsistentes.', exp: 'Se a regressão auxiliar de $X_j$ contra os demais regressores tem $R^2_j = 0{,}80$, então $VIF_j = 1 / (1 - 0{,}80) = 1 / 0{,}20 = 5$.' },
    { sub: 'Heterocedasticidade e Autocorrelação Residual (Durbin-Watson)', ref: 'Violação de Pressupostos', t: 'Na presença de heterocedasticidade (variância do erro não constante, testada por White, Breusch-Pagan ou Goldfeld-Quandt) ou de autocorrelação serial (testada por Durbin-Watson $d \\approx 2(1 - \\hat{\\rho})$ ou Breusch-Godfrey), os estimadores de MQO permanecem não viesados, mas deixam de ser eficientes (não são mais BLUE) e os erros-padrão usuais tornam-se inválidos.', f: 'No teste de Durbin-Watson (que varia de 0 a 4), um valor de $d = 2{,}0$ indica autocorrelação positiva perfeita dos resíduos.', exp: 'Em Durbin-Watson ($d \\approx 2(1 - \\hat{\\rho})$): $d \\approx 2 \\implies$ ausência de autocorrelação ($\\rho = 0$); $d \\to 0 \\implies$ autocorrelação positiva ($\\rho \\to +1$); $d \\to 4 \\implies$ autocorrelação negativa ($\\rho \\to -1$).' },
    { sub: 'Variáveis Dummy (Binárias) e Armadilha da Variável Dummy', ref: 'Variáveis Qualitativas na Regressão', t: 'Para incluir uma variável qualitativa com $m$ categorias mutuamente exclusivas em uma regressão com intercepto $\\beta_0$, devem ser introduzidas exatamente $m - 1$ variáveis binárias (dummies $0$ ou $1$), sob pena de incorrer em multicolinearidade perfeita (armadilha da variável dummy).', f: 'Para representar as 4 regiões de um estado em um modelo com intercepto, devem ser incluídas 4 variáveis dummies.', exp: 'Com intercepto no modelo, para $m$ categorias usam-se $m - 1$ dummies (a categoria omitida funciona como base/referência no intercepto $\\beta_0$).' }
  ],
  17: [
    { sub: 'Componentes Clássicas de uma Série Temporal ($T, C, S, I$)', ref: 'Séries Temporais', t: 'Na decomposição clássica (aditiva $Y_t = T_t + C_t + S_t + I_t$ ou multiplicativa $Y_t = T_t \\cdot C_t \\cdot S_t \\cdot I_t$), uma série temporal é decomposta em: Tendência ($T$, movimento de longo prazo), Ciclo ($C$, oscilações plurianuais de expansão/recessão), Sazonalidade ($S$, padrão repetitivo intra-anual em meses/trimestres) e Componente Irregular/Aleatória ($I$, ruído imprevisível).', f: 'O aumento de vendas do comércio todo mês de dezembro devido ao Natal é classificado como componente Cíclica de longo prazo.', exp: 'Oscilação dentro do ano com período fixo (Natal, verão, safra) = Sazonalidade; oscilação de médio/longo prazo superior a um ano = Ciclo.' },
    { sub: 'Médias Móveis e Amortecimento Exponencial Simples', ref: 'Suavização e Previsão', t: 'O método das médias móveis suaviza flutuações de curto prazo para isolar a tendência; já na suavização (amortecimento) exponencial simples, a previsão para o período seguinte é a média ponderada entre o último valor observado e a última previsão: $\\hat{Y}_{t+1} = \\alpha Y_t + (1 - \\alpha)\\hat{Y}_t$, com $0 < \\alpha < 1$.', f: 'No amortecimento exponencial simples, os dados mais antigos da série recebem pesos maiores do que a observação mais recente.', exp: 'No amortecimento exponencial, os pesos decaem geometricamente à medida que as observações ficam mais antigas no passado.' },
    { sub: 'Processos Estacionários, Ruído Branco, AR($p$), MA($q$) e ARIMA($p,d,q$)', ref: 'Modelos Box-Jenkins', t: 'Uma série temporal é fracamente estacionária quando possui média constante ao longo do tempo, variância constante e autocovariância que depende apenas da defasagem (lag $k$); em um modelo ARIMA($p, d, q$), $p$ é a ordem autorregressiva (AR), $d$ é o número de diferenças necessárias para tornar a série estacionária (ordem de integração) e $q$ é a ordem de médias móveis (MA).', f: 'O passeio aleatório (Random Walk $Y_t = Y_{t-1} + \\varepsilon_t$) é um processo estacionário com variância constante no tempo.', exp: 'O Passeio Aleatório tem raiz unitária (não é estacionário, é $I(1)$, pois $\\text{Var}(Y_t) = t\\sigma^2$ cresce com $t$), mas sua primeira diferença $\\Delta Y_t = \\varepsilon_t$ é estacionária!' },
    { sub: 'Números-Índices Agregativos Ponderados: Laspeyres, Paasche e Fisher', ref: 'Números-Índices', t: 'O índice de preços de Laspeyres pondera os preços pelas quantidades da data-base ($L_P = \\sum p_t q_0 / \\sum p_0 q_0$); o índice de Paasche pondera pelas quantidades da data atual ($P_P = \\sum p_t q_t / \\sum p_0 q_t$); e o Índice Ideal de Fisher é a média geométrica entre Laspeyres e Paasche: $F = \\sqrt{L \\cdot P}$.', f: 'O índice de preços de Laspeyres utiliza como pesos as quantidades consumidas no período atual $t$.', exp: 'Laspeyres = base 0 fixa ($q_0$); Paasche = época atual $t$ ($q_t$); Fisher = $\\sqrt{L \\cdot P}$; Marshall-Edgeworth = pondera pela soma/média $(q_0 + q_t)$.' },
    { sub: 'Propriedades dos Números-Índices (Identidade, Reversão no Tempo, Reversão de Fatores e Circular)', ref: 'Testes de Fisher', t: 'O Índice Ideal de Fisher satisfaz tanto o critério da reversão no tempo ($I_{0,t} \\cdot I_{t,0} = 1$) quanto o critério da reversão de fatores (Índice de Preços $\\times$ Índice de Quantidades = Índice de Valor $\\sum p_t q_t / \\sum p_0 q_0$), propriedades que Laspeyres e Paasche isoladamente não satisfazem.', f: 'O índice de Laspeyres satisfaz perfeitamente os testes de reversão no tempo e de reversão de fatores de Fisher.', exp: 'Por manter a cesta fixa na base, Laspeyres tende a superestimar a inflação (viés de substituição), enquanto Paasche tende a subestimá-la; Fisher é "ideal" por cumprir reversão no tempo e de fatores.' }
  ],
  18: [
    { sub: 'Análise de Componentes Principais (ACP / PCA)', ref: 'Análise Multivariada', t: 'A Análise de Componentes Principais transforma um conjunto de variáveis originais correlacionadas em um novo conjunto de combinações lineares ortogonais (não correlacionadas entre si) chamadas componentes principais, correspondentes aos autovetores da matriz de covariâncias (ou de correlações), sendo a variância de cada componente igual ao respectivo autovalor ($\\lambda_i$).', f: 'Na Análise de Componentes Principais, a primeira componente principal é escolhida de modo a ter a menor variância possível.', exp: 'A 1ª Componente Principal ($CP_1$) captura a maior variância possível ($\\lambda_1$ máximo), a 2ª ($CP_2$) é ortogonal à 1ª e captura a segunda maior variância, e a soma dos autovalores iguala o traço da matriz!' },
    { sub: 'Análise Fatorial vs. Componentes Principais', ref: 'Análise Multivariada', t: 'Enquanto a ACP busca explicar a variância total por combinações lineares das variáveis observadas, a Análise Fatorial modela cada variável observada como função linear de fatores latentes comuns mais um termo de erro específico (unicidade), decompondo a variância de cada variável em comunalidade ($h_i^2$, parte explicada pelos fatores comuns) mais especificidade ($\\psi_i$).', f: 'Na Análise Fatorial com variáveis padronizadas, a comunalidade de uma variável pode ser maior que 10.', exp: 'Para variáveis padronizadas (variância = 1): Variância Total ($1$) = Comunalidade ($h_i^2 = \\sum l_{ij}^2$, soma dos quadrados das cargas fatoriais) + Especificidade/Unicidade ($\\psi_i$).' },
    { sub: 'Análise de Agrupamentos (Cluster Analysis: Hierárquicos e K-Means)', ref: 'Análise Multivariada', t: 'A Análise de Agrupamentos (Cluster) é uma técnica de interdependência (não supervisionada, sem rótulos prévios) que agrupa objetos em clusters de modo a maximizar a homogeneidade interna (dentro do cluster) e a heterogeneidade externa (entre clusters), utilizando métodos hierárquicos (dendrograma, ligação simples, completa ou Ward) ou não hierárquicos ($K$-means).', f: 'Na Análise de Cluster, os grupos já são previamente conhecidos antes da coleta dos dados para prever uma variável dependente.', exp: 'Grupos não conhecidos a priori -> Cluster Analysis; Grupos já conhecidos a priori -> Análise Discriminante!' },
    { sub: 'Análise Discriminante e Regressão Logística', ref: 'Classificação Multivariada', t: 'A Análise Discriminante Linear (de Fisher) é uma técnica de dependência em que a variável resposta é categórica (grupos previamente conhecidos) e as variáveis explicativas são métricas, buscando combinações lineares (funções discriminantes) que maximizem a razão entre a soma de quadrados entre grupos e a soma de quadrados dentro dos grupos.', f: 'A Análise Discriminante exige que a variável dependente $Y$ seja contínua e as variáveis explicativas sejam todas qualitativas.', exp: 'Análise Discriminante: $Y$ qualitativo (grupos conhecidos) e $X$ quantitativos. MANOVA: múltiplos $Y$ quantitativos e $X$ qualitativos (fatores).' },
    { sub: 'Vetor de Médias e Matriz de Variâncias e Covariâncias ($\\Sigma$)', ref: 'Vetores Aleatórios', t: 'Na matriz de variâncias e covariâncias $\\Sigma$ (de dimensão $p \\times p$) de um vetor aleatório $X$, os elementos da diagonal principal são as variâncias de cada variável ($\\sigma_{ii} = \\text{Var}(X_i) \\ge 0$) e os elementos fora da diagonal são as covariâncias ($\\sigma_{ij} = \\text{Cov}(X_i, X_j)$), sendo $\\Sigma$ sempre uma matriz simétrica e semidefinida positiva.', f: 'Na matriz de correlações $R$ de variáveis padronizadas, os elementos da diagonal principal são todos iguais a zero.', exp: 'Na matriz de correlações $R$, todos os elementos da diagonal principal valem $1$ (pois $\\text{Corr}(X_i, X_i) = 1$) e o traço de $R$ ($p \\times p$) é igual a $p$.' }
  ],
  19: [
    { sub: 'Tabelas de Contingência: Frequências Conjuntas, Marginais e Condicionais', ref: 'Análise Bidimensional Qualitativa', t: 'Na análise bidimensional de duas variáveis qualitativas organizadas em uma tabela de contingência, a associação entre as variáveis é verificada comparando-se as distribuições relativas condicionais (por linha ou por coluna) com a respectiva distribuição marginal: se forem iguais para todas as categorias, as variáveis são estatisticamente independentes.', f: 'Duas variáveis qualitativas em uma tabela de contingência são independentes apenas quando todas as células da tabela possuem frequência igual a zero.', exp: 'Sob independência, a frequência esperada de cada célula $(i, j)$ é dada pelo produto dos totais marginais dividido pelo total geral: $E_{ij} = (\\text{Total da Linha } i \\times \\text{Total da Coluna } j) / N$.' },
    { sub: 'Coeficiente de Contingência de Pearson ($C$) e $V$ de Cramer', ref: 'Medidas de Associação Qualitativa', t: 'A partir da estatística Qui-Quadrado ($\\chi^2$) de uma tabela de contingência de tamanho $n$, medem-se o grau de associação pelo Coeficiente de Contingência de Pearson $C = \\sqrt{\\chi^2 / (\\chi^2 + n)}$ (que nunca atinge 1) e pelo Coeficiente $V$ de Cramer $V = \\sqrt{\\chi^2 / [n \\cdot \\min(L-1, C-1)]}$, que varia exatamente de $0$ (independência) a $1$ (associação perfeita).', f: 'Quando duas variáveis qualitativas são perfeitamente independentes ($\\chi^2 = 0$), o coeficiente $V$ de Cramer assume valor igual a 1.', exp: 'Se há independência $\\implies \\chi^2 = 0 \\implies C = 0$ e $V = 0$. Em tabelas $2 \\times 2$, o $V$ de Cramer reduz-se ao coeficiente $\\phi = \\sqrt{\\chi^2 / n}$.' },
    { sub: 'Análise Bidimensional Mista: Qualitativa vs. Quantitativa ($R^2$ / Razão de Correlação $\\eta^2$)', ref: 'Associação Mista', t: 'Para medir o grau de associação entre uma variável qualitativa (que divide os dados em $k$ grupos/estratos) e uma variável quantitativa $Y$, decompõe-se a variância total na soma da variância dentro dos grupos (média ponderada das variâncias internas) com a variância entre as médias dos grupos, definindo-se o coeficiente de explicação $\\eta^2 = R^2 = \\sigma^2_{\\text{entre}} / \\sigma^2_{\\text{total}} = 1 - (\\sigma^2_{\\text{dentro}} / \\sigma^2_{\\text{total}})$.', f: 'Se dentro de cada estrato todos os indivíduos têm exatamente o mesmo salário ($\\sigma^2_{\\text{dentro}} = 0$), mas as médias dos estratos são diferentes, o grau de associação $\\eta^2$ é zero.', exp: 'Se $\\sigma^2_{\\text{dentro}} = 0$, toda a variação vem das diferenças entre os grupos ($\\sigma^2_{\\text{entre}} = \\sigma^2_{\\text{total}}$), logo $\\eta^2 = R^2 = 1$ (100% da variação de $Y$ é explicada pela variável qualitativa).' },
    { sub: 'Correlação por Postos de Spearman ($r_s$)', ref: 'Associação Ordinal', t: 'O coeficiente de correlação de postos de Spearman ($r_s = 1 - [6 \\sum d_i^2] / [n(n^2 - 1)]$, onde $d_i$ é a diferença entre os postos de $X_i$ e $Y_i$) mede a associação monotônica (linear ou não linear estritamente crescente/decrescente) entre duas variáveis ordinais ou quantitativas, variando de $-1$ a $+1$.', f: 'O coeficiente de Spearman só pode ser calculado para variáveis binárias dicotômicas.', exp: 'Se quando $X$ cresce $Y$ sempre cresce (mesmo que de forma exponencial $Y = e^X$), os postos coincidem ($d_i = 0$) e a correlação de Spearman é $r_s = +1$!' },
    { sub: 'Risco Relativo ($RR$) e Razão de Chances (Odds Ratio - $OR$) em Tabelas $2 \\times 2$', ref: 'Tabelas 2x2', t: 'Em uma tabela de contingência $2 \\times 2$ com contagens $a, b$ (expostos com/sem desfecho) e $c, d$ (não expostos com/sem desfecho), a Razão de Chances (Odds Ratio) é dada pelo produto cruzado $OR = (a \\cdot d) / (b \\cdot c)$, assumindo valor igual a $1$ quando não há associação (independência) entre exposição e desfecho.', f: 'Em uma tabela $2 \\times 2$, uma Razão de Chances (Odds Ratio) igual a $1{,}0$ indica associação positiva máxima entre as duas variáveis.', exp: 'Na Odds Ratio e no Risco Relativo, o valor neutro de independência (ausência de associação) é $1$ (enquanto na correlação e covariância é $0$).' }
  ]
};

export const MATEMATICA_FINANCEIRA_LESSON_MATRIX: SubjectLessonMatrix = {
  0: [
    { sub: 'Fórmula do Juro Simples e Montante Linear', ref: 'Capitalização Simples', t: 'No regime de juros simples, a taxa de juros incide exclusivamente sobre o capital inicial (principal $C$), gerando crescimento em progressão aritmética (linear): $J = C \\cdot i \\cdot n$ e $M = C(1 + i \\cdot n)$.', f: 'Na capitalização simples, os juros de cada período são incorporados ao saldo devedor para render novos juros no período seguinte.', exp: 'Juros simples = crescimento linear (PA de razão $C \\cdot i$). Taxas proporcionais são equivalentes em juros simples.' },
    { sub: 'Juro Exato vs. Juro Comercial (Ordinário) e Regra dos Banqueiros', ref: 'Convenções de Contagem de Dias', t: 'No cálculo de juros diários a partir de taxa anual, o Juro Comercial (ordinário) adota o ano comercial de 360 dias e mês de 30 dias; o Juro Exato adota o ano civil de 365 (ou 366) dias; e pela Regra dos Banqueiros (norte-americana), combina-se o número exato de dias no numerador com o divisor 360 no denominador (fornecendo o maior juro ao credor).', f: 'Para um mesmo capital, taxa anual e número de dias, o juro exato (divisor 365) é sempre estritamente maior que o juro comercial (divisor 360).', exp: 'Como $360 < 365$, dividir por 360 gera resultado maior: $J_{\\text{comercial}} > J_{\\text{exato}}$, com a relação $J_c / J_e = 365 / 360 = 73 / 72$.' },
    { sub: 'Desconto Simples Racional (Por Dentro)', ref: 'Desconto Simples', t: 'O desconto simples racional (por dentro) incide sobre o valor atual (líquido) $A_r$, equivalendo a uma operação de juros simples: $N = A_r(1 + i \\cdot n)$ e $D_r = N - A_r = [N \\cdot i \\cdot n] / (1 + i \\cdot n)$.', f: 'No desconto simples racional, a taxa de desconto incide diretamente sobre o valor nominal futuro do título.', exp: 'Desconto Racional (por dentro) = incide sobre o Valor Atual ($D_r = A_r \\cdot i \\cdot n$). Desconto Comercial (por fora) = incide sobre o Valor Nominal ($D_c = N \\cdot d \\cdot n$).' },
    { sub: 'Desconto Simples Comercial (Bancário ou Por Fora)', ref: 'Desconto Simples', t: 'No desconto simples comercial (por fora), a taxa de desconto $d$ incide diretamente sobre o valor nominal $N$ do título: $D_c = N \\cdot d \\cdot n$ e $A_c = N(1 - d \\cdot n)$; no desconto bancário, soma-se ainda a taxa administrativa/IOF ($h$) sobre o nominal: $D_b = N(d \\cdot n + h)$.', f: 'Para o mesmo título, prazo e taxa positiva, o desconto simples racional é sempre maior que o desconto simples comercial.', exp: 'Como $N > A_r$, tem-se sempre $D_c > D_r$ (e consequentemente o valor atual comercial é menor: $A_c < A_r$).' },
    { sub: 'Relação Fundamental entre Desconto Comercial e Racional Simples e Taxa Efetiva Linear', ref: 'Relação $D_c$ e $D_r$', t: 'O desconto simples comercial e o desconto simples racional (calculados à mesma taxa $i$ e prazo $n$) relacionam-se pela identidade clássica: $D_c = D_r(1 + i \\cdot n)$; além disso, a taxa implícita (efetiva linear $i_{ef}$) de um desconto comercial é $i_{ef} = d / (1 - d \\cdot n)$.', f: 'A diferença entre o desconto comercial e o desconto racional ($D_c - D_r$) é sempre igual a zero.', exp: 'Fórmula de ouro da FGV: $D_c = D_r(1 + i \\cdot n) \\implies D_c - D_r = D_r \\cdot i \\cdot n$, logo $i \\cdot n = (D_c - D_r) / D_r$!' }
  ],
  1: [
    { sub: 'Fórmula do Montante em Juros Compostos (Progressão Geométrica)', ref: 'Capitalização Composta', t: 'No regime de juros compostos, os juros de cada período são incorporados ao principal para o cálculo dos juros seguintes (juros sobre juros), gerando evolução exponencial (progressão geométrica de razão $1+i$): $M = C(1 + i)^n$ e $J = C[(1 + i)^n - 1]$.', f: 'No regime de juros compostos, os juros gerados no 1º mês são sempre maiores do que os juros gerados no 10º mês.', exp: 'Em juros compostos, a quota de juros de cada período cresce geometricamente: $J_k = C \\cdot i(1 + i)^{k-1}$.' },
    { sub: 'Comparação entre Juros Simples e Juros Compostos ($n < 1$, $n = 1$ e $n > 1$)', ref: 'Comparação de Regimes', t: 'Para a mesma taxa positiva $i$ e capital $C$: em $n = 1$ período, os montantes simples e composto são idênticos ($M_s = M_c$); para prazos superiores a 1 período ($n > 1$), o montante composto supera o simples ($M_c > M_s$); porém, para frações de período ($0 < n < 1$, convenção exponencial), o montante simples supera o composto ($M_s > M_c$).', f: 'Para qualquer prazo fracionário inferior a 1 mês ($n = 0{,}5$), o montante a juros compostos exponenciais supera o montante a juros simples.', exp: 'Curva exponencial vs. reta secante entre $n=0$ e $n=1$: para $0 < n < 1$, a reta (juros simples) fica ACIMA da exponencial ($M_s > M_c$); para $n > 1$, a exponencial dispara acima ($M_c > M_s$)!' },
    { sub: 'Convenção Linear vs. Convenção Exponencial em Prazos Fracionários', ref: 'Prazos Não Inteiros ($n = k + p/q$)', t: 'Quando o prazo em juros compostos possui parte inteira $k$ e parte fracionária $p/q$: pela Convenção Exponencial aplica-se $M = C(1 + i)^{k + p/q}$ em todo o período; já pela Convenção Linear aplica-se juros compostos na parte inteira $k$ e juros simples sobre esse montante na fração $p/q$: $M = C(1 + i)^k \\cdot [1 + i \\cdot (p/q)]$.', f: 'Para prazos fracionários, a convenção exponencial fornece sempre um montante maior do que a convenção linear.', exp: 'Como na fração $0 < p/q < 1$ o fator linear $[1 + i(p/q)]$ é maior que o exponencial $(1+i)^{p/q}$, o montante pela Convenção Linear é sempre MAIOR que pela Convenção Exponencial!' },
    { sub: 'Taxas Equivalentes em Juros Compostos', ref: 'Equivalência de Taxas', t: 'Duas taxas referidas a unidades de tempo distintas são equivalentes quando, aplicadas ao mesmo capital durante o mesmo intervalo de tempo, produzem exatamente o mesmo montante; em juros compostos, vale $(1 + i_{\\text{anual}}) = (1 + i_{\\text{semestral}})^2 = (1 + i_{\\text{trimestral}})^4 = (1 + i_{\\text{mensal}})^{12}$.', f: 'Em juros compostos, a taxa anual equivalente a $2\\%$ ao mês é exatamente igual a $24\\%$ ao ano.', exp: 'Em juros compostos, $2\\%$ a.m. equivale a $(1{,}02)^{12} - 1 \\approx 26{,}82\\%$ a.a. (sempre maior que a taxa proporcional $12 \\times 2\\% = 24\\%$).' },
    { sub: 'Regra de Capitalização Contínua', ref: 'Capitalização Contínua', t: 'Quando a frequência de capitalização tende ao infinito ($m \\to \\infty$) para uma taxa instantânea nominal $\\delta$, o montante no regime de capitalização contínua é dado por $M = C \\cdot e^{\\delta \\cdot n}$, sendo a taxa efetiva por período igual a $i = e^\\delta - 1$.', f: 'Na capitalização contínua, o montante torna-se infinito para qualquer prazo positivo.', exp: 'Pelo limite fundamental $\\lim_{m\\to\\infty} (1 + \\delta/m)^{mn} = e^{\\delta n}$, o montante converge para $C e^{\\delta n}$.' }
  ],
  2: [
    { sub: 'Desconto Composto Racional (Por Dentro)', ref: 'Desconto Composto', t: 'No desconto composto racional (por dentro), que é a operação inversa da capitalização composta, o valor atual $A_r$ é obtido dividindo-se o valor nominal $N$ pelo fator de capitalização: $A_r = N / (1 + i)^n = N(1 + i)^{-n}$, e o desconto é $D_r = N - A_r = N[1 - (1 + i)^{-n}]$.', f: 'No desconto composto racional, o valor atual pode tornar-se negativo se o prazo de antecipação $n$ for muito grande.', exp: 'Como $(1 + i)^n > 1$ para $i > 0$, no desconto composto racional o valor atual $A_r = N / (1+i)^n$ é sempre positivo para qualquer prazo $n$!' },
    { sub: 'Desconto Composto Comercial (Por Fora)', ref: 'Desconto Composto Comercial', t: 'No desconto composto comercial (por fora), aplica-se sucessivamente a taxa de desconto comercial $d$ sobre o valor líquido do período imediatamente anterior: $A_c = N(1 - d)^n$ e $D_c = N[1 - (1 - d)^n]$.', f: 'No desconto composto comercial, o fator de atualização é dado por $(1 + d)^n$.', exp: 'Fórmulas: Composto Racional $A_r = N(1 + i)^{-n}$; Composto Comercial $A_c = N(1 - d)^n$.' },
    { sub: 'Equivalência entre Taxa de Desconto Composto Comercial ($d$) e Racional ($i$)', ref: 'Taxas Equivalentes de Desconto Composto', t: 'Para que o desconto composto comercial (à taxa $d$) e o desconto composto racional (à taxa $i$) produzam o mesmo valor atual para qualquer prazo $n$, deve valer a relação independente do prazo: $(1 - d)(1 + i) = 1$, ou seja, $i = d / (1 - d)$ e $d = i / (1 + i)$.', f: 'No regime composto, a relação de equivalência entre a taxa comercial $d$ e a taxa racional $i$ depende do número de meses $n$ da operação.', exp: 'Diferentemente do regime simples, no regime composto a relação $(1 - d) = 1 / (1 + i) \\iff i = d/(1-d)$ independe do prazo $n$!' },
    { sub: 'Decomposição do Desconto Composto em Quotas Periódicas', ref: 'Desconto Composto', t: 'No desconto composto racional, o desconto total em $n$ períodos equivale à soma dos juros compostos calculados sobre o valor atual período a período; se um título de valor nominal $N$ sofre desconto composto racional por 2 meses à taxa $i$, tem-se $N = A(1 + i)^2$.', f: 'Descontar um título por 2 meses à taxa composta racional de $10\\%$ a.m. reduz o seu valor nominal em exatamente $20\\%$.', exp: 'Se a taxa é racional composta de $10\\%$ a.m., $A = N / (1{,}10)^2 = N / 1{,}21$; se for comercial composta de $10\\%$ a.m., $A = N(1 - 0{,}10)^2 = 0{,}81 N$ (desconto de $19\\%$).' },
    { sub: 'Comparação entre os 4 Tipos de Desconto (Para Mesma Taxa e $n > 1$)', ref: 'Comparação de Descontos', t: 'Para um mesmo valor nominal $N$, mesma taxa numérica e prazo $n > 1$: no desconto racional (por dentro), o Composto Racional é maior que o Simples Racional ($D_{CR} < D_{SR}$? Não: como $(1+i)^n > 1+in$, o valor atual composto racional é MENOR que o simples racional, logo o Desconto Composto Racional é MAIOR que o Desconto Simples Racional: $D_{CR} > D_{SR}$); já para $n = 1$, coincidem $D_{SR} = D_{CR}$ e $D_{SC} = D_{CC}$.', f: 'Para $n = 1$ período, o desconto simples racional e o desconto composto racional fornecem valores diferentes.', exp: 'Em $n = 1$: $A_{SR} = A_{CR} = N/(1+i)$ e $A_{SC} = A_{CC} = N(1-d)$. Para $n > 1$: $(1+i)^n > 1 + in \\implies A_{CR} < A_{SR} \\implies D_{CR} > D_{SR}$; e no comercial $(1-d)^n > 1 - dn \\implies A_{CC} > A_{SC} \\implies D_{SC} > D_{CC}$.' }
  ],
  3: [
    { sub: 'Taxa Nominal vs. Taxa Efetiva', ref: 'Taxas Nominais e Efetivas', t: 'Dá-se o nome de Taxa Nominal àquela em que a unidade de tempo da taxa não coincide com o período de capitalização (ex: $24\\%$ ao ano com capitalização mensal); a conversão da taxa nominal para a taxa efetiva do período de capitalização é feita sempre por divisão proporcional ($24\\% / 12 = 2\\%$ a.m. efetiva), e desta para a efetiva anual por equivalência composta ($(1{,}02)^{12} - 1$).', f: 'Em uma taxa nominal de $12\\%$ ao ano com capitalização mensal, a taxa efetiva mensal é obtida tirando-se a raiz décima segunda de $1{,}12$.', exp: 'Regra de ouro da FGV: Taxa Nominal $\\xrightarrow{\\text{Proporcional (divide)}}$ Taxa Efetiva do período de capitalização $\\xrightarrow{\\text{Exponencial (composta)}}$ Taxa Efetiva Anual!' },
    { sub: 'Equação de Fisher: Taxa Aparente (Nominal $i$), Taxa Real ($r$) e Inflação ($\\pi$)', ref: 'Equação de Fisher', t: 'A relação exata (fórmula de Fisher) entre a taxa aparente/nominal de juros ($i$), a taxa real de juros ($r$) e a taxa de inflação do período ($\\pi$ ou $I$) é multiplicativa: $(1 + i) = (1 + r)(1 + \\pi)$, donde $r = [(1 + i) / (1 + \\pi)] - 1 = (i - \\pi) / (1 + \\pi)$.', f: 'Se a taxa aparente de uma aplicação foi de $15\\%$ no ano e a inflação foi de $10\\%$, a taxa real de juros é exatamente $15\\% - 10\\% = 5\\%$.', exp: 'Nunca subtraia diretamente na FGV! Para $i = 21\\%$ e $\\pi = 10\\%$, tem-se $1 + r = 1{,}21 / 1{,}10 = 1{,}10 \\implies r = 10\\%$ (e não $11\\%$).' },
    { sub: 'Taxa Real Negativa e Poder de Compra', ref: 'Inflação e Juros Reais', t: 'Se a taxa aparente de rendimento ($i$) for inferior à taxa de inflação do período ($\\pi$), a taxa real de juros ($r$) será negativa, significando perda efetiva de poder aquisitivo da moeda, embora o saldo nominal em reais tenha aumentado.', f: 'É matematicamente impossível existir uma taxa real de juros negativa quando a taxa nominal é positiva.', exp: 'Se $i < \\pi$ (ex: rendimento de $5\\%$ com inflação de $10\\%$), então $(1+i)/(1+\\pi) < 1 \\implies r < 0$ (perda real de poder de compra).' },
    { sub: 'Deflacionamento de Séries de Valores e Índice de Preços', ref: 'Atualização e Deflação Monetária', t: 'A taxa de inflação acumulada entre duas datas $t_0$ e $t_n$ a partir dos números-índices de preços ($IP_t$) é dada por $\\pi = (IP_n / IP_0) - 1$; para atualizar um valor de $t_0$ para moeda constante de $t_n$ multiplica-se por $(1 + \\pi) = IP_n / IP_0$, e para deflacionar de $t_n$ para $t_0$ divide-se por $(1 + \\pi)$.', f: 'Se o índice de preços passou de 100 em janeiro para 120 em fevereiro e 150 em março, a inflação acumulada no bimestre é de $20\\% + 30\\% = 50\\%$.', exp: 'Inflação acumulada pelo índice = $IP_{\\text{final}} / IP_{\\text{inicial}} - 1 = 150 / 100 - 1 = 50\\%$, sendo as taxas mensais $120/100 - 1 = 20\\%$ e $150/120 - 1 = 25\\%$ (pois $1{,}20 \\times 1{,}25 = 1{,}50$).' },
    { sub: 'Desvalorização da Moeda vs. Taxa de Inflação', ref: 'Perda do Poder de Compra', t: 'Dada uma taxa de inflação positiva $\\pi$ no período, a taxa de desvalorização da moeda (perda percentual do poder de compra do dinheiro parado no bolso) é dada por $d_m = \\pi / (1 + \\pi) = 1 - [1 / (1 + \\pi)]$.', f: 'Se a inflação no ano for de $100\\%$ (os preços dobraram), o poder de compra da moeda caiu $100\\%$ (passou a valer zero).', exp: 'Pegadinha clássica: se a inflação é de $\\pi = 100\\%$ (preços dobraram), o dinheiro compra a metade do que comprava antes, logo a perda do poder de compra é de $\\pi / (1 + \\pi) = 1 / 2 = 50\\%$ (e para $\\pi = 25\\%$, a perda é $0{,}25 / 1{,}25 = 20\\%$)!' }
  ],
  4: [
    { sub: 'Conceito de Equivalência de Capitais e Data Focal (Data de Comparação)', ref: 'Equivalência Financeira', t: 'Dois ou mais capitais (ou conjuntos de capitais) com vencimentos em datas diferentes são financeiramente equivalentes em uma determinada data focal, a uma dada taxa de juros, quando a soma de seus valores transportados para essa data focal são iguais.', f: 'Dois fluxos de caixa são equivalentes apenas se a soma aritmética simples de seus valores nominais (sem descontar juros) for idêntica.', exp: 'Pelo princípio fundamental da Matemática Financeira, nunca se somam nem se comparam valores em datas distintas sem antes transportá-los para uma mesma Data Focal!' },
    { sub: 'Influência da Escolha da Data Focal (Regime Composto vs. Regime Simples)', ref: 'Mudança de Data Focal', t: 'No regime de juros compostos (e desconto composto racional), se dois conjuntos de capitais são equivalentes em uma data focal, eles serão equivalentes em QUALQUER outra data focal (a equivalência independe da data focal); já no regime de juros simples (ou desconto simples), a equivalência depende da data focal escolhida.', f: 'No regime de juros compostos, mudar a data focal da data 0 para a data 5 altera a relação de equivalência entre dois fluxos de caixa.', exp: 'Como em juros compostos mudar a data focal da data $0$ para a data $k$ apenas multiplica ambos os lados da equação por $(1+i)^k$, a igualdade se mantém em qualquer data focal!' },
    { sub: 'Equação de Valor na Substituição de Dívidas (Refinanciamento)', ref: 'Substituição de Títulos', t: 'Na substituição (repactuação) de um conjunto de títulos antigos por um novo plano de pagamentos, a equação de valor impõe que, na data focal adotada, o Valor Atual dos novos compromissos seja exatamente igual ao Valor Atual dos compromissos antigos substituídos.', f: 'Em uma repactuação de dívida na data zero, os títulos que ainda vão vencer no futuro devem ser multiplicados por $(1 + i)^n$.', exp: 'Para trazer um título que vence no futuro (data $n$) para a data zero, ele deve ser DESCONTADO (dividido por $(1+i)^n$ no composto racional); já títulos vencidos no passado são capitalizados até a data focal.' },
    { sub: 'Prazo Médio de Vencimento de Títulos em Desconto Comercial Simples', ref: 'Prazo Médio', t: 'No desconto comercial simples à mesma taxa $d$, o prazo médio ($\\bar{n}$) para substituir vários títulos de valores nominais $N_1, N_2, \\dots, N_k$ e prazos $n_1, n_2, \\dots, n_k$ por um único título de valor nominal igual à soma $\\sum N_j$ é a média aritmética ponderada dos prazos pelos respectivos valores nominais: $\\bar{n} = (\\sum N_j \\cdot n_j) / (\\sum N_j)$.', f: 'O prazo médio de vencimento de três títulos de valores nominais distintos é sempre a média aritmética simples dos três prazos.', exp: 'Se os títulos têm o mesmo valor nominal ($N_1 = N_2 = N_3$), o prazo médio no desconto comercial simples reduz-se à média aritmética simples dos prazos; caso contrário, pondera-se pelos valores nominais.' },
    { sub: 'Valor Presente de Fluxo de Caixa Não Periódico ou Misto', ref: 'Fluxos de Caixa', t: 'O Valor Presente (VP) na data zero de uma sequência qualquer de fluxos de caixa $FC_1, FC_2, \\dots, FC_n$ a uma taxa efetiva composta $i$ é a soma algébrica dos valores descontados de cada parcela: $VP = \\sum_{t=1}^n FC_t / (1 + i)^t$.', f: 'Se duplicarmos o valor de todas as parcelas de um fluxo de caixa mantendo a mesma taxa de juros, o Valor Presente permanece inalterado.', exp: 'O operador Valor Presente é linear nos fluxos de caixa: se todas as parcelas dobram, o Valor Presente e o Valor Futuro também dobram.' }
  ],
  5: [
    { sub: 'Rendimento Bruto, Imposto de Renda Retido na Fonte (IRRF) e Rendimento Líquido', ref: 'Tributação de Aplicações Financeiras', t: 'Em uma aplicação financeira sujeita à tributação na fonte à alíquota $\\alpha$ sobre os rendimentos (juros brutos $J_b$), o imposto incide apenas sobre o ganho nominal ($IR = \\alpha \\cdot J_b$), de modo que o rendimento líquido é $J_{liq} = J_b(1 - \\alpha)$ e a taxa efetiva líquida do período único de resgate é $i_{liq} = i_{bruta}(1 - \\alpha)$.', f: 'Em uma aplicação de R$ 1.000,00 que rende 10% brutos com IR de 20% sobre os rendimentos, o imposto de renda descontado é de 20% sobre o montante total de R$ 1.100,00.', exp: 'O IR incide sobre os JUROS ($J_b = 100 \\implies IR = 20\\% \\times 100 = 20$), resultando em resgate líquido de R$ 1.080,00 e taxa líquida no período de $8\\%$.' },
    { sub: 'Taxa Efetiva em Operações com Recolhimento Antecipado de Taxas ou IOF', ref: 'Custos Antecipados e Saldo Médio', t: 'Quando uma instituição financeira cobra no ato da liberação do empréstimo uma tarifa de abertura ou IOF ($T$) retida na fonte sobre o valor contratado $C$, o valor efetivamente recebido pelo tomador na data zero é apenas $C_{ef} = C - T$, o que eleva o Custo Efetivo Total (taxa efetiva real da operação) acima da taxa contratual.', f: 'A retenção de uma tarifa de cadastro no ato da liberação de um empréstimo reduz a taxa efetiva paga pelo devedor.', exp: 'Como o devedor recebe menos dinheiro na mão na data zero ($C - T$) mas paga as prestações calculadas sobre o total $C$, a taxa efetiva do empréstimo aumenta!' },
    { sub: 'Empréstimo com Exigência de Saldo Médio (Reciprocidade Bancária)', ref: 'Reciprocidade Bancária', t: 'Se para liberar um empréstimo de valor $C$ o banco exige que o cliente mantenha bloqueado (sem remuneração) um percentual $q$ como saldo médio durante a operação, o recurso líquido disponível para uso pelo tomador é $C(1 - q)$, aumentando a taxa efetiva da operação.', f: 'A exigência de saldo médio bloqueado sem remuneração reduz o custo financeiro efetivo para a empresa tomadora.', exp: 'Se o empréstimo é de 100 com juros de 10 (paga 110 no fim), mas 20 ficam bloqueados sem render, na prática o tomador levou apenas 80 líquidos na data zero e devolveu 90 líquidos no fim ($90/80 - 1 = 12{,}5\\% > 10\\%$).' },
    { sub: 'Rendimento Real de Aplicação Financeira Após Imposto de Renda e Inflação', ref: 'Taxa Líquida Real', t: 'Para determinar a taxa real líquida de uma aplicação financeira, deve-se primeiro descontar o Imposto de Renda sobre os juros nominais para obter a taxa nominal líquida ($i_{liq} = i_{bruta}(1 - \\alpha)$ no resgate) e, em seguida, aplicar a equação de Fisher contra a inflação $\\pi$: $1 + r_{liq} = (1 + i_{liq}) / (1 + \\pi)$.', f: 'No Brasil, o Imposto de Renda sobre aplicações de renda fixa prefixadas incide apenas sobre o ganho acima da inflação.', exp: 'Como o IR incide sobre o ganho nominal total (incluindo a reposição inflacionária), primeiro calcula-se $i_{liq} = i_b(1 - \\alpha)$ e depois aplica-se Fisher $(1 + i_{liq}) / (1 + \\pi) - 1$.' },
    { sub: 'Comparação entre Pagamento à Vista com Desconto vs. Pagamento a Prazo', ref: 'Decisão à Vista vs. a Prazo', t: 'Se uma loja vende um produto de preço $P$ oferecendo desconto de percentual $d$ para pagamento à vista (preço à vista = $P(1 - d)$) ou pelo preço cheio $P$ para pagamento em 1 mês sem entrada, a taxa de juros implícita mensal cobrada no pagamento a prazo é $i = P / [P(1 - d)] - 1 = d / (1 - d)$.', f: 'Se uma loja oferece 20% de desconto à vista ou o preço de tabela para daqui a 30 dias, a taxa de juros embutida para quem compra a prazo é de 20% ao mês.', exp: 'Clássica da FGV! Se o bem custa 100 a prazo (30 dias) e 80 à vista ($20\\%$ de desconto), quem escolhe pagar a prazo deixa de desembolsar 80 hoje para pagar 100 em 30 dias: juros de $20 / 80 = 25\\%$ ao mês!' }
  ],
  6: [
    { sub: 'Rendas Certas Postecipadas (Imediatas): Fator de Valor Atual ($a_{\\overline{n}|i}$)', ref: 'Séries Uniformes Postecipadas', t: 'Em uma série uniforme de $n$ pagamentos iguais a $R$ postecipados (1ª parcela no fim do 1º período, na data 1), o Valor Presente na data zero é $VP = R \\cdot a_{\\overline{n}|i}$, onde o Fator de Valor Atual é $a_{\\overline{n}|i} = [1 - (1 + i)^{-n}] / i = [(1 + i)^n - 1] / [i(1 + i)^n]$.', f: 'Em uma renda postecipada de $n$ termos, a primeira prestação vence exatamente no ato da compra (data zero).', exp: 'Postecipada (modelo padrão Price): parcelas nas datas $1, 2, \\dots, n$, e o $VP$ calculado por $R \\cdot a_{\\overline{n}|i}$ cai um período antes da 1ª parcela (na data 0).' },
    { sub: 'Rendas Certas Postecipadas: Fator de Acumulação de Capital ($s_{\\overline{n}|i}$)', ref: 'Montante de Série Uniforme', t: 'O Montante (Valor Futuro $VF$) de uma série uniforme postecipada de $n$ depósitos iguais a $R$, calculado imediatamente após o $n$-ésimo depósito (na data $n$), é dado por $VF = R \\cdot s_{\\overline{n}|i}$, onde $s_{\\overline{n}|i} = [(1 + i)^n - 1] / i = a_{\\overline{n}|i} \\cdot (1 + i)^n$.', f: 'O fator de acumulação de capital $s_{\\overline{n}|i}$ para taxa positiva é sempre menor que o número de parcelas $n$.', exp: 'Como há capitalização de juros sobre os depósitos anteriores, para $i > 0$ e $n > 1$, tem-se sempre $s_{\\overline{n}|i} > n > a_{\\overline{n}|i}$.' },
    { sub: 'Rendas Certas Antecipadas (Com Entrada na Data Zero)', ref: 'Séries Uniformes Antecipadas', t: 'Em uma série uniforme antecipada de $n$ parcelas iguais a $R$ (parcelas nas datas $0, 1, \\dots, n-1$, sendo a 1ª no ato como entrada), tanto o Valor Presente (na data 0) quanto o Valor Futuro (na data $n$) equivalem aos da série postecipada multiplicados por $(1 + i)$: $VP_{ant} = R \\cdot a_{\\overline{n}|i} \\cdot (1 + i)$ e $VF_{ant} = R \\cdot s_{\\overline{n}|i} \\cdot (1 + i)$.', f: 'O valor presente de uma série antecipada de $n$ parcelas iguais é obtido dividindo-se o valor presente postecipado por $(1 + i)$.', exp: 'Como na série antecipada cada parcela ocorre 1 período mais cedo (a 1ª na data 0 sem desconto), seu Valor Presente é MAIOR: $VP_{\\text{antecipado}} = VP_{\\text{postecipado}} \\cdot (1 + i)$!' },
    { sub: 'Relação Algébrica entre os Fatores $a_{\\overline{n}|i}$, $s_{\\overline{n}|i}$ e o FRC', ref: 'Fatores Financeiros', t: 'O Fator de Recuperação de Capital ($FRC = 1 / a_{\\overline{n}|i} = [i(1+i)^n] / [(1+i)^n - 1]$) e o Fator de Formação de Capital ($FFC = 1 / s_{\\overline{n}|i} = i / [(1+i)^n - 1]$) satisfazem a identidade exata: $FRC - FFC = i$ (ou seja, $1/a_{\\overline{n}|i} - 1/s_{\\overline{n}|i} = i$).', f: 'A soma do Fator de Recuperação de Capital com o Fator de Formação de Capital é sempre igual a zero.', exp: 'Identidade rapidíssima para provas FGV: $\\frac{1}{a_{\\overline{n}|i}} - \\frac{1}{s_{\\overline{n}|i}} = i$ (se a questão der $s_{\\overline{n}|i}$ e $i$, você acha $a_{\\overline{n}|i}$ em 5 segundos!).' },
    { sub: 'Compra com Entrada Diferente das Demais Parcelas', ref: 'Fluxo com Entrada Especial', t: 'Quando um financiamento prevê uma entrada de valor $E$ na data zero seguida de $n$ prestações mensais iguais a $R$ (vencendo das datas $1$ a $n$), o valor à vista (Valor Presente na data zero) é dado por $VP = E + R \\cdot a_{\\overline{n}|i}$.', f: 'Em uma compra com entrada $E$ na data zero, o valor da entrada deve ser dividido por $(1 + i)^n$ para compor o valor à vista.', exp: 'Como a entrada $E$ já está na data zero, ela soma pelo seu valor integral $E$, e as $n$ parcelas restantes (datas $1$ a $n$) formam uma série postecipada $R \\cdot a_{\\overline{n}|i}$.' }
  ],
  7: [
    { sub: 'Rendas Certas Diferidas (Com Prazo de Carência $c$)', ref: 'Séries Diferidas', t: 'Se uma série uniforme de $n$ termos iguais a $R$ possui carência de $c$ períodos (de modo que a 1ª prestação vence apenas no fim do período $c + 1$), o seu Valor Presente na data zero é obtido trazendo-se $R \\cdot a_{\\overline{n}|i}$ (que cai na data $c$) para a data zero: $VP = [R \\cdot a_{\\overline{n}|i}] / (1 + i)^c = R(a_{\\overline{n+c}|i} - a_{\\overline{c}|i})$.', f: 'Se a primeira prestação de uma série uniforme vence no mês 4, o fator de desconto da carência sobre $R \\cdot a_{\\overline{n}|i}$ é $(1 + i)^4$.', exp: 'Atenção máxima na FGV! O fator postecipado $R \\cdot a_{\\overline{n}|i}$ sempre deixa o valor 1 período ANTES da 1ª parcela! Logo, se a 1ª parcela vence na data $4$, $R \\cdot a_{\\overline{n}|i}$ cai na data $3$, precisando descontar por apenas $c = 3$ períodos: $VP = R \\cdot a_{\\overline{n}|i} / (1 + i)^3$!' },
    { sub: 'Perpetuidade Imediata (Postecipada) de Termos Constantes', ref: 'Rendas Perpétuas', t: 'O Valor Presente na data zero de uma renda perpétua (infinitas parcelas periódicas constantes iguais a $R$, começando na data 1) a uma taxa efetiva positiva $i$ por período é dado pelo limite $\\lim_{n\\to\\infty} R \\cdot a_{\\overline{n}|i} = R / i$.', f: 'A soma do valor presente de infinitas prestações positivas iguais é sempre infinita.', exp: 'Como $(1 + i)^{-n} \\to 0$ quando $n \\to \\infty$, a série geométrica converge para $VP = R / i$ (ex: ação ou imóvel que paga aluguel perpétuo de R$ 1.000/mês a $1\\%$ a.m. vale $1.000 / 0{,}01 = \\text{R\\$ } 100.000,00$).' },
    { sub: 'Perpetuidade Antecipada e Perpetuidade Diferida', ref: 'Rendas Perpétuas', t: 'Se a perpetuidade de parcela $R$ for antecipada (1ª parcela já na data zero), seu valor presente é $VP = R + (R / i) = R(1 + i) / i$; se for diferida com a 1ª parcela vencendo na data $k > 1$, o valor $R / i$ (que cai na data $k - 1$) é descontado por $(1 + i)^{k-1}$: $VP = (R / i) / (1 + i)^{k-1}$.', f: 'Em uma perpetuidade antecipada de parcela $R$, o valor presente é menor que $R / i$.', exp: 'Na perpetuidade postecipada (1ª na data 1): $VP = R/i$. Na antecipada (1ª na data 0): $VP = R + R/i$.' },
    { sub: 'Perpetuidade Crescente à Taxa Geométrica Constante (Modelo de Gordon)', ref: 'Perpetuidade em PG', t: 'Em uma perpetuidade postecipada cujas parcelas crescem a uma taxa geométrica constante $g$ por período ($R_1$ na data 1, $R_1(1+g)$ na data 2, $R_1(1+g)^2$ na data 3, $\\dots$), sendo a taxa de desconto maior que a taxa de crescimento ($i > g$), o Valor Presente na data zero é dado pela fórmula de Gordon: $VP = R_1 / (i - g)$.', f: 'Na fórmula de Gordon para perpetuidade crescente, soma-se a taxa de crescimento $g$ à taxa de juros $i$ no denominador: $R_1 / (i + g)$.', exp: 'Fórmula de Gordon (muito cobrada em Matemática Financeira e Avaliação de Ações na FGV): $VP = R_1 / (i - g)$, exigindo $i > g$.' },
    { sub: 'Série em Progressão Aritmética Perpétua', ref: 'Perpetuidade em PA', t: 'Para uma perpetuidade postecipada cujos pagamentos crescem em progressão aritmética de razão $G$ ($R$ na data 1, $R + G$ na data 2, $R + 2G$ na data 3, $\\dots$), o Valor Presente na data zero é dado por $VP = (R / i) + (G / i^2)$.', f: 'Uma perpetuidade que cresce em progressão aritmética de razão positiva $G$ possui valor presente menor que $R / i$.', exp: 'A parcela constante $R$ vale $R / i$ e o gradiente aritmético perpétuo $G, 2G, 3G, \\dots$ a partir da data 2 vale $G / i^2$.' }
  ],
  8: [
    { sub: 'Características Fundamentais da Tabela Price (Sistema Francês - SAF)', ref: 'Sistema Francês / Price', t: 'No Sistema Francês de Amortização (ou Tabela Price, quando a taxa é dada em termos nominais anuais com prestações mensais), as prestações ($P$) são periódicas e CONSTANTES, as quotas de juros ($J_k$) são decrescentes e as quotas de amortização ($A_k$) são CRESCENTES em progressão geométrica de razão $(1 + i)$.', f: 'Na Tabela Price, as quotas de amortização permanecem constantes ao longo de todo o financiamento.', exp: 'Em todo sistema de amortização: $P_k = A_k + J_k$ e $J_k = i \\cdot SD_{k-1}$. Como na Price $P$ é constante e o saldo devedor cai ($J_k$ cai), a amortização $A_k$ cresce!' },
    { sub: 'Lei de Formação das Amortizações em PG na Tabela Price ($A_k = A_1(1 + i)^{k-1}$)', ref: 'Progressão Geométrica na Price', t: 'No Sistema Francês (Price), como $P = A_1 + J_1 = A_2 + J_2$, demonstra-se que cada quota de amortização é igual à anterior multiplicada por $(1 + i)$: $A_k = A_1(1 + i)^{k-1}$ e, de modo geral, $A_k = A_m(1 + i)^{k-m}$.', f: 'No Sistema Francês de Amortização, as quotas de amortização crescem em progressão aritmética de razão igual à taxa de juros.', exp: 'Propriedade de ouro da Price para resolver questões FGV sem calcular prestação: $A_2 = A_1(1+i)$, $A_3 = A_2(1+i)$, e na última parcela $P = A_n(1 + i)$!' },
    { sub: 'Cálculo do Saldo Devedor na Tabela Price (Método Prospectivo e Retrospectivo)', ref: 'Saldo Devedor na Price', t: 'No Sistema Francês (Price), o saldo devedor imediatamente após o pagamento da $k$-ésima prestação ($SD_k$) equivale ao Valor Presente, na data $k$, das $n - k$ prestações vincendas (restantes): $SD_k = P \\cdot a_{\\overline{n-k}|i}$.', f: 'Na Tabela Price de 60 meses, após pagar a 30ª prestação (metade do prazo), o devedor já amortizou exatamente 50% do saldo devedor inicial.', exp: 'Como as amortizações na Price crescem em PG (são menores no início e maiores no fim), na metade do prazo o devedor amortizou MENOS de 50% da dívida (o saldo devedor na metade ainda é maior que 50%)!' },
    { sub: 'Primeira Quota de Juros e Primeira Quota de Amortização na Price', ref: '1ª Prestação na Price', t: 'Na primeira prestação ($k = 1$) da Tabela Price sobre um empréstimo $SD_0$, os juros do 1º período são $J_1 = i \\cdot SD_0$, a prestação é $P = SD_0 / a_{\\overline{n}|i}$, e a primeira quota de amortização é a diferença $A_1 = P - J_1 = SD_0 / s_{\\overline{n}|i}$.', f: 'Na Tabela Price, os juros da primeira prestação são calculados aplicando-se a taxa $i$ sobre o valor da prestação $P$.', exp: 'Regra universal de TODOS os sistemas de amortização: os juros do período $k$ incidem SEMPRE sobre o Saldo Devedor do período anterior ($J_k = i \\cdot SD_{k-1}$), nunca sobre a prestação!' },
    { sub: 'Carência no Sistema Francês (Com Pagamento de Juros vs. Capitalização de Juros)', ref: 'Prazo de Carência', t: 'Se houver prazo de carência na Tabela Price com pagamento periódico dos juros durante a carência, o saldo devedor permanece igual a $SD_0$ até o início das amortizações; porém, se os juros não forem pagos durante os $c$ períodos de carência, eles são capitalizados no saldo devedor, que passa a ser $SD_c = SD_0(1 + i)^c$ antes de se calcularem as prestações.', f: 'Quando os juros não são pagos durante o período de carência, eles são perdoados pelo banco sem alterar o saldo devedor.', exp: 'Durante a carência: (a) paga juros -> $SD$ permanece constante $= SD_0$; (b) não paga juros -> juros capitalizam e $SD$ sobe para $SD_0(1+i)^c$.' }
  ],
  9: [
    { sub: 'Características Fundamentais do Sistema de Amortização Constante (SAC)', ref: 'Sistema SAC', t: 'No Sistema de Amortização Constante (SAC), todas as quotas de amortização são constantes e iguais a $A = SD_0 / n$; consequentemente, o saldo devedor, os juros ($J_k$) e as prestações ($P_k = A + J_k$) decrescem linearmente em progressão aritmética (PA) de razão igual a $-i \\cdot A$.', f: 'No SAC, as prestações permanecem constantes e as quotas de amortização decrescem ao longo do tempo.', exp: 'No SAC: Amortização = Constante ($A = SD_0 / n$); Saldo Devedor, Juros e Prestações = Decrescentes em PA de razão $r = i \\cdot A$!' },
    { sub: 'Fórmulas Diretas do Saldo Devedor, Juros e Prestação de Ordem $k$ no SAC', ref: 'Fórmulas do SAC', t: 'Em um financiamento pelo SAC de valor $SD_0$ em $n$ períodos com amortização $A = SD_0 / n$: após a $k$-ésima prestação, o saldo devedor é $SD_k = (n - k) \\cdot A$; os juros da $k$-ésima prestação são $J_k = i \\cdot SD_{k-1} = i \\cdot (n - k + 1) \\cdot A$; e a $k$-ésima prestação é $P_k = A[1 + i(n - k + 1)]$.', f: 'No SAC, a última prestação ($P_n$) é composta exclusivamente pela quota de amortização $A$, sem qualquer cobrança de juros.', exp: 'Na última prestação ($k = n$), o saldo anterior era $SD_{n-1} = 1 \\cdot A$, logo $J_n = i \\cdot A$ e a última prestação é $P_n = A(1 + i)$!' },
    { sub: 'Soma Total dos Juros e das Prestações no SAC (Soma de PA)', ref: 'Total Pago no SAC', t: 'Como os juros no SAC formam uma progressão aritmética decrescente de $J_1 = n \\cdot i \\cdot A$ até $J_n = 1 \\cdot i \\cdot A$, a soma total de todos os juros pagos no SAC é dada pela soma da PA: $\\sum J_k = [(J_1 + J_n) \\cdot n] / 2 = i \\cdot A \\cdot n(n + 1) / 2 = SD_0 \\cdot i \\cdot (n + 1) / 2$.', f: 'A soma de todas as quotas de amortização no SAC ($\\sum A_k$) depende da taxa de juros contratada.', exp: 'Em QUALQUER sistema de amortização sem correção monetária, a soma de todas as quotas de amortização ($\\sum_{k=1}^n A_k$) é sempre igual ao valor emprestado original ($SD_0$)!' },
    { sub: 'Comparação entre SAC e Tabela Price', ref: 'SAC vs. Price', t: 'Para um mesmo valor financiado $SD_0$, mesmo prazo $n > 1$ e mesma taxa $i$: a 1ª prestação do SAC é maior que a prestação constante da Price ($P_{1,\\text{SAC}} > P_{\\text{Price}}$), a última prestação do SAC é menor que a da Price, e o saldo devedor no SAC cai mais rapidamente, resultando em menor soma nominal de juros pagos no SAC.', f: 'Embora a soma nominal das prestações no SAC seja menor que na Price, a taxa interna de retorno (custo efetivo composto) da Tabela Price é maior que a do SAC.', exp: 'Pegadinha clássica de alto nível FGV: na data zero, descontados à taxa $i$, TANTO o fluxo do SAC QUANTO o fluxo da Price têm exatamente o mesmo Valor Presente ($SD_0$) e a mesma Taxa Interna de Retorno ($i$)! O total nominal de juros na Price é maior apenas porque o saldo devedor demora mais a cair.' },
    { sub: 'Sistema de Amortização Misto (SAM / SACRE)', ref: 'Sistema Misto (SAM)', t: 'No Sistema de Amortização Misto (SAM), cada prestação (bem como cada quota de amortização, juros e saldo devedor) em qualquer período $k$ é exatamente igual à média aritmética simples entre os valores correspondentes do SAC e do Sistema Francês (Price): $P_{k,\\text{SAM}} = (P_{k,\\text{SAC}} + P_{\\text{Price}}) / 2$.', f: 'No Sistema de Amortização Misto (SAM), a prestação é a média geométrica entre as prestações do SAC e do Sistema Americano.', exp: 'SAM = Média Aritmética Simples entre SAC e SAF (Price) para todos os elementos da planilha ($P_k, A_k, J_k, SD_k$).' }
  ],
  10: [
    { sub: 'Funcionamento do Sistema de Amortização Americano (SAA)', ref: 'Sistema Americano', t: 'No Sistema de Amortização Americano (SAA) básico (com pagamento periódico de juros), o devedor paga ao fim de cada período ($k = 1, 2, \\dots, n-1$) exclusivamente os juros do período ($P_k = J_k = i \\cdot SD_0$, com amortização $A_k = 0$), e no último período ($k = n$) devolve de uma só vez 100% do principal acrescido dos juros do último período ($P_n = SD_0 + i \\cdot SD_0 = SD_0(1 + i)$).', f: 'No Sistema Americano básico, o saldo devedor cai pela metade na metade do prazo do contrato.', exp: 'No Sistema Americano, como $A_1 = A_2 = \\dots = A_{n-1} = 0$ e os juros são pagos em dia, o saldo devedor permanece constante e igual a $SD_0$ até a véspera da última parcela, quando $A_n = SD_0$ zera a dívida!' },
    { sub: 'Sistema Americano com Fundo de Amortização (Sinking Fund)', ref: 'Sinking Fund', t: 'Na modalidade Sinking Fund do Sistema Americano, além de pagar os juros periódicos ($i \\cdot SD_0$) ao credor do empréstimo, o devedor realiza depósitos periódicos constantes ($D$) em um fundo de investimento remunerado a uma taxa de captação $r$, de modo que o montante acumulado no fundo na data $n$ ($D \\cdot s_{\\overline{n}|r}$) seja exatamente igual ao principal $SD_0$ a ser resgatado.', f: 'No Sinking Fund, os depósitos no fundo de amortização abatem mensalmente a base de cálculo dos juros cobrados pelo credor do empréstimo.', exp: 'No Sinking Fund, a dívida junto ao credor continua sendo $SD_0$ até o fim (pagando juros $i \\cdot SD_0$ todo período), enquanto paralelamente acumula-se $SD_0$ no fundo: $D = SD_0 / s_{\\overline{n}|r}$.' },
    { sub: 'Desembolso Periódico Total no Sinking Fund e Caso $r = i$', ref: 'Sinking Fund vs. Price', t: 'No Sistema Americano com Sinking Fund, o desembolso total do devedor em cada período é a soma dos juros pagos ao credor com a quota depositada no fundo: $DT = i \\cdot SD_0 + (SD_0 / s_{\\overline{n}|r})$; se a taxa de remuneração do fundo for igual à taxa do empréstimo ($r = i$), o desembolso periódico total do Sinking Fund iguala exatamente a prestação da Tabela Price!', f: 'Se a taxa do fundo de amortização for igual à taxa do empréstimo ($r = i$), o desembolso mensal do Sinking Fund será o dobro da prestação da Tabela Price.', exp: 'Pela identidade $i + 1/s_{\\overline{n}|i} = 1/a_{\\overline{n}|i}$, quando $r = i$ tem-se $DT = SD_0(i + 1/s_{\\overline{n}|i}) = SD_0 / a_{\\overline{n}|i} = P_{\\text{Price}}$! Se $r < i$, o desembolso do Sinking Fund supera a Price.' },
    { sub: 'Sistema de Pagamento Único (Bullet / Juros Capitalizados)', ref: 'Sistema de Pagamento Único', t: 'No sistema de pagamento único (sem pagamentos intermediários de juros nem de principal), os juros são capitalizados período a período sobre o saldo devedor, e toda a dívida (principal + juros compostos acumulados) é quitada em uma única parcela no vencimento final $n$: $P_n = SD_0(1 + i)^n$.', f: 'No sistema de pagamento único, a soma dos juros pagos ao final de $n$ períodos é igual a $n \\cdot i \\cdot SD_0$.', exp: 'No pagamento único (zero pagamentos até $n-1$), o saldo cresce exponencialmente e no fim paga-se $SD_0(1 + i)^n$.' },
    { sub: 'Sistema de Amortização Variável e Planilhas com Correção Monetária', ref: 'Sistemas com Correção Monetária', t: 'Em contratos com cláusula de atualização monetária pós-fixada (ex: IPCA ou TR) mais juros reais $i$, em cada período primeiro corrige-se o saldo devedor anterior pelo índice de inflação do período ($SD_{k-1,\\text{corr}} = SD_{k-1}(1 + \\pi_k)$) e, sobre esse saldo corrigido, calculam-se os juros e a quota de amortização do período.', f: 'Em contratos corrigidos monetariamente, a correção monetária incide apenas sobre os juros do mês, mantendo o saldo devedor nominal congelado.', exp: 'Ordem em cada mês: 1º atualiza o Saldo Devedor pela inflação do mês; 2º calcula Juros e Amortização sobre o saldo atualizado.' }
  ],
  11: [
    { sub: 'Definição e Fórmula do Valor Presente Líquido (VPL / NPV)', ref: 'Análise de Investimentos - VPL', t: 'O Valor Presente Líquido (VPL) de um projeto de investimento é a soma algébrica de todos os fluxos de caixa líquidos esperados ($FC_t$, positivos e negativos) descontados para a data zero à Taxa Mínima de Atratividade ($TMA = k$), subtraído o investimento inicial $I_0$: $VPL = -I_0 + \\sum_{t=1}^n [FC_t / (1 + k)^t]$.', f: 'No cálculo do VPL, o investimento inicial realizado na data zero ($I_0$) deve ser dividido por $(1 + k)^n$.', exp: 'Como $I_0$ já ocorre na data zero, ele entra sem desconto ($-I_0$), e as entradas/saídas futuras ($t = 1 \\dots n$) são trazidas para a data zero pela TMA.' },
    { sub: 'Critério de Decisão do VPL ($VPL > 0$, $VPL = 0$ e $VPL < 0$)', ref: 'Regra de Decisão do VPL', t: 'Um projeto de investimento é economicamente viável quando apresenta $VPL > 0$ (remunera o capital investido à TMA e ainda gera riqueza econômica adicional em valor presente) ou $VPL = 0$ (remunera exatamente à TMA, recuperando o capital más o custo de oportunidade); se $VPL < 0$, o projeto destrói valor e deve ser rejeitado.', f: 'Quando um projeto apresenta $VPL = 0$ para uma TMA de $12\\%$ ao ano, significa que o investidor teve lucro nominal igual a zero e não recuperou nem a inflação.', exp: 'Pegadinha clássica FGV: $VPL = 0$ NÃO significa lucro zero! Significa que o projeto recuperou 100% do capital investido e ainda rendeu exatamente a TMA exigida ($12\\%$ a.a.)!' },
    { sub: 'Comportamento do Perfil do VPL em Função da TMA', ref: 'Curva do VPL', t: 'Em projetos convencionais (uma saída inicial seguida apenas de entradas líquidas de caixa positivas), o VPL é uma função estritamente DECRESCENTE e côncava/convexa (convexa em relação à origem) da Taxa Mínima de Atratividade ($k$): quando $k = 0$, o VPL é máximo e igual à soma simples dos fluxos; à medida que a TMA aumenta, o VPL diminui.', f: 'Em um projeto convencional, aumentar a Taxa Mínima de Atratividade (TMA) de 10% para 20% aumenta o Valor Presente Líquido do projeto.', exp: 'Como $(1 + k)^t$ está no denominador dos fluxos positivos, quanto MAIOR a TMA ($k$), MENOR é o VPL!' },
    { sub: 'Propriedade de Aditividade do VPL e Projetos Mutuamente Exclusivos', ref: 'VPL em Projetos Exclusivos', t: 'O VPL goza da propriedade de aditividade de valor ($VPL(A + B) = VPL(A) + VPL(B)$) e assume implicitamente que os fluxos intermediários de caixa são reinvestidos à própria Taxa Mínima de Atratividade (TMA); na escolha entre projetos mutuamente exclusivos de mesma duração, deve-se escolher aquele que apresenta o MAIOR VPL positivo.', f: 'Na comparação entre dois projetos mutuamente exclusivos com escalas de investimento diferentes, deve-se sempre rejeitar o projeto de maior VPL.', exp: 'Entre projetos mutuamente exclusivos, o critério soberano em Finanças é maximizar a riqueza gerada em valor presente = escolher o maior VPL positivo!' },
    { sub: 'Índice de Lucratividade Líquida (ILL / Benefício-Custo) e Valor Anual Uniforme Equivalente (VAUE)', ref: 'ILL e VAUE', t: 'O Índice de Lucratividade ($IL = VP(\\text{Entradas}) / I_0 = 1 + VPL / I_0$) mede o retorno por unidade monetária investida (viável se $IL > 1$); já para comparar projetos mutuamente exclusivos com vidas úteis DIFERENTES e passíveis de repetição, converte-se o VPL de cada projeto em uma série uniforme anual pelo respectivo prazo: $VAUE = VPL / a_{\\overline{n}|k}$.', f: 'Um projeto com Valor Presente Líquido negativo apresenta Índice de Lucratividade superior a $1{,}0$.', exp: 'Se $VPL > 0 \\iff IL > 1$; se $VPL = 0 \\iff IL = 1$; se $VPL < 0 \\iff IL < 1$. Para projetos repetíveis de prazos diferentes, compara-se o $VAUE = VPL / a_{\\overline{n}|k}$.' }
  ],
  12: [
    { sub: 'Definição Algébrica da Taxa Interna de Retorno (TIR / IRR)', ref: 'Análise de Investimentos - TIR', t: 'A Taxa Interna de Retorno (TIR) é a taxa periódica de desconto ($r = TIR$) que anula o Valor Presente Líquido do fluxo de caixa do projeto ($VPL(TIR) = 0$), igualando o valor presente das entradas de caixa ao valor presente das saídas (investimentos): $I_0 = \\sum_{t=1}^n [FC_t / (1 + TIR)^t]$.', f: 'A Taxa Interna de Retorno (TIR) de um projeto depende diretamente da Taxa Mínima de Atratividade (TMA) do investidor: se a TMA subir, a TIR do projeto também sobe.', exp: 'Pegadinha clássica FGV: a TIR é uma característica intrínseca ("interna") exclusiva dos fluxos de caixa do projeto e NÃO depende da TMA! A TMA serve apenas como parâmetro externo de comparação.' },
    { sub: 'Critério de Decisão da TIR em Projetos de Investimento vs. Financiamento', ref: 'Regra de Decisão da TIR', t: 'Para um projeto convencional de investimento (saída na data 0 seguida de entradas), o projeto é viável ($VPL > 0$) quando a sua Taxa Interna de Retorno supera a Taxa Mínima de Atratividade ($TIR > TMA$); se $TIR = TMA$, então $VPL = 0$; e se $TIR < TMA$, então $VPL < 0$ (inviável).', f: 'Um projeto de investimento convencional é economicamente viável apenas quando a sua TIR é inferior à TMA.', exp: 'Em projeto de investimento: $TIR > TMA \\iff VPL > 0$ (aceita); $TIR = TMA \\iff VPL = 0$; $TIR < TMA \\iff VPL < 0$ (rejeita).' },
    { sub: 'Equações de 2º Grau para Cálculo da TIR em 2 Períodos', ref: 'Cálculo da TIR para $n = 2$', t: 'Em um fluxo de caixa de apenas 2 períodos ($-I_0$ na data 0, $FC_1$ na data 1 e $FC_2$ na data 2), fazendo a substituição $x = 1 + TIR$ (ou $u = 1 / (1 + TIR)$), a equação $-I_0 + FC_1/(1+TIR) + FC_2/(1+TIR)^2 = 0$ transforma-se na equação quadrática $-I_0 x^2 + FC_1 x + FC_2 = 0$, cuja raiz positiva $x > 0$ fornece $TIR = x - 1$.', f: 'Não é possível calcular algebricamente a TIR de um projeto com dois fluxos futuros sem usar logaritmos neperianos.', exp: 'Dica rápida FGV para $n=2$: multiplique toda a equação do VPL por $(1+TIR)^2 = x^2$, resolva por Bhaskara (ou soma e produto) para achar $x = 1 + TIR$, e subtraia 1!' },
    { sub: 'Limitações da TIR: Múltiplas Raízes (Regra de Descartes) e Pressuposto de Reinvestimento', ref: 'Limitações da TIR', t: 'A TIR apresenta duas limitações clássicas: (1) assume implicitamente que os fluxos intermediários de caixa são reinvestidos à própria TIR (e não à TMA); e (2) em fluxos de caixa não convencionais (com mais de uma mudança de sinal nos fluxos ao longo do tempo), o polinômio pode admitir múltiplas TIRs reais positivas (até o número de mudanças de sinal, pela regra de Descartes) ou nenhuma TIR real.', f: 'Todo fluxo de caixa não convencional com três inversões de sinal possui obrigatoriamente uma única TIR real positiva.', exp: 'Para corrigir essas duas falhas, utiliza-se a TIR Modificada ($TIRM$ ou $MIRR$), que capitaliza as entradas até a data $n$ pela TMA e desconta as saídas para a data 0 pela taxa de financiamento, tendo sempre solução única!' },
    { sub: 'Conflito entre VPL e TIR em Projetos Mutuamente Exclusivos e Taxa de Fisher', ref: 'Interseção de Fisher', t: 'Na comparação de dois projetos mutuamente exclusivos (com escalas diferentes ou distribuição temporal distinta dos fluxos), pode haver conflito de ranking entre VPL e TIR; a taxa de desconto na qual os dois projetos possuem exatamente o mesmo VPL ($VPL_A(i_F) = VPL_B(i_F)$) chama-se Taxa de Interseção de Fisher (calculada como a TIR do fluxo incremental $A - B$), prevalecendo sempre a decisão pelo maior VPL na TMA dada.', f: 'Para taxas de desconto superiores à Taxa de Interseção de Fisher, o ranking apontado pelo VPL sempre diverge do ranking apontado pela TIR.', exp: 'Para $TMA < i_{\\text{Fisher}}$ há conflito entre VPL e TIR (e prevalece o VPL); para $TMA > i_{\\text{Fisher}}$, ambos apontam o mesmo projeto vencedor (não há conflito)!' }
  ],
  13: [
    { sub: 'Conceito e Cálculo do Payback Simples (Nominal)', ref: 'Payback Simples', t: 'O Payback Simples (período de recuperação nominal) é o tempo necessário para que a soma aritmética acumulada dos fluxos de caixa nominais (sem descontar juros pela TMA) iguale o investimento inicial $I_0$; se os fluxos forem constantes e iguais a $FC$, tem-se $\\text{Payback Simples} = I_0 / FC$.', f: 'O Payback Simples leva em conta o valor do dinheiro no tempo descontando cada fluxo pela Taxa Interna de Retorno.', exp: 'O Payback Simples ignora o valor do dinheiro no tempo (taxa = 0%) e ignora todos os fluxos que ocorrem após a recuperação do investimento.' },
    { sub: 'Conceito e Cálculo do Payback Descontado (Econômico)', ref: 'Payback Descontado', t: 'O Payback Descontado é o tempo necessário para que a soma acumulada dos valores presentes dos fluxos de caixa (descontados período a período pela TMA $k > 0$) iguale o investimento inicial $I_0$, isto é, o momento em que o saldo do VPL acumulado passa de negativo para zero.', f: 'Para um mesmo projeto convencional e taxa de juros positiva ($TMA > 0$), o Payback Descontado é sempre menor (mais rápido) que o Payback Simples.', exp: 'Como para $k > 0$ cada fluxo descontado $FC_t / (1+k)^t$ é menor que o fluxo nominal $FC_t$, demora MAIS tempo para recuperar o investimento: $\\text{Payback Descontado} > \\text{Payback Simples}$!' },
    { sub: 'Relação Matemática entre Payback Descontado, Vida Útil ($n$) e VPL', ref: 'Payback Descontado vs. VPL', t: 'Em um projeto convencional de vida útil $n$: se o Payback Descontado é inferior à vida útil do projeto ($PB_D < n$), então o projeto se paga antes do fim e gera $VPL > 0$; se $PB_D = n$, então $VPL = 0$; e se $VPL < 0$, o Payback Descontado não existe dentro da vida útil do projeto ($PB_D > n$).', f: 'É possível que um projeto convencional apresente Valor Presente Líquido negativo ($VPL < 0$) e, ao mesmo tempo, tenha Payback Descontado igual à metade de sua vida útil.', exp: 'Em projeto convencional: $PB_{\\text{Descontado}} < n \\iff VPL > 0$! Porém, um projeto pode ter Payback SIMPLES menor que $n$ e ainda assim ter $VPL < 0$.' },
    { sub: 'Interpolação Linear para Fração de Período no Payback', ref: 'Interpolação no Payback', t: 'Quando a recuperação do investimento ocorre entre o período $t$ (onde ainda faltava recuperar um saldo devedor $S_t$) e o período $t + 1$ (que gera uma entrada $FC_{t+1}$, nominal no simples ou descontada no descontado), a fração de período é calculada por interpolação linear: $\\text{Payback} = t + (S_t / FC_{t+1})$.', f: 'Se após o 2º ano faltam R$ 30.000,00 para recuperar o investimento e o fluxo do 3º ano é de R$ 60.000,00, o payback é de $2 + 2 = 4$ anos.', exp: 'No exemplo: faltam 30.000 e entram 60.000 no 3º ano $\\implies$ recupera na metade do 3º ano: $\\text{Payback} = 2 + (30.000 / 60.000) = 2{,}5$ anos (2 anos e 6 meses).' },
    { sub: 'Limitação do Payback Descontado em Projetos de Longo Prazo', ref: 'Limitações do Payback', t: 'Embora o Payback Descontado corrija a falha de ignorar o valor do dinheiro no tempo até a data de recuperação, ele continua apresentando a falha de ignorar completamente os fluxos de caixa que ocorrem APÓS o período de recuperação, podendo preterir projetos altamente lucrativos de maturação mais longa (maior VPL).', f: 'O Payback Descontado é sempre um critério superior ao VPL para selecionar projetos mutuamente exclusivos.', exp: 'O Payback (simples ou descontado) é uma medida de liquidez e risco de prazo de retorno, não devendo substituir o VPL como medida de criação de riqueza.' }
  ],
  14: [
    { sub: 'Depreciação Linear (Quotas Constantes) e Valor Contábil ($VC_t$)', ref: 'Métodos de Depreciação', t: 'No método de depreciação linear para um ativo de custo inicial $C$, valor residual estimado $VR$ e vida útil de $n$ períodos, o valor depreciável total é $VD = C - VR$, a quota periódica constante de depreciação é $D = (C - VR) / n$, e o valor contábil após $t$ períodos é $VC_t = C - t \\cdot D$.', f: 'No método de depreciação linear, o valor residual $VR$ é somado ao custo inicial $C$ para calcular a quota anual de depreciação.', exp: 'O valor contábil ao final da vida útil ($t = n$) iguala exatamente o Valor Residual ($VC_n = VR$).' },
    { sub: 'Método da Soma dos Dígitos dos Anos (Método de Cole)', ref: 'Método de Cole', t: 'No método da soma dos dígitos para $n$ anos, calcula-se a soma $S = 1 + 2 + \\dots + n = n(n + 1) / 2$; na modalidade decrescente (acelerada), a quota do 1º ano é $(n / S)(C - VR)$, a do 2º ano é $((n-1) / S)(C - VR)$ e a do $t$-ésimo ano é $[(n - t + 1) / S](C - VR)$ (na modalidade crescente, invertem-se os numeradores para $1/S, 2/S, \\dots, n/S$).', f: 'Para um equipamento com vida útil de 5 anos, o denominador do método de Cole é igual a $5 \\times 5 = 25$.', exp: 'Para $n = 5$, a soma dos dígitos é $S = 5 \\times 6 / 2 = 15$ ($1+2+3+4+5$). Na modalidade decrescente, as frações são $5/15, 4/15, 3/15, 2/15$ e $1/15$.' },
    { sub: 'Efeito Fiscal da Depreciação no Fluxo de Caixa de Projetos (Benefício Fiscal / Tax Shield)', ref: 'Depreciação em Projetos', t: 'Embora a depreciação ($Dep$) não seja um desembolso de caixa, ela é uma despesa dedutível na apuração do Imposto de Renda (alíquota $\\alpha$), reduzindo o imposto a pagar e gerando uma economia fiscal (benefício fiscal ou tax shield) igual a $\\alpha \\cdot Dep$; assim, o Fluxo de Caixa Operacional é $FCO = (\\text{Receitas} - \\text{Custos Caixa})(1 - \\alpha) + \\alpha \\cdot Dep = \\text{Lucro Operacional Líquido} + Dep$.', f: 'A despesa de depreciação representa uma saída física de dinheiro do caixa da empresa todo final de mês.', exp: 'Fórmula clássica da FGV em Avaliação de Projetos: $FCO = LAJIR(1 - \\alpha) + \\text{Depreciação}$, onde o benefício fiscal da depreciação é $\\alpha \\cdot \\text{Depreciação}$!' },
    { sub: 'Avaliação de Títulos de Renda Fixa (Debêntures e Obrigações / Bonds)', ref: 'Precificação de Títulos (Bonds)', t: 'O preço justo (valor intrínseco no mercado na data zero) de um título de dívida (bond ou debênture) que paga cupons periódicos $C$ e devolve o valor de face (principal $VF$) no vencimento $n$, descontado à taxa de retorno exigida pelo mercado ($YTM = k$), é $P_0 = C \\cdot a_{\\overline{n}|k} + VF / (1 + k)^n$.', f: 'Quando a taxa de juros exigida pelo mercado ($YTM$) sobe acima da taxa de cupom do título, o título passa a ser negociado com ágio (acima do valor ao par).', exp: 'Relação inversa fundamental: se $YTM = i_{\\text{cupom}} \\implies$ título ao par ($P_0 = VF$); se $YTM > i_{\\text{cupom}} \\implies$ título com DESÁGIO ($P_0 < VF$); se $YTM < i_{\\text{cupom}} \\implies$ título com ÁGIO ($P_0 > VF$)!' },
    { sub: 'Custo Anual Uniforme Equivalente (CAUE / CAE) na Substituição de Equipamentos', ref: 'Custo Anual Equivalente', t: 'Para comparar duas máquinas alternativas com vidas úteis diferentes que desempenham a mesma função produtiva, calcula-se o Valor Presente de todos os custos (aquisição + manutenção operacional - valor residual de revenda no fim) e divide-se pelo fator de valor atual $a_{\\overline{n}|k}$ de cada máquina, escolhendo-se aquela de MENOR Custo Anual Equivalente ($CAE$).', f: 'Na comparação de custos entre dois equipamentos de vidas úteis distintas, o valor residual de revenda ao final da vida útil deve ser somado aos custos de aquisição.', exp: 'Na ótica de Custos, o Valor Residual ao final da vida útil é uma recuperação de caixa (entrada), logo SUBTRAI do custo em valor presente: $VP_{\\text{Custos}} = C_0 + VP(\\text{Manutenção}) - VR / (1+k)^n$.' }
  ],
  15: [
    { sub: 'Síntese FGV: Equivalência de Taxas e Convenção Linear vs. Exponencial', ref: 'Revisão Geral Mat. Financeira FGV', t: 'Em juros simples, taxas proporcionais são equivalentes ($i_a = 12 \\cdot i_m$); em juros compostos, taxas equivalentes obedecem a $(1 + i_a) = (1 + i_m)^{12}$, e para prazos fracionários ($0 < f < 1$) a Convenção Linear gera sempre um montante ligeiramente maior que a Convenção Exponencial.', f: 'Uma taxa nominal de 18% ao ano com capitalização semestral corresponde a uma taxa efetiva anual de exatamente 18%.', exp: 'Taxa nominal de $18\\%$ a.a. com cap. semestral $\\implies$ efetiva semestral de $18\\% / 2 = 9\\%$ a.s. $\\implies$ efetiva anual de $(1{,}09)^2 - 1 = 18{,}81\\%$ a.a.' },
    { sub: 'Síntese FGV: Descontos Simples e Compostos e Relação $D_c / D_r$', ref: 'Revisão Geral Mat. Financeira FGV', t: 'No desconto simples, $D_c = N \\cdot d \\cdot n$ e $D_r = N \\cdot i \\cdot n / (1 + i \\cdot n)$, valendo sempre a identidade $D_c = D_r(1 + i \\cdot n)$; no desconto composto, $A_r = N / (1 + i)^n$ e $A_c = N(1 - d)^n$, sendo as taxas equivalentes quando $(1 - d)(1 + i) = 1$.', f: 'Se o desconto comercial simples é R$ 110,00 e o desconto racional simples é R$ 100,00 (mesma taxa e prazo de 1 mês), então a taxa mensal é de 20%.', exp: 'Pela relação $D_c / D_r = 1 + i \\cdot n$: $110 / 100 = 1{,}10 = 1 + i \\cdot 1 \\implies i = 10\\%$ a.m. (e o valor nominal é $N = D_c / (i \\cdot n) = 110 / 0{,}10 = \\text{R\\$ } 1.100,00$)!' },
    { sub: 'Síntese FGV: Séries Uniformes (Postecipada, Antecipada, Diferida e Perpétua)', ref: 'Revisão Geral Mat. Financeira FGV', t: 'Para $n$ parcelas iguais a $R$: na postecipada $VP = R \\cdot a_{\\overline{n}|i}$; na antecipada $VP = R \\cdot a_{\\overline{n}|i}(1 + i)$; na diferida com 1ª parcela na data $k > 1$, $VP = R \\cdot a_{\\overline{n}|i} / (1 + i)^{k-1}$; e na perpetuidade postecipada crescente à taxa $g$, $VP = R_1 / (i - g)$.', f: 'Se um título paga dividendo perpétuo de R$ 12,00 no ano 1 crescendo 2% ao ano e a taxa exigida é de 10% ao ano, o valor presente da ação é de R$ 100,00.', exp: 'Pelo modelo de Gordon: $VP = R_1 / (i - g) = 12 / (0{,}10 - 0{,}02) = 12 / 0{,}08 = \\text{R\\$ } 150,00$.' },
    { sub: 'Síntese FGV: Confronto Price vs. SAC vs. SAM vs. Americano', ref: 'Revisão Geral Mat. Financeira FGV', t: 'Na Tabela Price, a prestação é constante e a amortização cresce em PG ($A_k = A_1(1+i)^{k-1}$); no SAC, a amortização é constante ($SD_0 / n$) e a prestação e os juros decrescem em PA de razão $i \\cdot A$; no SAM, cada linha é a média aritmética entre SAC e Price; e no Americano, paga-se apenas $J = i \\cdot SD_0$ até $n-1$ e amortiza-se 100% em $n$.', f: 'Em qualquer sistema de amortização, a quota de juros do 3º mês é calculada multiplicando-se a taxa de juros pelo valor da 3ª prestação.', exp: 'Em TODOS os sistemas, $J_k = i \\cdot SD_{k-1}$ e $P_k = A_k + J_k$.' },
    { sub: 'Síntese FGV: Análise de Projetos (VPL, TIR, Taxa de Fisher e Payback)', ref: 'Revisão Geral Mat. Financeira FGV', t: 'Em projetos convencionais, o VPL decresce quando a TMA aumenta, zerando exatamente quando $TMA = TIR$; entre dois projetos mutuamente exclusivos, há conflito entre VPL e TIR para taxas abaixo da Taxa de Interseção de Fisher (prevalecendo sempre o maior VPL), e o projeto tem $VPL > 0$ se e somente se o seu Payback Descontado for menor que a vida útil $n$.', f: 'Se a Taxa Interna de Retorno (TIR) de um projeto é de 15% ao ano e a TMA da empresa é de 18% ao ano, o VPL do projeto é positivo.', exp: 'Se $TIR = 15\\% < TMA = 18\\%$, em um projeto convencional de investimento o $VPL$ é NEGATIVO (inviável).' }
  ]
};

export const ECONOMIA_LESSON_MATRIX: SubjectLessonMatrix = {
  0: [
    { sub: 'Escassez, Custo de Oportunidade e Fronteira de Possibilidades de Produção (FPP)', ref: 'Fundamentos de Economia', t: 'A Fronteira (ou Curva) de Possibilidades de Produção (FPP) ilustra os conceitos de escassez, eficiência produtiva (pontos sobre a curva) e custo de oportunidade; a concavidade da FPP em relação à origem decorre da lei dos custos de oportunidade crescentes (rendimentos marginais decrescentes na transferência de fatores).', f: 'Pontos situados no interior (abaixo) da Fronteira de Possibilidades de Produção são tecnologicamente inatingíveis no curto prazo.', exp: 'Pontos sobre a FPP = eficientes (pleno emprego); pontos internos = ineficientes (recursos ociosos); pontos externos = inatingíveis com a tecnologia e recursos atuais.' },
    { sub: 'Deslocamento da Curva de Demanda vs. Movimento Ao Longo da Curva', ref: 'Oferta e Demanda', t: 'Variações no próprio preço do bem provocam movimento AO LONGO da curva de demanda (variação da quantidade demandada); já alterações na renda dos consumidores, nos preços de bens relacionados (substitutos ou complementares) ou nas preferências deslocam TODA a curva de demanda.', f: 'Um aumento no preço do próprio bem desloca toda a curva de demanda para a esquerda.', exp: 'Mudou o preço do próprio bem (variável do eixo vertical) -> movimento sobre a mesma curva; mudou variável exógena (renda, gostos, outros preços) -> deslocamento da curva.' },
    { sub: 'Deslocamento da Curva de Oferta e Equilíbrio de Mercado', ref: 'Oferta e Demanda', t: 'Avanços tecnológicos e reduções nos preços dos insumos deslocam a curva de oferta para a direita (para baixo), reduzindo o preço de equilíbrio e aumentando a quantidade de equilíbrio, ceteris paribus.', f: 'A criação de um imposto específico sobre os produtores desloca a curva de oferta para a direita, reduzindo o preço pago pelo consumidor.', exp: 'Imposto sobre vendas ou aumento de custo de insumos desloca a oferta para cima/esquerda, elevando o preço de equilíbrio e reduzindo a quantidade.' },
    { sub: 'Excedente do Consumidor, Excedente do Produtor e Peso Morto (Perda de Eficiência)', ref: 'Bem-Estar em Equilíbrio Parcial', t: 'O Excedente do Consumidor é a área abaixo da curva de demanda e acima do preço pago; o Excedente do Produtor é a área acima da curva de oferta e abaixo do preço recebido; no equilíbrio competitivo livre sem falhas de mercado, o Excedente Total (soma dos dois) é maximizado, sem peso morto.', f: 'A imposição de um teto de preços efetivo (abaixo do preço de equilíbrio, ex: tabelamento de aluguéis) gera excesso de oferta e aumenta o excedente total.', exp: 'Preço máximo (teto) abaixo do equilíbrio -> escassez (excesso de demanda) e peso morto. Preço mínimo (piso) acima do equilíbrio -> excedente (excesso de oferta) e peso morto.' },
    { sub: 'Economia Positiva vs. Economia Normativa', ref: 'Metodologia Econômica', t: 'A economia positiva ocupa-se de descrever e explicar "o que é" (fatos e relações de causa e efeito empiricamente testáveis), enquanto a economia normativa envolve juízos de valor éticos ou políticos sobre "o que deveria ser".', f: 'A afirmação "o governo deveria aumentar o imposto sobre grandes fortunas para promover justiça social" é uma proposição de economia estritamente positiva.', exp: 'Positiva = fatos objetivos ("o que é"); Normativa = juízo de valor prescritivo ("o que deveria ser").' }
  ],
  1: [
    { sub: 'Elasticidade-Preço da Demanda ($\varepsilon_d$) e Classificação', ref: 'Elasticidades', t: 'A elasticidade-preço da demanda mede a variação percentual na quantidade demandada dividida pela variação percentual no preço: $\\varepsilon_d = (\\Delta Q / Q) / (\\Delta P / P) = (dQ / dP) \\cdot (P / Q)$; em módulo, a demanda é elástica se $|\\varepsilon_d| > 1$, unitária se $|\\varepsilon_d| = 1$, inelástica se $0 < |\\varepsilon_d| < 1$ e perfeitamente inelástica se $\\varepsilon_d = 0$.', f: 'Em uma curva de demanda linear negativamente inclinada ($Q = a - bP$), a elasticidade-preço da demanda é constante em todos os pontos da reta.', exp: 'Pegadinha clássica FGV: na demanda linear, a INCLINAÇÃO é constante, mas a ELASTICIDADE varia de $\\infty$ (no intercepto vertical) a $1$ (no ponto médio) até $0$ (no intercepto horizontal)!' },
    { sub: 'Relação entre Elasticidade-Preço da Demanda e Receita Total ($RT = P \\cdot Q$)', ref: 'Elasticidade e Receita Total', t: 'Pela relação $RMg = P(1 - 1/|\\varepsilon_d|)$: quando a demanda é INELÁSTICA ($|\\varepsilon_d| < 1$), um aumento no preço eleva a Receita Total; quando a demanda é ELÁSTICA ($|\\varepsilon_d| > 1$), um aumento no preço reduz a Receita Total; e a Receita Total é máxima exatamente onde a elasticidade é unitária ($|\\varepsilon_d| = 1$).', f: 'Quando a demanda por um bem é preço-elástica ($|\\varepsilon_d| = 2$), a empresa deve aumentar o preço para aumentar sua receita total.', exp: 'Demanda inelástica ($|\\varepsilon| < 1$): $P$ e $RT$ caminham no MESMO sentido. Demanda elástica ($|\\varepsilon| > 1$): $P$ e $RT$ caminham em sentidos OPOSTOS.' },
    { sub: 'Elasticidade-Renda da Demanda ($\varepsilon_R$): Bem Normal, Inferior, Supérfluo e Lei de Engel', ref: 'Elasticidade-Renda', t: 'Pela elasticidade-renda da demanda ($\\varepsilon_R = (\\%\\Delta Q) / (\\%\\Delta R)$): se $\\varepsilon_R < 0$, o bem é INFERIOR; se $\\varepsilon_R > 0$, o bem é NORMAL, subdividindo-se em bem necessário/essencial ($0 < \\varepsilon_R \\le 1$) e bem superior/de luxo ($\\varepsilon_R > 1$, cuja participação no orçamento cresce com a renda).', f: 'Um bem cuja quantidade demandada diminui quando a renda do consumidor aumenta possui elasticidade-renda positiva superior a 1.', exp: '$\\varepsilon_R < 0$ = Bem Inferior; $0 < \\varepsilon_R < 1$ = Bem Normal Necessário (alimentos básicos - Lei de Engel); $\\varepsilon_R > 1$ = Bem Normal de Luxo/Superior.' },
    { sub: 'Elasticidade-Preço Cruzada da Demanda ($\varepsilon_{XY}$): Substitutos vs. Complementares', ref: 'Elasticidade Cruzada', t: 'A elasticidade-preço cruzada mede a resposta percentual na quantidade demandada do bem $X$ diante de uma variação percentual no preço do bem $Y$: se $\\varepsilon_{XY} > 0$, os bens $X$ e $Y$ são SUBSTITUTOS (concorrentes); se $\\varepsilon_{XY} < 0$, são COMPLEMENTARES; se $\\varepsilon_{XY} = 0$, são independentes.', f: 'Dois bens estreitamente complementares (como café e açúcar ou impressora e cartucho) possuem elasticidade-preço cruzada positiva.', exp: 'Preço de $Y$ subiu e demanda de $X$ subiu ($\\varepsilon_{XY} > 0$) $\\implies$ Substitutos (manteiga e margarina). Preço de $Y$ subiu e demanda de $X$ caiu ($\\varepsilon_{XY} < 0$) $\\implies$ Complementares.' },
    { sub: 'Incidência Econômica de Impostos e Elasticidades', ref: 'Incidência Tributária', t: 'Na introdução de um imposto indireto sobre um mercado, o ônus econômico do imposto recai mais pesadamente sobre o lado do mercado (consumidor ou produtor) que for MAIS INELÁSTICO (menos sensível ao preço), independentemente de quem a lei designe como contribuinte de direito.', f: 'Se a demanda for perfeitamente elástica (horizontal), o consumidor arcará com 100% do ônus econômico do imposto.', exp: 'Regra de ouro de Finanças Públicas e Microeconomia: quem é mais INELÁSTICO (tem menos rotas de fuga) paga a maior parte do imposto! Se demanda é perfeitamente inelástica, o consumidor paga 100%.' }
  ],
  2: [
    { sub: 'Axiomas das Preferências e Propriedades das Curvas de Indiferença', ref: 'Teoria do Consumidor', t: 'Sob os axiomas de completude, transitividade, monotonicidade (não saciedade) e convexidade estrita, as curvas de indiferença para dois bens desejáveis são negativamente inclinadas, NUNCA se cruzam (pela transitividade + não saciedade) e são estritamente convexas em relação à origem (TMS decrescente).', f: 'Duas curvas de indiferença pertencentes ao mesmo consumidor racional podem se cruzar no ponto de equilíbrio ótimo.', exp: 'Se duas curvas de indiferença de níveis distintos de utilidade se cruzassem, haveria violação da transitividade e da monotonicidade!' },
    { sub: 'Taxa Marginal de Substituição (TMS) e Razão das Utilidades Marginais', ref: 'Taxa Marginal de Substituição', t: 'A Taxa Marginal de Substituição de $Y$ por $X$ ($TMS_{XY} = -dY/dX$ ao longo da curva de indiferença) mede o quanto do bem $Y$ o consumidor está disposto a abrir mão para obter uma unidade adicional de $X$ mantendo a utilidade constante, sendo igual à razão das utilidades marginais: $TMS_{XY} = UMg_X / UMg_Y$.', f: 'Ao longo de uma curva de indiferença estritamente convexa, a Taxa Marginal de Substituição aumenta à medida que o consumidor acumula mais do bem $X$.', exp: 'Pela convexidade (preferência pela variedade), quanto mais $X$ e menos $Y$ o consumidor tem, menor é a $TMS_{XY} = UMg_X / UMg_Y$ (lei da TMS decrescente).' },
    { sub: 'Formatos Especiais: Substitutos Perfeitos, Complementares Perfeitos (Leontief) e Cobb-Douglas', ref: 'Funções de Utilidade', t: 'Para bens substitutos perfeitos ($U = aX + bY$), as curvas de indiferença são retas paralelas com $TMS = a/b$ constante; para complementares perfeitos ($U = \\min\\{aX, bY\\}$), têm formato em "L" (ângulo reto sobre o raio $aX = bY$); e na Cobb-Douglas ($U = X^\\alpha Y^\\beta$), o consumidor gasta sempre a fração constante $\\alpha / (\\alpha + \\beta)$ da renda no bem $X$.', f: 'Para bens complementares perfeitos (ex: pé direito e pé esquerdo de sapato), as curvas de indiferença são linhas retas com inclinação de $-45^\\circ$.', exp: 'Substitutos perfeitos = retas (solução de canto se $a/b \\ne P_X/P_Y$); Complementares perfeitos (Leontief) = formato em "L" (ótimo no vértice $aX = bY$); Cobb-Douglas = hipérboles convexas.' },
    { sub: 'Equilíbrio Ótimo do Consumidor (Condição de Tangência)', ref: 'Maximização de Utilidade', t: 'Em uma solução interior para preferências regulares, o consumidor maximiza sua utilidade sujeito à restrição orçamentária $P_X X + P_Y Y = R$ no ponto de tangência onde a inclinação da curva de indiferença iguala a inclinação da reta orçamentária: $TMS_{XY} = UMg_X / UMg_Y = P_X / P_Y$ (ou $UMg_X / P_X = UMg_Y / P_Y$).', f: 'O equilíbrio ótimo do consumidor ocorre sempre no ponto onde a utilidade marginal de ambos os bens é igual a zero ($UMg_X = UMg_Y = 0$).', exp: 'Princípio da Equimarginalidade (2ª Lei de Gossen): a última unidade monetária gasta em cada bem deve proporcionar a mesma utilidade marginal ($UMg_X / P_X = UMg_Y / P_Y$).' },
    { sub: 'Equação de Slutsky: Efeito Substituição, Efeito Renda e Bem de Giffen', ref: 'Efeito Preço = ES + ER', t: 'O Efeito Total de uma variação no preço de um bem decompõe-se em Efeito Substituição (ES, mantendo o poder de compra/utilidade constante, que é SEMPRE negativo em relação ao preço: se $P$ cai, o ES aumenta $Q$) e Efeito Renda (ER); em um Bem de Giffen, o bem é tão fortemente inferior que o efeito renda negativo supera em módulo o efeito substituição, fazendo a demanda cair quando o preço cai!', f: 'Todo bem inferior é necessariamente um Bem de Giffen com curva de demanda positivamente inclinada.', exp: 'Pegadinha clássica FGV: Todo Bem de Giffen é um bem inferior, mas NEM TODO bem inferior é de Giffen! (Bem Inferior comum: ER oposto ao ES, mas $|ES| > |ER|$, logo ainda obedece à Lei da Demanda; Bem de Giffen: Bem Inferior com $|ER| > |ES|$, violando a Lei da Demanda).' }
  ],
  3: [
    { sub: 'Curto Prazo vs. Longo Prazo na Teoria da Produção', ref: 'Teoria da Produção', t: 'Na microeconomia, o curto prazo é definido como o horizonte em que pelo menos um fator de produção é fixo (geralmente o capital $K$), enquanto o longo prazo é o horizonte em que TODOS os fatores de produção ($K$ e $L$) são variáveis.', f: 'Na teoria microeconômica, curto prazo refere-se exclusivamente a períodos inferiores a 360 dias no calendário civil.', exp: 'A distinção microeconômica entre curto e longo prazo não é cronológica/contábil, mas sim tecnológica: existência ou não de insumos fixos!' },
    { sub: 'Produto Total ($PT$), Produto Médio ($PMe$) e Produto Marginal ($PMg$) no Curto Prazo', ref: 'Produtividade no Curto Prazo', t: 'A curva de Produto Marginal do trabalho ($PMg_L = \\partial Q / \\partial L$) corta a curva de Produto Médio ($PMe_L = Q / L$) exatamente no ponto de MÁXIMO do Produto Médio: enquanto $PMg_L > PMe_L$, o $PMe_L$ é crescente; quando $PMg_L < PMe_L$, o $PMe_L$ é decrescente; e o Produto Total é máximo quando $PMg_L = 0$.', f: 'A empresa competitiva racional opera sempre no estágio III da produção, onde o produto marginal da mão de obra é negativo ($PMg_L < 0$).', exp: 'Os 3 Estágios da Produção: Estágio I (até o máximo do $PMe_L$); Estágio II (do máximo do $PMe_L$, onde $PMg_L = PMe_L$, até $PMg_L = 0$ -> ÚNICO estágio racional de operação!); Estágio III ($PMg_L < 0$).' },
    { sub: 'Lei dos Rendimentos Marginais Decrescentes', ref: 'Lei dos Rendimentos Decrescentes', t: 'A Lei dos Rendimentos Marginais Decrescentes (que é um fenômeno de CURTO PRAZO) estabelece que, mantendo-se fixos os demais insumos (como o capital) e a tecnologia, o acréscimo sucessivo de unidades de um fator variável (trabalho) fará com que, a partir de certo ponto, o produto marginal desse fator passe a diminuir.', f: 'A lei dos rendimentos marginais decrescentes é sinônimo de deseconomias de escala no longo prazo quando todos os fatores dobram.', exp: 'Não confunda! Rendimentos marginais decrescentes = Curto Prazo (varia 1 fator, mantendo outro fixo); Rendimentos de escala = Longo Prazo (variam TODOS os fatores na mesma proporção).' },
    { sub: 'Isoquantas e Taxa Marginal de Substituição Técnica ($TMST$)', ref: 'Produção no Longo Prazo', t: 'Uma isoquanta representa todas as combinações de insumos ($L$ e $K$) que geram o mesmo nível de produção; sua inclinação em módulo é a Taxa Marginal de Substituição Técnica ($TMST_{LK} = -dK/dL = PMg_L / PMg_K$), e a minimização de custo da firma ocorre na tangência com a reta de isocusto: $TMST_{LK} = PMg_L / PMg_K = w / r$.', f: 'No ponto de minimização de custos de longo prazo, a razão dos produtos marginais deve ser igual a zero.', exp: 'Condição de ótimo técnico-econômico da firma: $PMg_L / w = PMg_K / r$ (o último real gasto em trabalho gera o mesmo produto adicional que o último real gasto em capital).' },
    { sub: 'Rendimentos de Escala (Constantes, Crescentes e Decrescentes)', ref: 'Rendimentos de Escala', t: 'No longo prazo, ao multiplicar todos os insumos por um escalar $\\lambda > 1$: se $f(\\lambda K, \\lambda L) = \\lambda f(K, L)$, há rendimentos constantes de escala; se $> \\lambda f(K, L)$, crescentes; se $< \\lambda f(K, L)$, decrescentes; em uma função Cobb-Douglas $Q = A K^\\alpha L^\\beta$, os rendimentos de escala dependem da soma $\\alpha + \\beta$ ($= 1$ constantes, $> 1$ crescentes, $< 1$ decrescentes).', f: 'A função de produção $Q = 10 K^{0{,}3} L^{0{,}4}$ apresenta rendimentos crescentes de escala porque a constante multiplicativa é 10.', exp: 'Grau de homogeneidade na Cobb-Douglas (e na CES) é dado pela soma dos expoentes: $0{,}3 + 0{,}4 = 0{,}7 < 1 \\implies$ rendimentos DECRESCENTES de escala!' }
  ],
  4: [
    { sub: 'Custos Contábeis (Explícitos) vs. Custos Econômicos (Explícitos + Implícitos / Oportunidade)', ref: 'Conceitos de Custo', t: 'Enquanto o custo contábil considera apenas os desembolsos explícitos, o custo econômico inclui também os custos implícitos (custo de oportunidade do capital próprio dos sócios e do trabalho do proprietário); por isso, um Lucro Econômico igual a zero significa que a empresa está obtendo exatamente o Lucro Normal de mercado.', f: 'Quando uma firma em concorrência perfeita obtém lucro econômico igual a zero no longo prazo, seus proprietários têm prejuízo contábil e fecham a empresa.', exp: 'Lucro Econômico $= 0 \\iff$ Receita Total cobre todos os custos explícitos E remunera o capital próprio exatamente ao seu custo de oportunidade (Lucro Normal)!' },
    { sub: 'Custos de Curto Prazo: $CT, CF, CV, CTMe, CVMe, CFMe$ e Custo Marginal ($CMg$)', ref: 'Custos no Curto Prazo', t: 'No curto prazo, $CT(Q) = CF + CV(Q)$ e $CTMe = CFMe + CVMe$; o Custo Fixo Médio ($CFMe = CF / Q$) é uma hipérbole sempre decrescente, e a curva de Custo Marginal ($CMg = dCT / dQ = dCV / dQ$) corta tanto a curva de Custo Variável Médio ($CVMe$) quanto a curva de Custo Total Médio ($CTMe$) exatamente nos respectivos pontos de MÍNIMO.', f: 'O Custo Marginal depende diretamente do valor do Custo Fixo da empresa.', exp: 'Como a derivada de uma constante é zero ($dCF / dQ = 0$), o Custo Marginal independe do Custo Fixo! Além disso, o mínimo do $CVMe$ ocorre antes (a uma quantidade menor) que o mínimo do $CTMe$.' },
    { sub: 'Dualidade entre Produtividade e Custos no Curto Prazo', ref: 'Dualidade Produção-Custos', t: 'Como $CV = w \\cdot L$, valem as relações de espelho (dualidade): $CVMe = w / PMe_L$ e $CMg = w / PMg_L$; assim, quando o Produto Marginal ($PMg_L$) é máximo, o Custo Marginal ($CMg$) é mínimo; e quando o Produto Médio ($PMe_L$) é máximo, o Custo Variável Médio ($CVMe$) é mínimo!', f: 'Quando a produtividade média do trabalho está aumentando, o custo variável médio de produção também está aumentando.', exp: 'Espelho perfeito: $PMe_L$ máximo $\\iff CVMe$ mínimo; $PMg_L$ máximo $\\iff CMg$ mínimo!' },
    { sub: 'Curva de Custo Médio de Longo Prazo ($CMeLP$ / Curva Envoltória)', ref: 'Custos no Longo Prazo', t: 'A curva de Custo Médio de Longo Prazo ($CMeLP$) é a envoltória inferior das curvas de Custo Total Médio de Curto Prazo ($CTMeCP$); seu formato em "U" reflete economias de escala no trecho decrescente, rendimentos constantes no ponto mínimo (escala mínima eficiente) e deseconomias de escala no trecho crescente.', f: 'As curvas de custo médio de curto prazo situam-se sempre abaixo da curva de custo médio de longo prazo.', exp: 'Como no longo prazo a firma tem mais flexibilidade (pode ajustar $K$), $CMeLP(Q) \\le CTMeCP(Q)$ para todo $Q$, tangenciando no ponto mínimo apenas na planta da escala ótima.' },
    { sub: 'Custos Irrecuperáveis (Sunk Costs) e Economias de Escopo', ref: 'Sunk Costs e Escopo', t: 'Custos irrecuperáveis (sunk costs) são gastos já incorridos que não podem ser recuperados caso a atividade cesse e, portanto, devem ser ignorados nas decisões econômicas marginais futuras; já as economias de escopo ocorrem quando é mais barato produzir dois bens conjuntamente na mesma firma do que em duas firmas separadas: $C(Q_1, Q_2) < C(Q_1, 0) + C(0, Q_2)$.', f: 'Um custo irrecuperável (sunk cost) deve ser somado ao custo marginal para decidir o preço ótimo de venda.', exp: 'Regra de ouro microeconômica: Sunk costs são águas passadas e NUNCA afetam decisões prospectivas (marginais).' }
  ],
  5: [
    { sub: 'Hipóteses da Concorrência Perfeita e Demanda da Firma Individual', ref: 'Concorrência Perfeita', t: 'Em concorrência perfeita (atomicidade de compradores e vendedores, produto homogêneo, livre entrada/saída e transparência perfeita), cada firma individual é tomadora de preços (price taker), enfrentando uma curva de demanda perfeitamente elástica (horizontal) ao preço de mercado: $P = RMg = RMe$.', f: 'Em concorrência perfeita, a curva de demanda de todo o mercado é uma linha reta horizontal.', exp: 'Cuidado! A curva de demanda do MERCADO (indústria) é negativamente inclinada; a curva de demanda da FIRMA INDIVIDUAL é que é horizontal ($P = RMg = RMe$)!' },
    { sub: 'Maximização de Lucro da Firma Competitiva ($P = CMg$)', ref: 'Condição de Ótimo Competitivo', t: 'Para maximizar o lucro ($\pi = RT - CT$), qualquer firma produz onde $RMg = CMg$ (com $CMg$ crescente); como na concorrência perfeita $RMg = P$, a regra de maximização de lucro da firma competitiva é igualar o Preço ao Custo Marginal: $P = CMg(Q)$ no trecho ascendente do $CMg$.', f: 'A firma em concorrência perfeita maximiza seu lucro total produzindo na quantidade onde o Custo Total Médio é mínimo.', exp: 'Em $P = CTMe_{\\text{mín}}$, o lucro econômico é ZERO (ponto de nivelamento / break-even). Para maximizar o lucro quando $P > CTMe$, a firma produz onde $P = CMg$!' },
    { sub: 'Ponto de Fechamento (Encerramento) e Curva de Oferta de Curto Prazo', ref: 'Oferta de Curto Prazo', t: 'No curto prazo, a firma competitiva continua operando mesmo com prejuízo econômico desde que o preço cubra pelo menos o Custo Variável Médio ($P \\ge CVMe_{\\text{mín}}$, pois ajuda a pagar parte do custo fixo); se $P < CVMe_{\\text{mín}}$ (ponto de fechamento / shutdown point), a firma fecha e produz $Q = 0$; logo, a curva de oferta da firma no curto prazo é o trecho crescente do $CMg$ a partir do mínimo do $CVMe$.', f: 'No curto prazo, sempre que o preço de mercado cair abaixo do Custo Total Médio ($P < CTMe$), a firma deve fechar imediatamente e produzir zero.', exp: 'Se $CVMe_{\\text{mín}} < P < CTMe$, a firma tem prejuízo menor que o Custo Fixo ao operar, logo CONTINUA produzindo no curto prazo! Só fecha se $P < CVMe_{\\text{mín}}$.' },
    { sub: 'Equilíbrio Competitivo de Longo Prazo (Lucro Econômico Zero)', ref: 'Longo Prazo em Concorrência Perfeita', t: 'No longo prazo, devido à livre entrada e saída de firmas atraídas por lucros extraordinários ou expulsas por prejuízos, o preço de mercado converge para o ponto mínimo do Custo Médio de Longo Prazo: $P = CMgLP = CMeLP_{\\text{mín}}$, onde todas as firmas marginais operam na escala mínima eficiente com Lucro Econômico igual a zero.', f: 'No equilíbrio de longo prazo da concorrência perfeita, as firmas auferem lucros econômicos extraordinários positivos permanentes.', exp: 'Se há lucro extraordinário ($\pi > 0$), entram novas firmas $\\implies$ oferta de mercado desloca para a direita $\\implies$ preço cai até $P = CMeLP_{\\text{mín}}$ ($\pi = 0$).' },
    { sub: 'Eficiência de Pareto e 1º Teorema do Bem-Estar na Concorrência Perfeita', ref: 'Eficiência Alocativa', t: 'O equilíbrio de concorrência perfeita (sem externalidades ou bens públicos) é eficiente no sentido de Pareto e maximiza o excedente social total porque o preço iguala o Custo Marginal ($P = CMg$), significando que o benefício marginal social da última unidade consumida iguala exatamente o custo marginal social de produzi-la.', f: 'A concorrência perfeita gera um peso morto social maior do que o monopólio puro.', exp: 'Em concorrência perfeita: $P = CMg \\implies$ peso morto zero (eficiência alocativa máxima).' }
  ],
  6: [
    { sub: 'Receita Marginal do Monopolista e Maximização de Lucro ($RMg = CMg < P$)', ref: 'Monopólio Puro', t: 'Como o monopolista enfrenta toda a curva de demanda de mercado (negativamente inclinada), para vender uma unidade a mais no monopólio de preço único ele precisa reduzir o preço de todas as unidades, de modo que a Receita Marginal é sempre menor que o preço ($RMg < P$; se a demanda é linear $P = a - bQ$, então $RMg = a - 2bQ$ tem o dobro da inclinação!), e no ótimo tem-se $P > RMg = CMg$.', f: 'No monopólio puro, a curva de oferta do monopolista é o trecho crescente do seu Custo Marginal.', exp: 'Pegadinha clássica FGV: o monopolista NÃO TEM curva de oferta (não há relação unívoca entre preço e quantidade independente da elasticidade da demanda)!' },
    { sub: 'Regra de Markup e Índice de Poder de Monopólio de Lerner ($L$)', ref: 'Índice de Lerner', t: 'Da condição $RMg = P(1 - 1/|\\varepsilon_d|) = CMg$, obtém-se o Índice de Lerner de poder de mercado: $L = (P - CMg) / P = 1 / |\\varepsilon_d| = -1 / \\varepsilon_d$; consequentemente, o monopolista que maximiza lucro com $CMg > 0$ NUNCA opera no trecho inelástico da demanda (opera sempre onde $|\\varepsilon_d| \\ge 1$)!', f: 'O monopolista maximizador de lucro escolhe operar sempre no trecho inelástico da curva de demanda ($|\\varepsilon_d| < 1$).', exp: 'Se $|\\varepsilon_d| < 1$, a Receita Marginal seria negativa ($RMg < 0$), o que jamais pode igualar um Custo Marginal positivo ($CMg > 0$)! Em concorrência perfeita, $|\\varepsilon_d| = \\infty \\implies L = 0$.' },
    { sub: 'Ineficiência Alocativa (Peso Morto) do Monopólio', ref: 'Bem-Estar no Monopólio', t: 'Comparado à concorrência perfeita, o monopólio de preço único produz uma quantidade MENOR ($Q_m < Q_c$) e cobra um preço MAIOR ($P_m > P_c$), transferindo parte do excedente do consumidor para o produtor e gerando uma perda líquida de eficiência alocativa (peso morto de Harberger) porque $P_m > CMg$.', f: 'No monopólio de preço único, a quantidade produzida é maior que a de concorrência perfeita.', exp: 'Como $RMg < P$, a interseção $RMg = CMg$ ocorre a uma quantidade menor que a interseção competitiva $P = CMg$.' },
    { sub: 'Discriminação de Preços de 1º, 2º e 3º Graus (Classificação de Pigou)', ref: 'Discriminação de Preços', t: 'Na discriminação de 1º grau (perfeita), o monopolista cobra de cada unidade o preço máximo de reserva do consumidor, apropriando-se de 100% do excedente do consumidor e eliminando o peso morto ($Q = Q_c$); na de 2º grau, cobra preços diferentes conforme a quantidade/bloco comprado (autosseleção, tarifas em duas partes); e na de 3º grau, segmenta mercados com elasticidades distintas, cobrando preço MAIOR no mercado cuja demanda é MAIS INELÁSTICA.', f: 'Na discriminação de preços de 3º grau (ex: meia-entrada para estudantes), o monopolista cobra o preço mais alto do grupo que possui a demanda mais elástica.', exp: 'Na discriminação de 3º grau ($RMg_1 = RMg_2 = CMg$): $P_1(1 - 1/|\\varepsilon_1|) = P_2(1 - 1/|\\varepsilon_2|) \\implies$ quem tem menor $|\\varepsilon|$ (demanda mais inelástica) paga preço MAIOR!' },
    { sub: 'Monopólio Natural e Regulação pelo Custo Médio vs. Custo Marginal', ref: 'Monopólio Natural', t: 'Um monopólio natural ocorre quando há subaditividade de custos (fortes economias de escala para toda a demanda do mercado, com $CMe$ decrescente e $CMg < CMe$); se o regulador fixar $P = CMg$ (first-best), a firma terá prejuízo ($P < CMe$), exigindo subsídio ou regulação second-best pelo Custo Médio ($P = CMe$, lucro econômico zero).', f: 'Em um monopólio natural operando com economias de escala, o Custo Marginal está sempre acima do Custo Médio.', exp: 'Enquanto o Custo Médio é decrescente (economias de escala), o Custo Marginal é necessariamente MENOR que o Custo Médio ($CMg < CMe$).' }
  ],
  7: [
    { sub: 'Concorrência Monopolística (Chamberlin): Curto vs. Longo Prazo', ref: 'Concorrência Monopolística', t: 'Na concorrência monopolística, há muitas firmas vendendo produtos diferenciados (substitutos próximos, gerando curva de demanda levemente inclinada e $P > CMg$) mas com LIVRE entrada e saída; por isso, no longo prazo a entrada de rivais desloca a demanda até tangenciar o Custo Médio, zerando o lucro econômico ($P = CMe$) com excesso de capacidade instalada (opera à esquerda do mínimo do $CMe$).', f: 'Na concorrência monopolística, a existência de fortes barreiras legais à entrada garante lucro econômico positivo no longo prazo.', exp: 'Concorrência Monopolística combina: (a) diferenciação de produto ($P > RMg = CMg$, como no monopólio); e (b) livre entrada ($\pi = 0 \implies P = CMe$ no longo prazo, como na concorrência perfeita).' },
    { sub: 'Oligopólio de Cournot (Competição Simultânea em Quantidades)', ref: 'Modelo de Cournot', t: 'No duopólio de Cournot, duas firmas escolhem simultaneamente suas quantidades produzidas ($q_1$ e $q_2$), tratando a quantidade da rival como dada (funções de reação negativamente inclinadas); o equilíbrio de Cournot-Nash gera uma quantidade total maior que a de monopólio (cartel) e menor que a de concorrência perfeita ($Q_{\\text{Monopólio}} < Q_{\\text{Cournot}} < Q_{\\text{Competitiva}}$).', f: 'No duopólio de Cournot com bens homogêneos, o preço de equilíbrio iguala o Custo Marginal.', exp: 'Para demanda linear e custos iguais, o monopólio produz $1/2$ da quantidade competitiva e o duopólio de Cournot produz $2/3$ da quantidade competitiva ($1/3 + 1/3$).' },
    { sub: 'Oligopólio de Stackelberg (Liderança em Quantidade) vs. Bertrand (Competição em Preços)', ref: 'Stackelberg e Bertrand', t: 'No modelo de Stackelberg (jogo sequencial em quantidade), a firma líder move primeiro antecipando a função de reação da seguidora e obtém vantagem do primeiro a mover (produz mais e lucra mais que em Cournot); já no paradoxo de Bertrand (competição simultânea em preços com bens homogêneos e $CMg = c$ constante), basta duas firmas para que o preço caia até o nível competitivo $P_1 = P_2 = CMg$, com lucro econômico zero!', f: 'No modelo de Bertrand com produtos homogêneos e custos marginais idênticos constantes, as duas firmas dividem o lucro de monopólio.', exp: 'Ranking de quantidades totais e queda de preços: Monopólio/Cartel ($Q$ menor, $P$ maior) $\\to$ Cournot $\\to$ Stackelberg $\\to$ Bertrand = Concorrência Perfeita ($P = CMg$).' },
    { sub: 'Teoria dos Jogos: Estratégia Dominante e Equilíbrio de Nash', ref: 'Teoria dos Jogos', t: 'Uma estratégia é estritamente dominante quando proporciona payoff maior para o jogador independentemente do que o oponente faça; já um perfil de estratégias constitui um Equilíbrio de Nash quando cada jogador está escolhendo sua melhor resposta dada a estratégia escolhida pelos demais jogadores (nenhum jogador tem incentivo para desviar unilateralmente).', f: 'No Dilema dos Prisioneiros em jogada única, o equilíbrio de Nash em estratégias dominantes é um ótimo de Pareto para os dois jogadores.', exp: 'No Dilema dos Prisioneiros (e na guerra de preços de um cartel), "Trair/Delatar" é estratégia dominante para ambos, gerando um Equilíbrio de Nash que é Pareto-ineficiente (pior para ambos do que cooperar)!' },
    { sub: 'Cartel (Conluio) e Curva de Demanda Quebrada (Sweezy)', ref: 'Cartel e Sweezy', t: 'Em um cartel perfeito, as firmas agem como um monopolista multiplantas ($RMg = CMg_1 = CMg_2$), mas cada membro tem incentivo individual a trapacear produzindo além da cota; já no modelo da demanda quebrada de Sweezy, as rivais acompanham reduções de preço mas ignoram aumentos de preço, gerando uma descontinuidade (hiato vertical) na Receita Marginal que explica a rigidez de preços.', f: 'Em um cartel estável em jogo de uma única rodada sem punição, nenhum participante tem incentivo econômico para vender secretamente acima da sua cota.', exp: 'Como no cartel $P > CMg$, cada firma individualmente aumenta seu lucro se produzir um pouco a mais (daí a instabilidade intrínseca dos cartéis, que só se sustentam em jogos repetidos tipo tit-for-tat).' }
  ],
  8: [
    { sub: 'Classificação dos Bens: Rivalidade e Excludibilidade (Bens Públicos Puros)', ref: 'Bens Públicos', t: 'Um Bem Público Puro (como defesa nacional ou iluminação pública) caracteriza-se simultaneamente pela NÃO RIVALIDADE no consumo (o consumo por um indivíduo não reduz a quantidade disponível para outros, custo marginal de um usuário adicional é zero) e pela NÃO EXCLUDIBILIDADE (é impossível ou proibitivamente caro impedir quem não paga de usufruir do bem).', f: 'Os bens privados puros (como alimentos e roupas) são não rivais e não excludentes.', exp: 'Quadro 2x2 da FGV: (1) Rival + Excludente = Bem Privado; (2) Não Rival + Não Excludente = Bem Público Puro; (3) Rival + Não Excludente = Recurso Comum (cardume no oceano -> Tragédia dos Comuns); (4) Não Rival + Excludente = Bem de Clube / Monopólio Natural (TV a cabo, pedágio sem congestionamento).' },
    { sub: 'Problema do Carona (Free Rider) e Condição de Samuelson para Bens Públicos', ref: 'Condição de Samuelson', t: 'Como os bens públicos puros são não excludentes, surge o problema do carona (free rider), levando à subprovisão pelo mercado privado; a demanda agregada por um bem público é obtida pela SOMA VERTICAL das disposições marginais a pagar individuais, resultando na condição de eficiência de Samuelson: $\\sum TMS_i = CMg$.', f: 'A curva de demanda de mercado por um bem público puro é obtida pela soma horizontal das quantidades consumidas por cada cidadão.', exp: 'Bem Privado: mesmo preço para todos, soma-se a quantidade (soma HORIZONTAL, $TMS_1 = TMS_2 = CMg$). Bem Público: mesma quantidade para todos, somam-se as disposições a pagar (soma VERTICAL, $\\sum TMS_i = CMg$)!' },
    { sub: 'Externalidades Negativas e Positivas e Imposto/Subsídio Pigouviano', ref: 'Externalidades e Pigou', t: 'Quando uma atividade gera externalidade negativa (ex: poluição industrial), o Custo Marginal Social supera o Custo Marginal Privado ($CMgS = CMgP + DMg$), fazendo o mercado livre produzir ACIMA do ótimo social; a solução de Pigou consiste em cobrar um imposto por unidade igual ao dano marginal externo no ponto ótimo ($t = DMg(Q^*)$), internalizando a externalidade.', f: 'Na presença de uma externalidade positiva (como vacinação ou educação básica), o mercado livre produz uma quantidade superior à socialmente ótima.', exp: 'Externalidade Negativa $\\implies Q_{\\text{mercado}} > Q_{\\text{ótimo}}$ (corrige com Imposto Pigouviano). Externalidade Positiva $\\implies Q_{\\text{mercado}} < Q_{\\text{ótimo}}$ (corrige com Subsídio Pigouviano).' },
    { sub: 'Teorema de Coase (Direitos de Propriedade e Custos de Transação)', ref: 'Teorema de Coase', t: 'Segundo o Teorema de Coase, se os direitos de propriedade estiverem claramente definidos e os custos de transação (negociação) forem nulos, as partes privadas negociarão voluntariamente uma solução eficiente de Pareto para a externalidade, independentemente de a qual das partes a lei tenha atribuído inicialmente o direito de propriedade.', f: 'O Teorema de Coase afirma que a negociação privada é eficiente mesmo quando os custos de transação são proibitivos e envolvem milhões de agentes difusos.', exp: 'Atenção: pelo Teorema de Coase (com custos de transação zero e sem efeito renda), a ALOCAÇÃO final de recursos é eficiente e independe de quem recebeu o direito de propriedade, embora a DISTRIBUIÇÃO de riqueza dependa de quem detém o direito!' },
    { sub: 'Assimetria de Informação: Seleção Adversa (Akerlof) vs. Risco Moral (Moral Hazard)', ref: 'Informação Assimétrica', t: 'A Seleção Adversa é uma assimetria de informação PRÉ-CONTRATUAL (informação oculta antes da transação, ex: mercado de carros usados/"limões" de Akerlof ou planos de saúde atraindo clientes de maior risco), combatida por sinalização (signaling, ex: garantia, diploma) e triagem (screening, ex: franquia); já o Risco Moral é PÓS-CONTRATUAL (ação oculta após o contrato, ex: motorista segurado dirigir com menos cuidado ou problema principal-agente).', f: 'O risco moral ocorre sempre antes da assinatura do contrato, enquanto a seleção adversa ocorre apenas após a assinatura.', exp: 'Antes do contrato (características ocultas) = Seleção Adversa; Depois do contrato (comportamento/esforço oculto) = Risco Moral (Moral Hazard).' }
  ],
  9: [
    { sub: 'As Três Óticas do PIB (Produto, Renda e Despesa) e Identidade Macroeconômica', ref: 'Contabilidade Social', t: 'Na Contabilidade Nacional, o Produto Interno Bruto (PIB) mede o valor de mercado de todos os bens e serviços FINAIS produzidos dentro do território econômico em determinado período; pelas três óticas equivalentes, tem-se: Produto (Soma do Valor Adicionado = Valor Bruto da Produção menos Consumo Intermediário) $\\equiv$ Renda (Salários + Lucros + Juros + Aluguéis) $\\equiv$ Despesa ($Y = C + I + G + X - M$).', f: 'O valor das matérias-primas intermediárias (como a farinha comprada pela padaria para fazer pão) deve ser somado ao valor final do pão no cálculo do PIB.', exp: 'Para evitar a dupla contagem no PIB, computam-se apenas os bens e serviços FINAIS (ou soma-se o Valor Adicionado em cada etapa produtiva). Transações meramente financeiras (compra de ações, transferências previdenciárias) e venda de bens usados de anos anteriores NÃO entram no PIB!' },
    { sub: 'PIB (Interno) vs. PNB / RNB (Nacional) e Renda Líquida Enviada ao Exterior (RLEE)', ref: 'PIB vs. PNB', t: 'Enquanto o PIB mede a produção realizada dentro das fronteiras geográficas do país, o Produto Nacional Bruto (PNB, ou Renda Nacional Bruta - RNB) mede a renda apropriada pelos residentes do país: $PNB = PIB - RLEE$ (ou $PNB = PIB + RLR$, onde $RLEE$ é a Renda Líquida Enviada ao Exterior: remessas de lucros, juros e salários pagos a não residentes menos os recebidos do exterior).', f: 'Em países em desenvolvimento como o Brasil, onde a Renda Líquida Enviada ao Exterior é historicamente positiva ($RLEE > 0$), o PNB é maior que o PIB.', exp: 'Fórmula clássica da FGV: $PIB = PNB + RLEE \\iff PNB = PIB - RLEE$. Como no Brasil $RLEE > 0$ (enviamos mais juros/lucros do que recebemos), no Brasil temos $PIB > PNB$!' },
    { sub: 'Preços de Mercado vs. Custo de Fatores e Bruto vs. Líquido', ref: 'Agregados a Custo de Fatores e Líquidos', t: 'Passa-se de Custo de Fatores (ou Preços Básicos) para Preços de Mercado somando-se os Impostos Indiretos ($II$) líquidos de Subsídios ($Sub$): $PIB_{pm} = PIB_{cf} + (II - Sub)$; e passa-se de Bruto para Líquido deduzindo-se a Depreciação (consumo de capital fixo $D$): $PIL = PIB - D$ e $PNL = PNB - D$.', f: 'Para obter o Produto Interno a Preços de Mercado a partir do Custo de Fatores, subtraem-se os impostos indiretos e somam-se os subsídios.', exp: 'Preços de Mercado = Custo de Fatores $+$ Impostos Indiretos $-$ Subsídios. Líquido = Bruto $-$ Depreciação.' },
    { sub: 'Identidade Poupança-Investimento ($I = S_{\\text{priv}} + S_{\\text{gov}} + S_{\\text{ext}}$)', ref: 'Identidade de Contas Nacionais', t: 'Pela identidade macroeconômica contábil, o Investimento Bruto Total ($I = FBCF + \\Delta\\text{Estoques}$) é sempre igual à Poupança Total ($S$), que é a soma da Poupança Privada ($S_p = Y_d - C$), da Poupança do Governo ($S_g = T - G$ em conta corrente) e da Poupança Externa ($S_e = M - X + RLEE$, equivalente ao déficit em transações correntes do Balanço de Pagamentos).', f: 'Se um país apresenta superávit em transações correntes no Balanço de Pagamentos, sua Poupança Externa é positiva.', exp: 'Atenção máxima na FGV! Poupança Externa ($S_e$) = DÉFICIT em Transações Correntes ($M - X + RLEE$). Se o país tem superávit externo, a Poupança Externa é NEGATIVA (está emprestando poupança ao resto do mundo)!' },
    { sub: 'PIB Nominal vs. PIB Real e Deflator Implícito do PIB vs. IPCA', ref: 'Deflator do PIB', t: 'O PIB Nominal é medido a preços correntes do próprio ano, enquanto o PIB Real é medido a preços constantes de um ano-base; o Deflator Implícito do PIB é a razão $(\\text{PIB Nominal} / \\text{PIB Real}) \\times 100$ (um índice do tipo Paasche que abrange todos os bens produzidos internamente, inclusive bens de capital, mas exclui bens importados).', f: 'O aumento no preço de um bem de consumo importado eleva diretamente o Deflator Implícito do PIB.', exp: 'Bens importados entram no IPC/IPCA (cesta do consumidor, tipo Laspeyres), mas NÃO entram no Deflator do PIB (que só mede o que é produzido internamente).' }
  ],
  10: [
    { sub: 'Função Consumo Keynesiana, Propensão Marginal a Consumir ($PMgC$) e a Poupar ($PMgS$)', ref: 'Modelo Keynesiano Simples', t: 'Na função consumo keynesiana linear $C = C_0 + cY_d$ (onde $C_0 > 0$ é o consumo autônomo e $c = PMgC = \\Delta C / \\Delta Y_d$, com $0 < c < 1$), a função poupança é $S = -C_0 + (1 - c)Y_d$, valendo sempre que a soma da Propensão Marginal a Consumir com a Propensão Marginal a Poupar é igual a 1 ($c + s = 1$), e a Propensão Média a Consumir ($C/Y_d = C_0/Y_d + c$) é decrescente com a renda e maior que a $PMgC$.', f: 'Na função consumo keynesiana de curto prazo com consumo autônomo positivo, a Propensão Média a Consumir é constante e igual à Propensão Marginal a Consumir.', exp: 'Como $C_0 > 0$, no curto prazo $PMeC = C_0/Y + c > c = PMgC$, e à medida que a renda $Y$ cresce, a $PMeC$ diminui.' },
    { sub: 'Multiplicador Keynesiano dos Gastos Autônomos em Economia Fechada', ref: 'Multiplicador Keynesiano', t: 'Em uma economia fechada com tributação fixa (lump-sum $T = T_0$) e investimentos/gastos autônomos, o multiplicador dos gastos autônomos (gastos do governo $\\Delta G$ ou investimento $\\Delta I$) é $k_G = 1 / (1 - c) = 1 / s$; se a tributação for proporcional à renda ($T = tY$), o multiplicador reduz-se para $k = 1 / [1 - c(1 - t)]$.', f: 'Quanto maior for a propensão marginal a poupar ($s$), maior será o multiplicador keynesiano dos gastos do governo.', exp: 'Para $c = 0{,}80$ (e $s = 0{,}20$) sem imposto proporcional, o multiplicador dos gastos é $1 / (1 - 0{,}80) = 1 / 0{,}20 = 5$. Quanto MAIOR a propensão a consumir $c$ (menor a poupança $s$), MAIOR é o multiplicador!' },
    { sub: 'Multiplicador dos Impostos ($-c / (1-c)$) e Teorema do Orçamento Equilibrado (Haavelmo)', ref: 'Teorema de Haavelmo', t: 'O multiplicador dos impostos autônomos (ou das transferências, com sinal trocado) é $k_T = -c / (1 - c)$, menor em módulo que o multiplicador dos gastos ($1 / (1-c)$); por isso, pelo Teorema do Orçamento Equilibrado de Haavelmo, se o governo aumentar os gastos públicos $\\Delta G$ e financiar 100% com aumento igual de impostos autônomos ($\\Delta G = \\Delta T$), a renda de equilíbrio aumenta no exato valor de $\\Delta G$ (multiplicador do orçamento equilibrado $= 1$)!', f: 'Se o governo aumentar seus gastos em R$ 100 bilhões e elevar os impostos autônomos nos mesmos R$ 100 bilhões, o efeito líquido sobre o PIB no modelo keynesiano simples será zero.', exp: 'Soma dos efeitos (Haavelmo): $\\Delta Y = \\frac{1}{1-c}\\Delta G - \\frac{c}{1-c}\\Delta T = \\frac{1 - c}{1 - c}\\Delta G = 1 \\cdot \\Delta G$!' },
    { sub: 'Multiplicador em Economia Aberta (Com Propensão Marginal a Importar $m$)', ref: 'Multiplicador em Economia Aberta', t: 'Em uma economia aberta onde as importações crescem com a renda interna ($M = M_0 + mY$, sendo $m$ a propensão marginal a importar), parte da demanda vaza para o exterior, reduzindo o multiplicador keynesiano para $k = 1 / [1 - c(1 - t) + m]$.', f: 'O aumento da propensão marginal a importar ($m$) amplia o multiplicador keynesiano dos gastos públicos internos.', exp: 'Vazamentos do fluxo circular da renda (poupança $s$, alíquota tributária $t$ e propensão a importar $m$) entram no denominador e REDUZEM o multiplicador!' },
    { sub: 'Paradoxo da Parcimônia (Paradoxo da Poupança de Keynes)', ref: 'Paradoxo da Parcimônia', t: 'No modelo keynesiano simples (com investimento autônomo ou dependente da renda), se todas as famílias decidirem simultaneamente poupar mais (reduzindo o consumo autônomo $C_0$), a demanda agregada e a renda de equilíbrio $Y$ cairão, de modo que, no novo equilíbrio, a poupança agregada total permanecerá inalterada (ou até cairá se o investimento depender de $Y$).', f: 'No modelo keynesiano de curto prazo com recursos ociosos, uma queda autônoma no consumo das famílias eleva imediatamente o PIB de equilíbrio.', exp: 'Na Cruz Keynesiana, como $S = I$ e $I = I_0$ é fixo, tentar poupar mais reduz o consumo $\\implies$ reduz as vendas e a renda $Y$ até que a poupança volte a ser exatamente $I_0$!' }
  ],
  11: [
    { sub: 'Funções da Moeda e Agregados Monetários ($BM, M1, M2, M3, M4$)', ref: 'Moeda e Agregados Monetários', t: 'A moeda exerce três funções clássicas: meio de troca (intermediário de trocas), unidade de conta (medida de valor) e reserva de valor (sendo o ativo de liquidez plena); os Meios de Pagamento restritos ($M1$) somam o Papel-Moeda em Poder do Público ($PMPP$) e os Depósitos à Vista nos bancos comerciais ($DV$), enquanto a Base Monetária ($BM$ ou passivo monetário do Banco Central) soma o $PMPP$ mais as Reservas Bancárias ($RB$, ou $PME + RB$).', f: 'Os depósitos de caderneta de poupança e os títulos públicos federais (Selic) integram o conceito restrito de meios de pagamento $M1$.', exp: 'Fórmulas essenciais: $M1 = PMPP + DV$ (moeda manual + moeda escritural criadas pelo BACEN e bancos comerciais); Base Monetária $BM = PMPP + RB = PME + RB$.' },
    { sub: 'Multiplicador Bancário da Base Monetária ($m = M1 / BM$)', ref: 'Multiplicador Monetário', t: 'No sistema de reservas fracionárias, os bancos comerciais multiplicam a moeda através de empréstimos que geram novos depósitos à vista; sendo $c = PMPP / M1$ (ou $d = PMPP / DV$) a retenção do público e $r = RB / DV$ a taxa de encaixe/compulsório dos bancos, o multiplicador monetário é $m = M1 / BM = 1 / [c + r(1 - c)] = (1 + d) / (d + r) > 1$.', f: 'Quando o Banco Central aumenta a alíquota do recolhimento compulsório ($r$) sobre os depósitos à vista, o multiplicador monetário aumenta.', exp: 'Qualquer aumento em $r$ (compulsório/reservas bancárias) ou na preferência do público por papel-moeda ($c$ ou $d$) REDUZ o multiplicador monetário! Se $r = 100\\%$, o multiplicador cai para $1$.' },
    { sub: 'Instrumentos Clássicos de Política Monetária do Banco Central', ref: 'Política Monetária', t: 'O Banco Central controla a oferta de moeda e a taxa de juros por três instrumentos clássicos: (1) Operações de Mercado Aberto (Open Market - compra e venda de títulos públicos, o instrumento mais ágil do dia a dia); (2) Depósitos Compulsórios (alteram o multiplicador bancário); e (3) Assistência Financeira de Liquidez (Redesconto). Para expandir a moeda, o BACEN COMPRA títulos, REDUZ o compulsório ou REDUZ a taxa de redesconto.', f: 'Para executar uma política monetária contracionista e enxugar liquidez da economia, o Banco Central deve comprar títulos públicos no mercado aberto.', exp: 'Compra de títulos pelo BACEN = injeta dinheiro no mercado (Expansionista). Venda de títulos pelo BACEN = retira dinheiro do mercado (Contracionista).' },
    { sub: 'Teoria Quantitativa da Moeda (Equação de Trocas de Fisher $MV = PY$)', ref: 'Teoria Quantitativa da Moeda', t: 'Pela Equação de Trocas ($M \\cdot V = P \\cdot Y$), assumindo no modelo clássico que a velocidade de circulação da moeda ($V$) é constante no curto prazo e que o produto real ($Y$) está fixo no pleno emprego (dicotomia clássica e neutralidade da moeda), qualquer aumento percentual na oferta de moeda ($M$) provoca aumento proporcional direto no nível geral de preços ($P$ - inflação).', f: 'Segundo a Teoria Quantitativa da Moeda clássica, aumentos na emissão de moeda elevam permanentemente o produto real sem causar inflação.', exp: 'Para os clássicos, a moeda é neutra no lado real ($Y$ é determinado pelos fatores de produção e tecnologia), logo $\\Delta\\% M = \\Delta\\% P$.' },
    { sub: 'Demanda por Moeda em Keynes (Transação, Precaução e Especulação) e Armadilha da Liquidez', ref: 'Preferência pela Liquidez', t: 'Na teoria da preferência pela liquidez de Keynes, a demanda por moeda pelos motivos transação e precaução depende positivamente da renda ($Y$), enquanto a demanda especulativa depende NEGATIVAMENTE da taxa de juros ($i$); na Armadilha da Liquidez (quando a taxa de juros já está tão baixa que todos esperam que ela suba e o preço dos títulos caia), a demanda por moeda torna-se perfeitamente elástica (horizontal), tornando a política monetária ineficaz.', f: 'Na teoria keynesiana, quando a taxa de juros sobe, o preço de mercado dos títulos prefixados também sobe e a demanda especulativa por moeda aumenta.', exp: 'O preço de um título prefixado é inversamente proporcional à taxa de juros! Se $i$ é muito alto, os títulos estão baratos $\\implies$ as pessoas compram títulos e retêm pouca moeda ociosa.' }
  ],
  12: [
    { sub: 'Curva IS (Equilíbrio no Mercado de Bens e Serviços)', ref: 'Modelo IS-LM', t: 'A curva IS representa as combinações de taxa de juros ($i$) e renda ($Y$) que equilibram o mercado de bens ($Y = C + I(i) + G$): é negativamente inclinada porque juros menores estimulam o investimento e aumentam a renda via multiplicador; políticas fiscais expansionistas ($\\uparrow G$ ou $\\downarrow T$) deslocam a IS para a DIREITA, e a IS é mais horizontal quanto maior for a sensibilidade do investimento aos juros e maior o multiplicador.', f: 'Um aumento nos gastos públicos ($\\Delta G > 0$) desloca a curva LM para a direita e mantém a curva IS parada.', exp: 'IS = Bens (Fiscal: $G, T$ deslocam a IS). LM = Moeda (Monetária: $M/P$ desloca a LM).' },
    { sub: 'Curva LM (Equilíbrio no Mercado Monetário)', ref: 'Modelo IS-LM', t: 'A curva LM representa os pares $(Y, i)$ que equilibram a oferta real de moeda ($M/P$) e a demanda por moeda ($L(Y, i)$): é positivamente inclinada porque um aumento na renda eleva a demanda transacional por moeda, exigindo juros maiores para reequilibrar o mercado monetário; uma expansão monetária ($\\uparrow M$) desloca a LM para a DIREITA (para baixo).', f: 'No trecho clássico da curva LM (quando a demanda por moeda é totalmente insensível à taxa de juros), a curva LM é horizontal.', exp: 'Casos extremos da LM: (1) Armadilha da Liquidez (Keynesiano extremo: demanda por moeda infinitamente sensível a $i$) $\\implies$ LM HORIZONTAL (Fiscal tem efeito máximo sem crowding-out, Monetária é ineficaz); (2) Caso Clássico (demanda por moeda insensível a $i$) $\\implies$ LM VERTICAL (Monetária tem efeito máximo, Fiscal sofre 100% de crowding-out)!' },
    { sub: 'Efeito Deslocamento (Crowding-Out) na Política Fiscal Expansionista', ref: 'Efeito Crowding-Out', t: 'No caso normal do modelo IS-LM (LM positivamente inclinada), quando o governo aumenta os gastos públicos ($\\uparrow G$), a curva IS desloca-se para a direita, elevando a renda $Y$; esse aumento de $Y$ eleva a demanda por moeda e faz subir a taxa de juros $i$, o que inibe (desloca/expulsa) parte do investimento privado ($\\downarrow I$), fazendo o aumento final da renda ser menor do que no multiplicador keynesiano simples.', f: 'O efeito crowding-out é máximo quando a economia se encontra na armadilha da liquidez (curva LM horizontal).', exp: 'Na LM horizontal, $i$ não sobe, logo o crowding-out é ZERO. Na LM vertical (clássica), o crowding-out é TOTAL (100%: $\\Delta I = -\\Delta G$ e $\\Delta Y = 0$).' },
    { sub: 'Modelo Mundell-Fleming (IS-LM-BP) com Perfeita Mobilidade de Capitais e Câmbio FLUTUANTE', ref: 'Mundell-Fleming - Câmbio Flutuante', t: 'Em uma pequena economia aberta com perfeita mobilidade de capitais ($BP$ horizontal em $i = i^*$) e regime de câmbio FLUTUANTE (flexível): a Política Monetária é PLENAMENTE EFICAZ (expansão monetária reduz juros $\\implies$ saída de capitais $\\implies$ desvalorização cambial $\\implies$ aumenta exportações líquidas $NX$, deslocando a IS para a direita e elevando $Y$), enquanto a Política Fiscal é TOTALMENTE INEFICAZ (eleva juros $\\implies$ entrada de capitais $\\implies$ apreciação cambial que reduz $NX$ na exata medida de $\\Delta G$, mantendo $Y$ inalterado)!', f: 'Sob câmbio flutuante e perfeita mobilidade de capitais no modelo Mundell-Fleming, a política fiscal expansionista tem eficácia máxima sobre o PIB.', exp: 'Quadro mais cobrado pela FGV em Macroeconomia Aberta (Mundell-Fleming com mobilidade perfeita de capitais): Câmbio FLUTUANTE $\\implies$ Monetária EFICAZ, Fiscal INEFICAZ!' },
    { sub: 'Modelo Mundell-Fleming (IS-LM-BP) com Perfeita Mobilidade de Capitais e Câmbio FIXO', ref: 'Mundell-Fleming - Câmbio Fixo', t: 'Em uma pequena economia aberta com perfeita mobilidade de capitais ($BP$ horizontal) e regime de câmbio FIXO: a Política Fiscal é PLENAMENTE EFICAZ (expansão fiscal pressiona $i$ para cima $\\implies$ entrada de dólares $\\implies$ para impedir a valorização da moeda, o BACEN compra dólares e expande a base monetária, deslocando a LM para a direita e aumentando $Y$), enquanto a Política Monetária é TOTALMENTE INEFICAZ (perde-se a autonomia monetária - Trilema da Economia Aberta)!', f: 'Em regime de câmbio fixo e livre mobilidade de capitais, o Banco Central possui total independência para reduzir a taxa de juros doméstica abaixo da internacional.', exp: 'Tríade Impossível (Trilema de Mundell): é impossível ter simultaneamente (1) Câmbio Fixo, (2) Livre Mobilidade de Capitais e (3) Política Monetária Autônoma! No Câmbio FIXO $\\implies$ Fiscal EFICAZ, Monetária INEFICAZ!' }
  ],
  13: [
    { sub: 'Tipos de Desemprego: Friccional, Estrutural, Cíclico e Taxa Natural (NAIRU)', ref: 'Desemprego', t: 'O desemprego friccional decorre do tempo normal de busca e transição entre empregos; o estrutural decorre de mudanças tecnológicas ou descompasso de qualificação/região; a soma do friccional com o estrutural compõe a Taxa Natural de Desemprego ($u_n$ ou NAIRU, correspondente ao produto potencial de pleno emprego), enquanto o desemprego cíclico (conjuntural) decorre de recessões (insuficiência de demanda agregada).', f: 'No pleno emprego macroeconômico (produto igual ao produto potencial), a taxa de desemprego medida pelo IBGE é igual a 0%.', exp: 'Taxa de Desemprego = Desempregados / PEA (Força de Trabalho). No pleno emprego, o desemprego cíclico é zero, mas a taxa de desemprego é positiva e igual à Taxa Natural ($u = u_n$, friccional + estrutural)! Além disso, a Lei de Okun relaciona negativamente a variação do desemprego cíclico ao crescimento do PIB real.' },
    { sub: 'Causas da Inflação: Demanda, Custos (Oferta) e Inercial', ref: 'Teorias da Inflação', t: 'A inflação de demanda ocorre quando a demanda agregada cresce acima da capacidade produtiva (economia aquecida, hiato do produto positivo); a inflação de custos (choque de oferta adverso, como alta do petróleo ou quebra de safra) desloca a Oferta Agregada para a esquerda, gerando ESTAGFLAÇÃO (inflação com queda do PIB e aumento do desemprego); e a inflação inercial decorre de mecanismos formais e informais de indexação aos índices passados.', f: 'Um choque adverso de oferta (aumento autônomo nos custos de energia) reduz a inflação e aumenta o nível de emprego no curto prazo.', exp: 'Inflação de Demanda $\\implies \\uparrow P$ e $\\uparrow Y$ (menor desemprego). Inflação de Custos / Choque de Oferta $\\implies \\uparrow P$ e $\\downarrow Y$ (Estagflação).' },
    { sub: 'Curva de Phillips Original vs. Curva de Phillips Aceleracionista (Friedman-Phelps)', ref: 'Curva de Phillips', t: 'Na Curva de Phillips aumentada pelas expectativas de Friedman e Phelps ($\\pi_t = \\pi_t^e - \\alpha(u_t - u_n)$): no curto prazo existe um trade-off negativo entre inflação não antecipada e desemprego; porém, no LONGO PRAZO, como as expectativas se ajustam ($\\pi_t = \\pi_t^e$), a taxa de desemprego retorna à Taxa Natural ($u_t = u_n$) e a Curva de Phillips de Longo Prazo é VERTICAL!', f: 'Segundo Milton Friedman, a Curva de Phillips de longo prazo é horizontal, permitindo manter o desemprego permanentemente abaixo da taxa natural com inflação constante.', exp: 'Para manter $u_t < u_n$ sob expectativas adaptativas, o governo precisaria aceitar uma inflação permanentemente crescente (aceleracionista). No longo prazo, a Curva de Phillips é VERTICAL sobre $u_n$!' },
    { sub: 'Expectativas Adaptativas vs. Expectativas Racionais (Lucas / Sargent) e Taxa de Sacrifício', ref: 'Expectativas e Desinflação', t: 'Sob expectativas adaptativas (olhando para a inflação passada), reduzir a inflação exige recessão temporária ($u_t > u_n$, gerando uma Taxa de Sacrifício positiva); já sob a hipótese de Expectativas Racionais (uso de toda a informação disponível sem erros sistemáticos), um anúncio plenamente crível de desinflação pelo Banco Central pode reduzir a inflação imediatamente sem causar recessão (taxa de sacrifício nula)!', f: 'Sob expectativas racionais e credibilidade plena do Banco Central, qualquer redução da inflação exige dez anos de desemprego elevado.', exp: 'Expectativas Adaptativas = backward-looking (inércia, taxa de sacrifício alta). Expectativas Racionais (Novo-Clássicos) = forward-looking (se há credibilidade, desinflação sem custo real).' },
    { sub: 'Senhoriagem, Imposto Inflacionário e Efeito Olivera-Tanzi', ref: 'Financiamento Monetário do Déficit', t: 'A Senhoriagem é a receita real obtida pelo governo através do monopólio de emissão de base monetária ($\\Delta M / P$); o Imposto Inflacionário é a perda de poder aquisitivo sofrida pelos detentores de moeda devido à inflação ($\\pi \\cdot M/P$); e o Efeito Olivera-Tanzi consiste na corrosão do valor real da arrecadação tributária do governo causada pela alta inflação no intervalo entre o fato gerador do tributo e o seu efetivo recolhimento aos cofres públicos.', f: 'Pelo Efeito Olivera-Tanzi, a aceleração da inflação aumenta o valor real dos impostos arrecadados sem correção monetária.', exp: 'Na alta inflação sem indexação diária dos tributos, a defasagem entre o fato gerador e o pagamento corrói a receita real do Estado (Efeito Olivera-Tanzi).' }
  ],
  14: [
    { sub: 'Estrutura do Balanço de Pagamentos (6ª Edição do Manual do FMI - BPM6)', ref: 'Balanço de Pagamentos', t: 'Segundo o padrão BPM6 adotado pelo Banco Central do Brasil, o Balanço de Pagamentos estrutura-se em três grandes contas: (1) Conta de Transações Correntes (Balança Comercial de Bens, Balança de Serviços, Renda Primária e Renda Secundária); (2) Conta Capital; e (3) Conta Financeira (Investimento Direto, Investimento em Carteira, Derivativos, Outros Investimentos e Ativos de Reserva).', f: 'Os lucros e dividendos remetidos por multinacionais ao exterior são contabilizados na Balança Comercial de Bens.', exp: 'No BPM6: (a) Bens = exportação/importação de mercadorias (FOB); (b) Serviços = viagens internacionais, fretes, seguros, royalties/propriedade intelectual, aluguel de equipamentos; (c) Renda Primária = salários de fronteiriços, juros e lucros/dividendos; (d) Renda Secundária = transferências unilaterais correntes (remessas de migrantes, doações).' },
    { sub: 'Detalhamento da Conta de Transações Correntes (Renda Primária vs. Serviços vs. Renda Secundária)', ref: 'Transações Correntes', t: 'Na Conta de Transações Correntes: os juros da dívida externa e as remessas de lucros e dividendos entram na conta de Renda Primária; os gastos de turistas brasileiros no exterior, fretes e seguros internacionais entram na Balança de Serviços; e as doações internacionais correntes e remessas pessoais de trabalhadores residentes no exterior para familiares no Brasil entram em Renda Secundária.', f: 'O pagamento de juros da dívida externa brasileira é registrado na Conta Financeira como amortização de empréstimo.', exp: 'Atenção máxima na FGV! Juros e Lucros = Renda Primária (Transações Correntes). Amortização do principal do empréstimo e ingresso de novo empréstimo/IED = Conta Financeira!' },
    { sub: 'Conta Capital vs. Conta Financeira no BPM6', ref: 'Conta Capital e Conta Financeira', t: 'Na Conta Capital registram-se as transferências de capital unilaterais (como perdão de dívida externa ou doação para obras de infraestrutura) e a compra/venda de ativos não financeiros não produzidos (como cessão definitiva de marcas, patentes ou direitos de passe de atletas); já na Conta Financeira registram-se os fluxos de ativos e passivos financeiros (Investimento Direto no País - IDP, Investimento em Carteira, Empréstimos e Variação das Reservas Internacionais).', f: 'A compra de ações na B3 por investidores estrangeiros (investimento em carteira) é registrada na Conta de Transações Correntes.', exp: 'Investimento Direto (participação duradoura $\\ge 10\\%$ do capital votante ou empréstimos intercompanhias) e Investimento em Carteira (ações $<10\\%$ e títulos de dívida) pertencem à CONTA FINANCEIRA!' },
    { sub: 'Identidade do Balanço de Pagamentos e Financiamento do Déficit em Transações Correntes', ref: 'Equilíbrio do Balanço de Pagamentos', t: 'Pelo método das partidas dobradas no BPM6 (excluídos os erros e omissões), a soma do Saldo em Transações Correntes ($STC$) com o Saldo da Conta Capital ($SCK$) equivale à Necessidade de Financiamento Externo, que é igual ao Saldo da Conta Financeira ($SCF$, definido como Aquisição Líquida de Ativos Financeiros menos Incorrência Líquida de Passivos, incluída a variação de reservas): $STC + SCK - SCF + \\text{Erros e Omissões} = 0$.', f: 'Um país que apresenta déficit em Transações Correntes está necessariamente acumulando ativos líquidos contra o resto do mundo.', exp: 'Se o país tem Déficit em Transações Correntes ($STC < 0$, poupança externa positiva), ele precisa ser financiado por entrada líquida de capitais estrangeiros (passivos na Conta Financeira, como IDP/empréstimos) ou por perda/venda de Reservas Internacionais!' },
    { sub: 'Condição de Marshall-Lerner e Curva J nas Exportações Líquidas', ref: 'Marshall-Lerner e Curva J', t: 'Pela Condição de Marshall-Lerner, uma desvalorização real da taxa de câmbio melhora o saldo da balança comercial (partindo do equilíbrio) se e somente se a soma dos módulos das elasticidades-preço da demanda por exportações e por importações for maior que 1 ($|\\varepsilon_X| + |\\varepsilon_M| > 1$); como no curtíssimo prazo as quantidades contratadas são rígidas (baixa elasticidade) e as importações ficam mais caras em moeda local, o saldo comercial primeiro piora para só depois melhorar, desenhando a chamada Curva J!', f: 'Pela Curva J, uma desvalorização cambial melhora instantaneamente a balança comercial no primeiro dia e piora no longo prazo.', exp: 'Curva J: no curtíssimo prazo (efeito preço domina efeito volume), a desvalorização piora o saldo comercial; no médio/longo prazo (volumes reagem e $|\\varepsilon_X| + |\\varepsilon_M| > 1$), o saldo comercial melhora!' }
  ],
  15: [
    { sub: 'Taxa de Câmbio Nominal ($E$) vs. Taxa de Câmbio Real ($e = E \\cdot P^* / P$)', ref: 'Câmbio Nominal e Real', t: 'Na cotação direta usada no Brasil ($E =$ preço da moeda estrangeira em moeda nacional, ex: $\\text{R\\$/US\\$}$), um aumento de $E$ significa DESVALORIZAÇÃO (depreciação) nominal do Real; a Taxa de Câmbio Real ($e = E \\cdot P^* / P$, onde $P^*$ é o nível de preços externo e $P$ o doméstico) mede a competitividade externa: uma depreciação real ($\\uparrow e$, que ocorre se $\\uparrow E$, $\\uparrow P^*$ ou $\\downarrow P$) barateia os produtos nacionais e estimula as exportações líquidas.', f: 'Se a taxa de câmbio nominal permanece fixa em R$ 5,00/US$ mas a inflação brasileira é de 15% enquanto a americana é de 2%, ocorre uma desvalorização real do Real que aumenta as exportações brasileiras.', exp: 'Cuidado! Se a inflação interna ($P$) sobe mais que a externa ($P^*$) com câmbio nominal parado, o produto brasileiro fica mais caro em dólar: $e = E \\cdot P^* / P$ CAI, ocorrendo uma APRECIAÇÃO (valorização) REAL do Real, que prejudica as exportações e estimula as importações!' },
    { sub: 'Paridade do Poder de Compra (PPC Absoluta e Relativa)', ref: 'Paridade do Poder de Compra', t: 'Pela Lei do Preço Único e pela Paridade do Poder de Compra (PPC) Absoluta, a taxa de câmbio nominal entre dois países iguala a razão entre seus níveis gerais de preços ($E = P / P^*$, de modo que o câmbio real $e = 1$); pela PPC Relativa, a variação percentual da taxa de câmbio nominal ao longo do tempo é igual ao diferencial de inflação entre o país doméstico e o exterior: $\\Delta\\% E \\approx \\pi - \\pi^*$.', f: 'Segundo a Paridade do Poder de Compra Relativa, o país que apresenta a maior taxa de inflação terá sua moeda nominalmente valorizada perante as demais.', exp: 'Pela PPC Relativa: se a inflação no Brasil é de $8\\%$ e nos EUA é de $3\\%$, o Real deve se depreciar nominalmente em cerca de $8\\% - 3\\% = 5\\%$ para manter a taxa de câmbio real constante!' },
    { sub: 'Paridade Descoberta da Taxa de Juros (UIP)', ref: 'Paridade de Juros', t: 'Pela condição de Paridade Descoberta da Taxa de Juros (arbitragem internacional de ativos com livre mobilidade de capitais e neutralidade ao risco), a taxa de juros doméstica ($i$) deve ser igual à taxa de juros internacional ($i^*$) somada à expectativa de depreciação da moeda nacional ($\\Delta E^e / E$) mais o prêmio de risco-país: $i \\approx i^* + (E^e - E)/E + \\text{Risco}$.', f: 'Pela paridade descoberta de juros, uma elevação na taxa de juros internacional ($i^*$), mantendo o resto constante, provoca apreciação imediata da moeda doméstica.', exp: 'Se a taxa de juros dos EUA ($i^*$) sobe ou o risco-país sobe, capitais saem do país emergente, provocando DEPRECIAÇÃO (desvalorização) imediata da moeda doméstica (aumento de $E$)!' },
    { sub: 'Regimes Cambiais: Fixo, Flutuante Puro, Flutuação Suja (Dirty Float) e Bandas Cambiais', ref: 'Regimes de Câmbio', t: 'No regime de Câmbio Fixo, o Banco Central compromete-se a comprar e vender moeda estrangeira a uma paridade predeterminada; no Flutuante Puro (limpo), o BACEN não intervém e o câmbio ajusta-se livremente pela oferta e demanda; já na Flutuação Suja (Dirty Float / Flutuação Administrada, adotada pelo Brasil desde 1999), o câmbio é flutuante, mas o Banco Central intervém discricionariamente (leilões de linha, swaps ou spot) para conter volatilidade excessiva, sem defender uma meta fixa de câmbio.', f: 'Desde 1999, o Brasil adota o regime de bandas cambiais fixas conjugado com conselho da moeda (currency board).', exp: 'O tripé macroeconômico brasileiro (adotado em 1999) é composto por: (1) Metas de Inflação; (2) Superávit Primário (responsabilidade fiscal); e (3) Câmbio Flutuante (com flutuação administrada/suja).' },
    { sub: 'Síntese FGV: Micro e Macroeconomia para a SEFAZ-BA', ref: 'Revisão Geral Economia FGV', t: 'Em Microeconomia: na concorrência perfeita $P = CMg$ (peso morto zero); no monopólio $P > RMg = CMg$ e o índice de Lerner é $L = (P-CMg)/P = 1/|\\varepsilon_d|$; em bens públicos puros somam-se verticalmente as demandas ($\\sum TMS = CMg$). Em Macroeconomia: $PIB_{pm} = PNB_{pm} + RLEE$; o multiplicador de orçamento equilibrado de Haavelmo é igual a $1$; e sob mobilidade perfeita de capitais (Mundell-Fleming), a política monetária é eficaz no câmbio flutuante e a política fiscal é eficaz no câmbio fixo.', f: 'No modelo Mundell-Fleming com perfeita mobilidade de capitais, a política monetária é totalmente eficaz sob câmbio fixo.', exp: 'Resumo definitivo para gabaritar Economia na FGV!' }
  ]
};
